config":["search_path=\"\"","statement_timeout=30s"],"secdef":true,"ddl_md5":"__C64_DDL_13__","language":"plpgsql","signature":"public.mission_generic_staff_republish_failed_v1(uuid,uuid,uuid)","source_md5":"e509bd418c5de7d0cb9f9c753dfae4a9","volatility":"v"},"abi":{"cost":100,"kind":"f","rows":0,"retset":false,"strict":false,"parallel":"u","leakproof":false,"return_type":"jsonb","support_oid":0,"variadic_type":0,"argument_count":3,"argument_modes":["i","i","i"],"argument_names":["p_session","p_work","p_staff"],"argument_defaults_sql":null,"argument_defaults_count":0}},{"signature":"public.regia_round_publication_state_v1(uuid,uuid)","before":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","oid":261375,"owner":"postgres","config":["search_path=\"\""],"secdef":true,"ddl_md5":"45f33b1ac2b4f6232da80032a536385f","language":"plpgsql","signature":"public.regia_round_publication_state_v1(uuid,uuid)","source_md5":"2ca0cb601abbd773f87e62ba1f2ada49","volatility":"s"},"header":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","oid":261375,"owner":"postgres","config":["search_path=\"\""],"secdef":true,"ddl_md5":"__C64_DDL_14__","language":"plpgsql","signature":"public.regia_round_publication_state_v1(uuid,uuid)","source_md5":"ee50e3d8e1d7f5a7163b10ceee977a2a","volatility":"s"},"abi":{"cost":100,"kind":"f","rows":0,"retset":false,"strict":false,"parallel":"u","leakproof":false,"return_type":"jsonb","support_oid":0,"variadic_type":0,"argument_count":2,"argument_modes":["i","i"],"argument_names":["p_master_session","p_actor"],"argument_defaults_sql":"NULL::uuid","argument_defaults_count":1}},{"signature":"combat_panel_private.commit_master_actor(jsonb)","before":{"acl":"{postgres=X/postgres}","oid":44942,"owner":"postgres","config":["search_path=\"\""],"secdef":true,"ddl_md5":"b9423acb7c77ec171ed84c99aa5b33dd","language":"plpgsql","signature":"combat_panel_private.commit_master_actor(jsonb)","source_md5":"5555a3001124b8c00f5c9b49d5b9efa7","volatility":"v"},"header":{"acl":"{postgres=X/postgres}","oid":44942,"owner":"postgres","config":["search_path=\"\""],"secdef":true,"ddl_md5":"__C64_DDL_15__","language":"plpgsql","signature":"combat_panel_private.commit_master_actor(jsonb)","source_md5":"6bda481a4db34fc3a614f3adedb5f25f","volatility":"v"},"abi":{"cost":100,"kind":"f","rows":0,"retset":false,"strict":false,"parallel":"u","leakproof":false,"return_type":"jsonb","support_oid":0,"variadic_type":0,"argument_count":1,"argument_modes":["i"],"argument_names":["p_command"],"argument_defaults_sql":null,"argument_defaults_count":0}}]$c64expected$::jsonb;params jsonb:=$c64params${"schema":"combat64-material/1","review_sha":"8c518de53f0b94eb23085cdfe687fec44c506c0fc2e5bfc10a3523f9194c019f","review_ref":"C1266_COMBAT64_REVIEW.json","p0":0,"p1":0,"p2":0,"ui_git_head":"49a9059843868c5cbdb330833455002a49559a78","assets_verified":true,"semantic":"9133e31533b60ef4362a223c841507760c0842ad1560a93278d397cc43ae0792","edge_ezbr_sha256":"1aaca3c2f4cdf7e2af47ec25d9db8838ab30d0168eea5fb3763cf5ac705e1415","edge_verified":true}$c64params$::jsonb;
BEGIN
 IF params->>'schema'<>'combat64-material/1' OR params->>'review_ref'<>'C1266_COMBAT64_REVIEW.json' OR params->'p0'<>'0'::jsonb OR params->'p1'<>'0'::jsonb OR params->'p2'<>'0'::jsonb OR coalesce(params->>'review_sha','')!~'^[a-f0-9]{64}$' OR coalesce(params->>'ui_git_head','')!~'^[a-f0-9]{40}$' OR params->'assets_verified' IS DISTINCT FROM 'true'::jsonb OR params->'edge_verified' IS DISTINCT FROM 'true'::jsonb OR coalesce(params->>'edge_ezbr_sha256','')!~'^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'C64_MATERIAL_REVIEW_REQUIRED';END IF;
 IF current_user<>'postgres' THEN RAISE EXCEPTION 'C64_OPERATOR_REQUIRED';END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('C1266:GENERIC-AI:AVAILABILITY',0)) THEN RAISE EXCEPTION 'C64_RELEASE_BUSY';END IF;
 SELECT * INTO STRICT rr FROM mission_factory_owner.editor_release_readiness WHERE singleton FOR UPDATE NOWAIT;
 IF rr.canonical_preimage IS DISTINCT FROM baseline OR rr.revision_sha256 IS DISTINCT FROM '71bb950bc0b876d560271c96003c7be8a38f1d8f207326447026355ef1eb1132' OR rr.observed_revision_sha256 IS DISTINCT FROM rr.revision_sha256 OR rr.state<>'enabled' OR rr.scope<>'staff' OR NOT rr.staff_guards_verified OR NOT rr.published_assets_verified THEN RAISE EXCEPTION 'C64_ROOT_DRIFT';END IF;
 IF NOT EXISTS(SELECT 1 FROM mission_narrative_internal.scene_runtime_v1 s JOIN public.master_v2_sessions m ON m.id=s.master_session_id WHERE m.id='c2faf883-5264-44e3-b1a2-bd9a39876942' AND m.stato='in_corso' AND m.closed_at IS NULL AND s.is_active AND s.mode='combat' AND s.current_phase_key='fase_3' AND s.state_version=3 AND s.last_publication_id='075a5472-bcff-4237-ab42-416e42d48c05') THEN RAISE EXCEPTION 'C64_SCENE_CHANGED';END IF;
 IF NOT EXISTS(SELECT 1 FROM mission_generic_owner.work_items fw JOIN public.combat_v2_round_reports rp ON rp.id=fw.authority_receipt_id WHERE fw.id='3cecb7a6-2331-45e8-bf1a-b53feb1b351a' AND fw.master_session_id='c2faf883-5264-44e3-b1a2-bd9a39876942' AND fw.state='failed' AND fw.result_sha256='9ea939ae7c788436b32107b9f7d9b6484049527fbe3855c0669e5b52ce1ddace' AND fw.result->>'failure_code'='request_validation_failed' AND fw.result->>'provider_calls'='0' AND rp.id='3a734d4a-6aa9-4ce9-a641-9ef26271df76' AND rp.values_written IS FALSE AND rp.narration_state='attesa' AND rp.message_id IS NULL AND rp.mechanics_sha256='37aba24839765b4588ccb778678225e060c53999d75ceb48ca182301fff9cdc5' AND rp.mechanics_sha256=public.combat_v2_sha256(rp.mechanics)) THEN RAISE EXCEPTION 'C64_NATIVE_WRITER_SOURCE_CHANGED';END IF;
 IF EXISTS(SELECT 1 FROM public.master_v2_sessions WHERE location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b' AND id<>'c2faf883-5264-44e3-b1a2-bd9a39876942' AND closed_at IS NULL AND stato<>'chiusa') THEN RAISE EXCEPTION 'C64_OTHER_STAFF_ACTIVE';END IF;
 SELECT jsonb_agg(jsonb_build_object('name',conname,'definition',pg_get_constraintdef(oid),'validated',convalidated,'type',contype) ORDER BY conname) INTO cons FROM pg_constraint WHERE conrelid='mission_narrative_internal.scene_sources_v1'::regclass AND conname IN('scene_sources_v1_request_kind_check','scene_sources_v1_check');
 IF cons IS DISTINCT FROM $c64constraints$[{"name":"scene_sources_v1_check","type":"c","validated":true,"definition":"CHECK ((((request_kind = 'narration'::text) AND (work_id IS NOT NULL) AND (cardinality(accepted_role_ids) > 0) AND (technical_request IS NULL) AND (board_start_receipt_id IS NULL)) OR ((request_kind = 'initial_opening'::text) AND (work_id IS NOT NULL) AND (cardinality(accepted_role_ids) = 0) AND (technical_request IS NULL) AND (board_start_receipt_id IS NOT NULL)) OR ((request_kind = 'combat_entry'::text) AND (work_id IS NULL) AND (cardinality(accepted_role_ids) = 0) AND (jsonb_typeof(technical_request) = 'object'::text))))"},{"name":"scene_sources_v1_request_kind_check","type":"c","validated":true,"definition":"CHECK ((request_kind = ANY (ARRAY['narration'::text, 'initial_opening'::text, 'combat_entry'::text])))"}]$c64constraints$::jsonb THEN RAISE EXCEPTION 'C64_CONSTRAINT_BASELINE_DRIFT';END IF;
 FOR h IN SELECT value FROM jsonb_array_elements(baseline::jsonb#>'{db_core,all_function_headers}') LOOP sig:=h->>'signature';SELECT jsonb_build_object('signature',sig,'oid',p.oid::bigint,'owner',pg_catalog.pg_get_userbyid(p.proowner),
 'acl',p.proacl::text,'config',to_jsonb(p.proconfig),'secdef',p.prosecdef,'language',l.lanname,
 'volatility',p.provolatile::text,'source_md5',pg_catalog.md5(p.prosrc),'ddl_md5',pg_catalog.md5(pg_catalog.pg_get_functiondef(p.oid)))
 INTO actual FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_language l ON l.oid=p.prolang WHERE p.oid=pg_catalog.to_regprocedure(sig);
 IF actual IS DISTINCT FROM h THEN RAISE EXCEPTION 'C64_BASELINE_HEADER_DRIFT %',sig;END IF;END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(expected) LOOP sig:=item->>'signature';SELECT jsonb_build_object('signature',sig,'oid',p.oid::bigint,'owner',pg_catalog.pg_get_userbyid(p.proowner),
 'acl',p.proacl::text,'config',to_jsonb(p.proconfig),'secdef',p.prosecdef,'language',l.lanname,
 'volatility',p.provolatile::text,'source_md5',pg_catalog.md5(p.prosrc),'ddl_md5',pg_catalog.md5(pg_catalog.pg_get_functiondef(p.oid)))
 INTO actual FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_language l ON l.oid=p.prolang WHERE p.oid=pg_catalog.to_regprocedure(sig);
 IF actual IS DISTINCT FROM nullif(item->'before','null'::jsonb) THEN RAISE EXCEPTION 'C64_TARGET_DRIFT %',sig;END IF;END LOOP;
END $c64pre$;
CREATE TEMP TABLE c64_preservation(before_data jsonb,before_combat jsonb) ON COMMIT DROP;
DO $c64capture$
DECLARE before_data jsonb; before_data_combat jsonb;
BEGIN
WITH scopes AS (SELECT unnest(ARRAY['1fb789a2-0319-435f-9f6d-dd517cac7cd3','4c7b05e0-b5b7-4586-9aa9-2a77ae03deb4','7c301c10-5a0e-42d8-92b3-cee6fc4171e6','93053f1e-7a4e-4ed9-b73c-df8bae2c361e','8281f278-c198-424f-a2b2-63b76812c1f3','c2faf883-5264-44e3-b1a2-bd9a39876942']::uuid[]) AS id), msgids AS(SELECT DISTINCT message_id FROM mission_generic_owner.work_items WHERE master_session_id IN(SELECT id FROM scopes) AND message_id IS NOT NULL)
SELECT jsonb_build_object('fati_count',(SELECT count(*) FROM public.messages WHERE id IN(SELECT message_id FROM msgids)),
 'fati_sha',(SELECT public.combat_v2_sha256(jsonb_agg(jsonb_build_object('id',id,'body',body) ORDER BY id)) FROM public.messages WHERE id IN(SELECT message_id FROM msgids)),
 'roles_sha',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(t) ORDER BY master_session_id,submission_order)) FROM mission_generic_owner.role_submissions t WHERE master_session_id IN(SELECT id FROM scopes)),
 'sessions_sha',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(t) ORDER BY id)) FROM public.master_v2_sessions t WHERE id IN(SELECT id FROM scopes)),
 'bindings_sha',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(t) ORDER BY master_session_id)) FROM mission_generic_owner.run_bindings t WHERE master_session_id IN(SELECT id FROM scopes)),
 'work_sha',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(t) ORDER BY id)) FROM mission_generic_owner.work_items t WHERE master_session_id IN(SELECT id FROM scopes)),
 'quota_sha',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(t) ORDER BY id)) FROM staff_ai_quota_private.calls t WHERE scope_id IN(SELECT id FROM scopes)),
 'scenes_sha',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(t) ORDER BY id)) FROM mission_narrative_internal.scene_runtime_v1 t WHERE master_session_id IN(SELECT id FROM scopes)),
 'gameplay_sha',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(t)-ARRAY['updated_at','last_regen_at','avatar_url','banner_url','music_url','off_notes'] ORDER BY id)) FROM public.characters t WHERE id IN('6bceee99-974f-426b-8d92-38b43b4a4267','f335b077-34a1-41c3-94aa-58ec674b649b'))) INTO before_data;

SELECT jsonb_build_object('failed_writers',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(fw) ORDER BY id)) FROM mission_generic_owner.work_items fw WHERE fw.id IN('3cecb7a6-2331-45e8-bf1a-b53feb1b351a','203b64e2-e0f3-d871-317c-0ebf87d4a697')),'reports',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(rp) ORDER BY id)) FROM public.combat_v2_round_reports rp WHERE rp.round_id IN(SELECT id FROM public.combat_v2_rounds WHERE session_id='b3135a23-78c5-4c45-a730-b1de8257367b')),'defense_publication',(SELECT public.combat_v2_sha256(to_jsonb(dm)) FROM public.messages dm WHERE dm.id='a74fdfe9-4974-44c6-b066-cdd7fe04feaa'),'rounds',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(x) ORDER BY id)) FROM public.combat_v2_rounds x WHERE session_id='b3135a23-78c5-4c45-a730-b1de8257367b'),'actors',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(x) ORDER BY id)) FROM public.combat_v2_actors x WHERE session_id='b3135a23-78c5-4c45-a730-b1de8257367b'),'declarations',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(x) ORDER BY id)) FROM public.combat_v2_declarations x WHERE round_id IN(SELECT id FROM public.combat_v2_rounds WHERE session_id='b3135a23-78c5-4c45-a730-b1de8257367b')),'events',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(x) ORDER BY event_version,event_key)) FROM mission_generic_owner.event_outbox_v1 x WHERE master_session_id='c2faf883-5264-44e3-b1a2-bd9a39876942')) INTO before_data_combat;
 INSERT INTO c64_preservation VALUES(before_data,before_data_combat);
END $c64capture$;

-- Exactly two existing source-kind constraints are extended for a real Scene5 combat-intent source.
-- No rows, prior sources, messages or reports are edited.
ALTER TABLE mission_narrative_internal.scene_sources_v1 DROP CONSTRAINT scene_sources_v1_request_kind_check;
ALTER TABLE mission_narrative_internal.scene_sources_v1 ADD CONSTRAINT scene_sources_v1_request_kind_check
 CHECK (request_kind IN('narration','initial_opening','combat_entry','combat_intent'));
ALTER TABLE mission_narrative_internal.scene_sources_v1 DROP CONSTRAINT scene_sources_v1_check;
ALTER TABLE mission_narrative_internal.scene_sources_v1 ADD CONSTRAINT scene_sources_v1_check CHECK(
 (request_kind='narration' AND work_id IS NOT NULL AND cardinality(accepted_role_ids)>0 AND technical_request IS NULL AND board_start_receipt_id IS NULL)
 OR (request_kind='initial_opening' AND work_id IS NOT NULL AND cardinality(accepted_role_ids)=0 AND technical_request IS NULL AND board_start_receipt_id IS NOT NULL)
 OR (request_kind='combat_entry' AND work_id IS NULL AND cardinality(accepted_role_ids)=0 AND jsonb_typeof(technical_request)='object')
 OR (request_kind='combat_intent' AND work_id IS NOT NULL AND cardinality(accepted_role_ids)=0 AND board_start_receipt_id IS NULL
  AND jsonb_typeof(technical_request)='object' AND technical_request->>'schema_version'='mission-native-combat-intent/1'));

CREATE OR REPLACE FUNCTION mission_narrative_internal.scene_native_declaration_public_v1(p_declaration uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO '' AS $function$
 SELECT EXISTS(SELECT 1 FROM public.combat_v2_declarations d JOIN public.combat_v2_rounds rr ON rr.id=d.round_id
 JOIN public.combat_v2_sessions cs ON cs.id=rr.session_id WHERE d.id=p_declaration AND (
 EXISTS(SELECT 1 FROM combat_consumer_private.declaration_messages dm JOIN public.messages m ON m.id=dm.message_id
  WHERE dm.declaration_id=d.id AND m.location_id=cs.location_id AND m.kind='fato' AND m.recipient_user IS NULL
   AND public._combat_narrative_sha(m.id)=dm.message_sha256)
 OR EXISTS(SELECT 1 FROM public.combat_v2_round_reports report JOIN public.messages m ON m.id=report.message_id
  JOIN public.combat_v2_narratives n ON n.report_id=report.id AND n.round_id=rr.id AND n.body=m.body AND n.kind='fato_ia'
  WHERE report.round_id=rr.id AND report.narration_state='pubblicata' AND rr.state='narrato' AND NOT report.values_written
   AND m.location_id=cs.location_id AND m.kind='fato' AND m.recipient_user IS NULL)
 OR EXISTS(SELECT 1 FROM mission_narrative_internal.scene_sources_v1 source
  JOIN mission_narrative_internal.scene_runtime_v1 cache ON cache.id=source.scene_id AND cache.master_session_id=cs.master_session_id
  JOIN mission_generic_owner.work_items w ON w.id=source.work_id AND w.message_id=source.published_message_id AND w.state='completed'
  JOIN public.messages m ON m.id=w.message_id AND m.location_id=cs.location_id AND m.kind='fato' AND m.recipient_user IS NULL
  WHERE source.request_kind='combat_intent' AND source.retired_at IS NULL AND source.technical_request->>'round_id'=rr.id::text
   AND EXISTS(SELECT 1 FROM jsonb_array_elements(source.technical_request->'intents')i WHERE i->>'declaration_id'=d.id::text))))
$function$;


CREATE OR REPLACE FUNCTION mission_narrative_internal.scene_combat_intent_source_v1(p_session uuid,p_round uuid)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO '' AS $function$
DECLARE intents jsonb; rr public.combat_v2_rounds; cs public.combat_v2_sessions; d public.combat_v2_declarations; item jsonb;
BEGIN
 PERFORM mission_ai_board_owner.service_only();
 SELECT * INTO STRICT rr FROM public.combat_v2_rounds WHERE id=p_round;
 SELECT * INTO STRICT cs FROM public.combat_v2_sessions WHERE id=rr.session_id AND master_session_id=p_session;
 IF NOT mission_narrative_internal.scene_native_round_bound_v1(p_session,p_round)
  OR rr.state NOT IN('raccolta_azioni','raccolta_difese') OR cs.closed_at IS NOT NULL
 THEN RAISE EXCEPTION 'NATIVE_INTENT_SCOPE' USING ERRCODE='42501';END IF;
 intents:='[]'::jsonb;
 FOR d IN SELECT dd.* FROM public.combat_v2_declarations dd JOIN public.combat_v2_actors a ON a.id=dd.actor_id
  WHERE dd.round_id=p_round AND a.actor_kind='png' AND dd.kind IN('attacco','movimento','utilita','passa','difesa','nessuna') AND NOT(dd.kind='nessuna' AND coalesce(dd.declaration_text,'')='') AND NOT mission_narrative_internal.scene_native_declaration_public_v1(dd.id) ORDER BY dd.id LOOP
  SELECT jsonb_build_object('declaration_id',d.id,'actor_id',d.actor_id,'target_actor_id',d.target_actor_id,
   'actor_key',(SELECT map->>'actor_key' FROM mission_generic_owner.encounters e CROSS JOIN LATERAL jsonb_array_elements(e.actor_map)map WHERE e.encounter_id=cs.id AND map->>'actor_id'=d.actor_id::text),
   'target_character_id',(SELECT character_id FROM public.combat_v2_actors WHERE id=d.target_actor_id),
   'target_actor_key',(SELECT map->>'actor_key' FROM mission_generic_owner.encounters e CROSS JOIN LATERAL jsonb_array_elements(e.actor_map)map WHERE e.encounter_id=cs.id AND map->>'actor_id'=d.target_actor_id::text),
   'kind',d.kind,'body',d.declaration_text,'declaration_state',d.state,'position_m',aa.position_m,'choice_work_id',wi.id,'request_key',d.request_key,
   'command_sha256',pc.command_sha256,'receipt_sha256',public.combat_v2_sha256(q.viewer_envelope)) INTO item
  FROM mission_generic_owner.panel_choices pc JOIN mission_generic_owner.work_items wi ON wi.id=pc.work_id
  JOIN combat_panel_private.request_receipts q ON q.principal_user=pc.principal_id AND q.request_key=pc.request_key
  JOIN mission_narrative_internal.dispatch_audit da ON da.receipt_id=wi.dispatch_receipt_id AND da.event_code='generic_finalized'
  JOIN public.combat_v2_actors aa ON aa.id=pc.actor_id AND aa.session_id=pc.encounter_id
  WHERE pc.master_session_id=p_session AND pc.encounter_id=cs.id AND pc.actor_id=d.actor_id
   AND pc.request_key=d.request_key AND pc.consumed_at IS NOT NULL AND pc.result=q.viewer_envelope
   AND pc.command_sha256=q.command_fingerprint AND pc.controller_version=d.controller_version_snapshot
   AND pc.principal_id=d.controller_user_snapshot AND aa.controller_version=pc.controller_version
   AND q.viewer_envelope#>>'{receipt,declaration_id}'=d.id::text
   AND wi.kind='choice' AND wi.state='completed' AND wi.master_session_id=p_session
   AND wi.result#>>'{command,narrative_text}'=d.declaration_text
   AND da.details->>'result_sha256'=wi.result_sha256 AND da.details->>'result_jsonb_sha256'=public.combat_v2_sha256(wi.result)
   AND NOT EXISTS(SELECT 1 FROM combat_consumer_private.declaration_messages dm WHERE dm.declaration_id=d.id);
  IF item IS NULL THEN RAISE EXCEPTION 'NATIVE_INTENT_RECEIPT' USING ERRCODE='PT409';END IF;
  intents:=intents||jsonb_build_array(item);
 END LOOP;
 IF jsonb_array_length(intents)=0 THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('schema_version','mission-native-combat-intent/1','encounter_id',cs.id,'round_id',rr.id,'intents',intents);
END $function$;


CREATE OR REPLACE FUNCTION mission_narrative_internal.scene_combat_intent_prepare_v1(p_session uuid,p_round uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$
DECLARE r mission_narrative_internal.scene_runtime_v1;run public.mission_run_state;b mission_generic_owner.run_bindings;
 src mission_narrative_internal.scene_sources_v1;root mission_generic_owner.event_outbox_v1;
 intent jsonb;payload jsonb;sha text;wid uuid;sid uuid;cfg jsonb;eventkey uuid;req jsonb;wake bigint;
BEGIN
 PERFORM mission_ai_board_owner.service_only();
 PERFORM 1 FROM public.locations WHERE id=(SELECT location_id FROM public.master_v2_sessions WHERE id=p_session) FOR UPDATE;
 PERFORM 1 FROM mission_generic_owner.role_window_cursors WHERE master_session_id=p_session FOR UPDATE;
 SELECT * INTO STRICT r FROM mission_narrative_internal.scene_runtime_v1 WHERE master_session_id=p_session FOR UPDATE;
 SELECT * INTO STRICT run FROM public.mission_run_state WHERE master_session_id=p_session FOR UPDATE;
 SELECT * INTO STRICT b FROM mission_generic_owner.run_bindings WHERE master_session_id=p_session;
 IF NOT r.is_active OR r.mode<>'combat' THEN RETURN NULL;END IF;
 intent:=mission_narrative_internal.scene_combat_intent_source_v1(p_session,p_round);
 IF intent IS NULL THEN RETURN NULL;END IF;
 IF EXISTS(SELECT 1 FROM mission_narrative_internal.scene_sources_v1 prior WHERE prior.scene_id=r.id
  AND prior.request_kind='combat_intent' AND prior.retired_at IS NULL AND prior.technical_request=intent
  AND prior.published_message_id IS NOT NULL) THEN RETURN NULL;END IF;
 SELECT * INTO src FROM mission_narrative_internal.scene_sources_v1 WHERE scene_id=r.id
  AND retired_at IS NULL AND published_message_id IS NULL AND technical_receipt IS NULL;
 IF FOUND THEN RETURN jsonb_build_object('state','narration_ready','work_id',src.work_id,'replayed',true);END IF;
 IF r.turn_owner<>'combat' THEN RAISE EXCEPTION 'NATIVE_INTENT_TURN_OWNER' USING ERRCODE='PT409';END IF;
 sha:=public.combat_v2_sha256(jsonb_build_object('scene_id',r.id,'state_version',r.state_version,
  'snapshot_sha256',r.snapshot_sha256,'phase',r.current_phase_key,'combat_intent',intent,
  'last_publication_id',r.last_publication_id,'last_publication_sha256',r.last_publication_sha256,'scene_memory',r.scene_memory));
 sid:=mission_ai_service_owner.uuid5(r.id,'combat-intent-source:'||sha);wid:=mission_ai_service_owner.uuid5(sid,'narrative-work');
 payload:=jsonb_build_object('schema_version','mission-narrative-scene/1','mode','narrative_scene',
  'scene_id',r.id,'source_window_id',sid,'source_revision',sha,'state_version',r.state_version,
  'snapshot_sha256',r.snapshot_sha256,'snapshot',r.snapshot,'current_phase_key',r.current_phase_key,
  'scene_memory',r.scene_memory,'accepted_roles','[]'::jsonb,'last_publication',jsonb_build_object(
  'message_id',r.last_publication_id,'body_sha256',r.last_publication_sha256),'last_fati',r.last_fati,'combat_intent',intent);
 SELECT * INTO STRICT root FROM mission_generic_owner.event_outbox_v1 WHERE master_session_id=p_session AND event_domain='start' AND event_version=1;
 INSERT INTO mission_narrative_internal.scene_sources_v1(id,scene_id,work_id,actor_user_id,state_version,source_revision,
 snapshot_sha256,accepted_role_ids,accepted_roles_sha256,last_publication_id,last_publication_sha256,current_phase_key,scene_memory_sha256,payload_sha256,request_kind,technical_request)
 VALUES(sid,r.id,wid,root.root_principal,r.state_version,sha,r.snapshot_sha256,'{}'::uuid[],public.combat_v2_sha256('[]'::jsonb),
 r.last_publication_id,r.last_publication_sha256,r.current_phase_key,public.combat_v2_sha256(coalesce(r.scene_memory,'null'::jsonb)),public.combat_v2_sha256(payload),'combat_intent',intent);
 INSERT INTO mission_generic_owner.work_items(id,master_session_id,event_id,dedupe_key,step_key,run_control_version,definition_sha256,authority_receipt_id,kind,revision,payload,payload_sha256)
 VALUES(wid,p_session,sid,'narrative:'||sid,run.current_step_key,run.control_version,b.snapshot_sha256,sid,'narration',run.control_version,payload,public.combat_v2_sha256(payload));
 UPDATE mission_narrative_internal.scene_runtime_v1 SET turn_owner='fato',updated_at=clock_timestamp() WHERE id=r.id;
 PERFORM mission_public_owner.work_contract_issue_v1(wid);
 SELECT canonical_preimage::jsonb#>'{config,c1266_server_events}' INTO cfg FROM mission_factory_owner.editor_release_readiness WHERE singleton AND state='enabled' AND scope='staff' AND revision_sha256=observed_revision_sha256;
 IF cfg->>'schema_version' IS DISTINCT FROM 'c1266-server-events/1' OR cfg->'enabled' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'NATIVE_INTENT_WAKE_SCOPE' USING ERRCODE='42501';END IF;
 req:=jsonb_build_object('schema_version','mission-generic-request/1','master_session_id',p_session,'event_id',sid,
 'request_key',(SELECT request_key FROM mission_generic_owner.work_items WHERE id=wid),'expected_revision',run.control_version);
 eventkey:=mission_ai_service_owner.uuid5(wid,'server-event:writer-ready');
 INSERT INTO mission_generic_owner.event_outbox_v1(event_key,event_version,master_session_id,event_domain,source_id,source_sha256,root_event_key,root_request_key,root_principal,root_receipt_sha256,work_id,canonical_request)
 VALUES(eventkey,1,p_session,'writer_ready',wid,public.combat_v2_sha256(payload),root.root_event_key,root.root_request_key,root.root_principal,root.root_receipt_sha256,wid,req);
 wake:=net.http_post(cfg->>'endpoint',jsonb_build_object('schema_version','mission-event-wake/2','event_key',eventkey,'event_version',1),'{}'::jsonb,jsonb_build_object('Content-Type','application/json','x-tus-server-event','event42'),5000);
 UPDATE mission_generic_owner.event_outbox_v1 SET wake_request_id=wake WHERE event_key=eventkey AND event_version=1;
 RETURN jsonb_build_object('state','narration_ready','work_id',wid,'replayed',false);
END $function$;


CREATE OR REPLACE FUNCTION combat_panel_private.master_projection(p_location uuid, p_actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE multiplication jsonb; src jsonb; c combat_panel_private.contexts%ROWTYPE; sid uuid; mid uuid; rid uuid; actor uuid;
 is_master boolean; is_admin boolean; is_test boolean; simulated boolean; policy text; phase text; phase_label text;
 controlled jsonb:='[]'; roster jsonb:='[]'; item jsonb; resources jsonb; map_view jsonb:=null;
 companion_view jsonb:=null; sabaku_view jsonb:=null; narrative_view jsonb:=null; narrative_meta jsonb; meta public.combat_v2_actors%ROWTYPE;
 actor_state text; distance numeric; body_only boolean; due boolean; selected boolean;
BEGIN
 src:=public.master_v2_ui_state(p_location)->'data';
 IF src->>'publication_state'='pending' AND src->>'reason_code'='REGIA_FATO_PENDING' THEN
  RETURN jsonb_build_object('schema_version','combat-panel/1','status','blocked','reason_code','REGIA_FATO_PENDING',
   'context',NULL,'viewer',jsonb_build_object('command_actor_id',NULL,'controlled_actors','[]'::jsonb,
    'is_master',false,'is_admin',coalesce((src#>>'{viewer,is_admin}')::boolean,false),'can_command',false),
   'actors','[]'::jsonb,'map',NULL,'offers','[]'::jsonb,'movement_explanations',NULL,'companion',NULL,
   'sabaku_transport',NULL,'aburame_colony',NULL,'multiplication',NULL,'narrative',NULL,'receipt',NULL,'round_details',NULL);
 END IF;
 is_master:=coalesce((src#>>'{viewer,is_master}')::boolean,false);
 is_admin:=coalesce((src#>>'{viewer,is_admin}')::boolean,false);
 mid:=(src#>>'{master,id}')::uuid;
 IF mid IS NULL THEN is_master:=coalesce(public.master_v2_is_master(exam_regia_private.current_principal()),false); END IF; sid:=(src#>>'{encounter,id}')::uuid; rid:=(src#>>'{round,id}')::uuid;
 SELECT coalesce(l.is_test,false) INTO is_test FROM public.locations l WHERE l.id=p_location AND l.is_active;
 IF NOT FOUND THEN RAISE EXCEPTION 'panel_location_not_available' USING ERRCODE='42501'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(src->'actors') LOOP
   IF coalesce((item->>'mine')::boolean,false) AND EXISTS(SELECT 1 FROM public.combat_v2_actors
     WHERE id=(item->>'id')::uuid AND session_id=sid AND exam_regia_private.actor_principal(id,controller_user)=exam_regia_private.current_principal() AND companion_id IS NULL) THEN
     controlled:=controlled||jsonb_build_array(jsonb_build_object('actor_id',item->'id','label',item->'name'));
   END IF;
 END LOOP;
 actor:=p_actor;
 IF actor IS NULL AND NOT(is_master OR is_admin) AND jsonb_array_length(controlled)>0 THEN
   actor:=(controlled#>>'{0,actor_id}')::uuid;
 END IF;
 IF actor IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(controlled) AS a(value)
   WHERE value->>'actor_id'=actor::text) THEN
   RAISE EXCEPTION 'panel_actor_not_controlled' USING ERRCODE='42501'; END IF;
 phase:=CASE WHEN src#>>'{master,stato}'='sospesa' OR src#>>'{encounter,state}'='sospeso' THEN 'suspended'
   WHEN sid IS NULL OR rid IS NULL THEN 'setup'
   WHEN NOT EXISTS(SELECT 1 FROM combat_spatial.arena_instances WHERE encounter_id=sid)
     AND NOT EXISTS(SELECT 1 FROM public.combat_v2_declarations d JOIN public.combat_v2_rounds r ON r.id=d.round_id WHERE r.session_id=sid) THEN 'setup'
   ELSE CASE src#>>'{round,phase}' WHEN 'raccolta_azioni' THEN 'action' WHEN 'raccolta_difese' THEN 'defense'
     WHEN 'congelato' THEN 'review' WHEN 'valutazione' THEN 'review' WHEN 'risoluzione' THEN 'resolving'
     WHEN 'risolto' THEN 'resolved' WHEN 'narrazione' THEN 'resolved' WHEN 'narrato' THEN 'resolved' ELSE NULL END END;
 IF phase IS NULL THEN RAISE EXCEPTION 'panel_master_phase_unsupported' USING ERRCODE='22023'; END IF;
 phase_label:=CASE phase WHEN 'setup' THEN 'Preparazione dello scontro' WHEN 'action' THEN 'Raccolta delle azioni'
   WHEN 'defense' THEN 'Raccolta delle difese' WHEN 'review' THEN 'Valutazione del Master'
   WHEN 'resolving' THEN 'Risoluzione in corso' WHEN 'resolved' THEN 'Esito del round' ELSE 'Scontro sospeso' END;
 IF rid IS NOT NULL AND combat_panel_private.human_duel_round(rid) THEN
   phase_label:=CASE phase WHEN 'action' THEN 'Duello a iniziativa · turno di attacco'
     WHEN 'defense' THEN 'Duello a iniziativa · risposta difensiva' ELSE phase_label END;
 END IF;
 simulated:=CASE WHEN sid IS NULL THEN is_test ELSE NOT public.combat_v2_values_written(sid) END;
 policy:=CASE WHEN exam_human_private.execution_session_v1(mid) THEN 'exam_protected_no_persistent_resources_v1' WHEN exam_regia_private.is_bound(sid) THEN 'exam_protected_no_persistent_resources_v1' WHEN is_test THEN 'staff_test_no_persistent_resources_v1' ELSE 'master_game_resources_v1' END;
 IF sid IS NOT NULL AND (actor IS NOT NULL OR is_master OR is_admin) THEN
   map_view:=combat_panel_private.master_map(sid,actor);
 END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(src->'actors') LOOP
   SELECT * INTO STRICT meta FROM public.combat_v2_actors WHERE id=(item->>'id')::uuid AND session_id=sid;
   body_only:=meta.companion_id IS NOT NULL;
   actor_state:=CASE item->>'state' WHEN 'attivo' THEN 'active' WHEN 'fuori' THEN 'out' WHEN 'ritirato' THEN 'withdrawn' ELSE NULL END;
   IF actor_state IS NULL THEN RAISE EXCEPTION 'panel_actor_state_unsupported' USING ERRCODE='22023'; END IF;
   selected:=actor IS NOT NULL AND meta.id=actor;
   resources:=combat_panel_private.participant_resources(sid,meta.id,simulated);
   distance:=NULL;
   IF jsonb_typeof(map_view->'pov')='object' AND NOT selected THEN
     SELECT round(combat_spatial.distance_m((map_view#>>'{pov,x_m}')::numeric,(map_view#>>'{pov,y_m}')::numeric,
       (value->>'x_m')::numeric,(value->>'y_m')::numeric),2) INTO distance
       FROM jsonb_array_elements(map_view->'actors') WHERE value->>'actor_id'=meta.id::text;
   END IF;
   -- Il compagno resta passivo: risponde il controllore tramite le stesse
   -- difese ammesse dal consumer, anche con Fili recisi (Nessuna difesa).
   due:=NOT body_only AND actor_state='active' AND phase='defense'
     AND (is_master OR is_admin OR exam_regia_private.actor_principal(meta.id,meta.controller_user)=exam_regia_private.current_principal())
     AND NOT EXISTS(SELECT 1 FROM public.combat_v2_declarations d
       WHERE d.round_id=rid AND d.actor_id=meta.id AND d.kind IN ('difesa','nessuna'))
     AND EXISTS(SELECT 1 FROM public.combat_v2_attack_targets t
       WHERE t.round_id=rid AND t.state='attesa_difesa' AND (
         t.target_actor_id=meta.id OR (
           EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(map_view->'actors','[]')) v
             WHERE v->>'actor_id'=t.target_actor_id::text)
           AND clan_marionettisti_private.defends_body(meta.id,t.target_actor_id,'nessuna'))));
   roster:=roster||jsonb_build_array(jsonb_build_object('actor_id',meta.id,
     'kind',CASE WHEN body_only THEN 'companion' ELSE meta.actor_kind END,'body_only',body_only,
     'display_name',CASE WHEN body_only THEN to_jsonb('Marionetta'::text) ELSE item->'name' END,'team',item->'team','state',actor_state,'mine',selected,
     'action_due',NOT body_only AND actor_state='active' AND phase='action' AND combat_panel_private.human_duel_turn_allowed(rid,meta.id) AND mission_generic_owner.unified_turn_allowed(rid,meta.id) AND NOT coalesce((item->>'has_action')::boolean,false),
     'defense_due',due,'resources',resources,'distance_from_viewer_m',distance));
 END LOOP;
 IF sid IS NOT NULL AND rid IS NOT NULL THEN
   narrative_meta:=combat_panel_private.narrative_details(p_location,sid,rid);
   narrative_view:=jsonb_build_object('schema_version','combat-panel-narrative/1','activity_id',sid,'round_id',rid,
     'mode','human','state',CASE WHEN narrative_meta#>>'{last_published,round_id}'=rid::text THEN 'published'
       WHEN phase='resolved' THEN 'waiting' ELSE 'idle' END,'reason_code',null,
     'report_id',narrative_meta->'report_id','report_sha256',narrative_meta->'report_sha256',
     'last_published',narrative_meta->'last_published');
 END IF;
 multiplication:=combat_panel_private.multiplication_view(p_location,map_view->'actors');
 map_view:=combat_panel_private.multiplication_mask_map(map_view,multiplication);
 roster:=combat_panel_private.multiplication_mask_roster(roster,multiplication);
 -- Versione fissa per il fingerprint: non dipende dalla versione che genera.
 companion_view:=combat_panel_private.master_companion_projection(actor);
 sabaku_view:=clan_sabaku_private.master_panel_projection(actor,1);
 c:=combat_panel_private.refresh_context(p_location,actor,
   CASE WHEN coalesce(sid,mid) IS NULL THEN NULL ELSE 'master_v2' END,coalesce(sid,mid),rid,
   (map_view->>'map_version')::bigint,jsonb_build_object('participant_resources',roster,'multiplication',multiplication,'is_master',is_master,'is_admin',is_admin,'source',src,'map',map_view,'narrative',narrative_view,'sabaku',sabaku_view,'companion',companion_view,
     -- Stato nativo stabile: il preset cambia le offerte senza consumare una principale.
     -- Solo fingerprint interno; nessun dato aggiunto alla risposta del viewer.
     'other_control_state',(SELECT coalesce(jsonb_agg(jsonb_build_object('technique_id',z.technique_id,'controller_version',z.controller_version,'receipt_sha256',z.receipt_sha256) ORDER BY z.technique_id,z.controller_version),'[]'::jsonb) FROM combat_v2_elemental_internal.other_staff_receipts z WHERE z.actor_id=actor AND z.session_id=sid),
     'suiton_control_state',(SELECT coalesce(jsonb_agg(jsonb_build_object(
       'technique_id',s.technique_id,'controller_version',s.controller_version,'receipt_sha256',s.receipt_sha256)
       ORDER BY s.technique_id,s.controller_version),'[]'::jsonb)
       FROM combat_v2_elemental_internal.suiton_staff_receipts s WHERE s.actor_id=actor AND s.session_id=sid),
     'scudo_control_state',(SELECT coalesce(jsonb_agg(jsonb_build_object(
       'technique_id',s.technique_id,'controller_version',s.controller_version,'receipt_sha256',s.receipt_sha256) ORDER BY s.technique_id,s.controller_version),'[]'::jsonb) FROM combat_v2_elemental_internal.scudo_staff_receipts s WHERE s.actor_id=actor AND s.session_id=sid),
     'hyuga_control_state',jsonb_build_object(
       'profiles',(SELECT coalesce(jsonb_agg(jsonb_build_object('profile_version',h.profile_version,'active',h.is_active)
           ORDER BY h.profile_version,h.is_active,h.created_request),'[]'::jsonb)
         FROM clan_hyuga_private.staff_profiles h WHERE h.actor_id=actor AND h.session_id=sid),
       'offensive_receipts',(SELECT count(*) FROM clan_hyuga_private.offensive_staff_receipts h
         WHERE h.actor_id=actor AND h.session_id=sid),
       'byakugan',(SELECT jsonb_build_object('active',h.active,'state_version',h.state_version)
         FROM clan_innata_combat_private.combat_state h WHERE h.actor_id=actor AND h.session_id=sid
           AND h.technique_id='4a527ff2-0420-4da9-bc1f-5489c753b285'::uuid))));
 RETURN clan_inuzuka_private.master_projection(clan_sabaku_private.clone_attach_map(jsonb_build_object('schema_version','combat-panel/1','status','ready','reason_code',null,
   'context',jsonb_build_object('activity_id',coalesce(sid,mid),'activity_kind',c.activity_kind,
     'location_id',p_location,'round_id',rid,'round_no',to_jsonb(exam_regia_private.logical_round_no(rid)),'phase',phase,'phase_label',phase_label,
     'version',c.context_version,'scene_version',c.scene_version,'policy_id',policy,'simulated',simulated),
   'viewer',jsonb_build_object('command_actor_id',actor,'controlled_actors',controlled,'is_master',is_master,
     'is_admin',is_admin,'can_command',is_master OR is_admin OR (actor IS NOT NULL AND (phase='defense' OR (phase='action' AND combat_panel_private.human_duel_turn_allowed(rid,actor) AND mission_generic_owner.unified_turn_allowed(rid,actor))))),
   'actors',roster,'map',map_view,'offers','[]'::jsonb,'movement_explanations',null,
   'multiplication',multiplication,'companion',companion_view,'sabaku_transport',CASE WHEN sabaku_view IS NULL THEN NULL
     ELSE jsonb_set(sabaku_view,'{context_version}',to_jsonb(c.context_version)) END,'narrative',narrative_view,
   'round_details',combat_panel_private.round_details_from_source(src,roster),'receipt',null)));
END $function$;


CREATE OR REPLACE FUNCTION combat_panel_private.master_state_authoritative(p_location uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=exam_regia_private.current_principal();
  v_m public.master_v2_sessions%rowtype;
  v_s public.combat_v2_sessions%rowtype;
  v_r public.combat_v2_rounds%rowtype;
  v_is_admin boolean:=false;
  v_is_master boolean:=false;
  v_is_participant boolean:=false;
begin
  if v_uid is null then
    perform public.combat_v2_fail('autenticazione_richiesta','Autenticazione richiesta.',401,null,'{}');
  end if;

  select * into v_m
    from public.master_v2_sessions
   where location_id=p_location and stato not in ('chiusa','annullata')
   order by created_at desc limit 1;

  if v_m.id is null then
    return public.combat_v2_envelope(null,jsonb_build_object(
      'viewer',jsonb_build_object('is_master',false,'is_admin',public.combat_v2_is_admin(v_uid)),
      'master',null,'encounter',null,'actors','[]'::jsonb,'round',null,
      'declarations','[]'::jsonb,'pending_defenses','[]'::jsonb,
      'ratings_pending','[]'::jsonb,'report',null));
  end if;

  v_is_admin:=public.combat_v2_is_admin(v_uid);
  v_is_master:=coalesce(v_m.master_user=v_uid,false);
  select exists(
    select 1 from public.master_v2_participants p
     where p.session_id=v_m.id and p.user_id_snapshot=v_uid
       and p.engagement_state in ('attivo','sospeso')
  ) into v_is_participant;

  v_is_participant:=v_is_participant OR EXISTS(SELECT 1 FROM exam_regia_private.bindings b
 WHERE b.master_session_id=v_m.id AND b.service_principal_id=v_uid AND b.state<>'closed'
 AND v_uid=exam_regia_private.current_principal());
  v_is_participant:=v_is_participant OR mission_generic_owner.principal_in_session(v_m.id,v_uid);
  if not (v_is_master or v_is_admin or v_is_participant) then
    perform public.combat_v2_fail('master_non_proprietario','Sessione non accessibile.',403,null,'{}');
  end if;

  select * into v_s
    from public.combat_v2_sessions
   where master_session_id=v_m.id and state not in ('chiuso','annullato')
   order by created_at desc limit 1;

  if v_s.id is not null then
    select * into v_r
      from public.combat_v2_rounds
     where session_id=v_s.id
     order by round_no desc limit 1;
  end if;

  IF v_r.id IS NOT NULL AND NOT v_is_master AND NOT public.combat_v2_is_service()
   AND mission_narrative_internal.scene_native_round_bound_v1(v_m.id,v_r.id)
   AND (EXISTS(SELECT 1 FROM mission_narrative_internal.scene_runtime_v1 cache
      WHERE cache.master_session_id=v_m.id AND cache.is_active AND cache.turn_owner='fato')
    OR (v_r.state IN('congelato','valutazione','risoluzione','risolto','narrazione')
      AND NOT EXISTS(SELECT 1 FROM public.combat_v2_round_reports report JOIN public.messages published ON published.id=report.message_id
       WHERE report.id=v_r.report_id AND report.round_id=v_r.id AND report.narration_state='pubblicata'
        AND published.kind='fato' AND published.location_id=p_location AND published.recipient_user IS NULL))
    OR EXISTS(SELECT 1 FROM public.combat_v2_declarations pending
      JOIN public.combat_v2_actors png ON png.id=pending.actor_id AND png.actor_kind='png'
      WHERE pending.round_id=v_r.id AND NOT(pending.kind='nessuna' AND coalesce(pending.declaration_text,'')='')
       AND NOT mission_narrative_internal.scene_native_declaration_public_v1(pending.id)))
  THEN
   -- No attested public snapshot of this frame exists: use a typed empty pending
   -- transport rather than expose current PV, positions, action flags or outcomes.
   RETURN public.combat_v2_envelope(NULL,jsonb_build_object(
    'publication_state','pending','reason_code','REGIA_FATO_PENDING',
    'viewer',jsonb_build_object('is_master',false,'is_admin',v_is_admin),
    'master',NULL,'encounter',NULL,'actors','[]'::jsonb,'round',NULL,
    'declarations','[]'::jsonb,'pending_defenses','[]'::jsonb,'ratings_pending','[]'::jsonb,'report',NULL));
  END IF;
  IF v_r.id IS NOT NULL AND NOT v_is_master AND EXISTS(SELECT 1 FROM mission_generic_owner.regia_human_admissions_v1 adm WHERE adm.encounter_id=v_s.id)
   AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.unified_round_windows uw WHERE uw.round_id=v_r.id AND uw.publication_id IS NOT NULL) THEN
    SELECT vr.* INTO v_r FROM public.combat_v2_rounds vr JOIN mission_generic_owner.unified_round_windows uw ON uw.round_id=vr.id
     WHERE vr.session_id=v_s.id AND uw.publication_id IS NOT NULL ORDER BY vr.round_no DESC LIMIT 1;
    IF v_r.id IS NULL THEN v_s:=NULL; END IF;
  END IF;
  IF v_r.id IS NOT NULL AND EXISTS(SELECT 1 FROM mission_generic_owner.unified_round_windows uw WHERE uw.round_id=v_r.id AND uw.publication_id IS NULL)
    AND NOT mission_generic_owner.unified_service_staging(v_r.id)
    AND NOT (v_is_master AND EXISTS(
      SELECT 1 FROM mission_generic_owner.regia_human_windows_v1 hw
      WHERE hw.next_round_id=v_r.id AND hw.master_session_id=v_m.id
        AND hw.state='private')) THEN
    SELECT vr.* INTO v_r FROM public.combat_v2_rounds vr JOIN mission_generic_owner.unified_round_windows uw ON uw.round_id=vr.id
    WHERE vr.session_id=v_s.id AND uw.publication_id IS NOT NULL ORDER BY vr.round_no DESC LIMIT 1;
    IF v_r.id IS NULL THEN v_s:=NULL; END IF;
  END IF;
  -- The human Master may inspect the private successor. Everyone else sees
  -- only the last published round; opening PNG has no public Combat yet.
  IF v_r.id IS NOT NULL AND NOT v_is_master
    AND EXISTS(SELECT 1 FROM exam_human_private.round_publication_windows_v1 w
      WHERE (w.next_round_id=v_r.id OR (w.side='terminal' AND w.source_round_id=v_r.id))
        AND w.state<>'published') THEN
    SELECT vr.* INTO v_r FROM public.combat_v2_rounds vr
      JOIN exam_human_private.round_publication_windows_v1 w ON w.next_round_id=vr.id
      WHERE vr.session_id=v_s.id AND w.state='published' AND vr.state='narrato'
      ORDER BY vr.round_no DESC LIMIT 1;
    IF v_r.id IS NULL THEN v_s:=NULL; END IF;
  END IF;
  return public.combat_v2_envelope(null,jsonb_build_object(
    'unified_publication_id',(SELECT uw.publication_id FROM mission_generic_owner.unified_round_windows uw WHERE uw.round_id=v_r.id),
    'viewer',jsonb_build_object(
      'is_master',v_is_master,
      'is_admin',v_is_admin,
      'is_participant',v_is_participant),
    'master',jsonb_build_object(
      'id',v_m.id,'location_id',v_m.location_id,'tipo',v_m.tipo,
      'stato',v_m.stato,
      'control_version',v_m.control_version,'mission_id',v_m.mission_id,
      'titolo',v_m.titolo,'suspended_at',v_m.suspended_at),
    'encounter',case when v_s.id is null then null else jsonb_build_object(
      'id',v_s.id,'state',v_s.state,'source_kind',v_s.source_kind,
      'location_id',v_s.location_id,'lesiva',v_s.lesiva) end,
    'actors',case when v_s.id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',a.id,
        'kind',a.actor_kind,
        'name',coalesce(c.name,p.nome,pi.nome,'Attore'),
        'character_id',a.character_id,
        'team',a.team_key,
        'state',a.state,
        'position_m',a.position_m,
        'initiative',a.initiative_snapshot,
        'mine',exam_regia_private.actor_principal(a.id,a.controller_user)=v_uid,
        'has_action',exists(
          select 1 from public.combat_v2_declarations d
           where d.round_id=v_r.id and d.actor_id=a.id
             and d.kind in ('attacco','movimento','utilita','passa')),
        'reaction_used',exists(
          select 1 from public.combat_v2_declarations d
           join public.combat_v2_declarations x on x.id=d.parent_attack_id
           where d.round_id=v_r.id and d.kind='difesa'
             and x.target_actor_id=a.id),
        'resources',case when v_is_master or v_is_admin or exam_regia_private.actor_principal(a.id,a.controller_user)=v_uid
          then jsonb_build_object(
            'vita',a.mechanics_snapshot->'vita',
            'vita_max',a.mechanics_snapshot->'vita_max',
            'chakra',a.mechanics_snapshot->'chakra',
            'chakra_max',a.mechanics_snapshot->'chakra_max')
          else null end
      ) order by a.initiative_snapshot desc,a.id)
      from public.combat_v2_actors a
      left join public.characters c on c.id=a.character_id
      left join public.combat_v2_png_instances p on p.id=a.png_instance_id left join public.combat_v2_provider_instances_v1 pi on pi.id=a.provider_instance_v1_id
      where a.session_id=v_s.id
    ),'[]'::jsonb) end,
    'round',case when v_r.id is null then null else jsonb_build_object(
      'id',v_r.id,'no',v_r.round_no,'phase',v_r.phase,'state',v_r.state,
      'evaluation_mode',v_r.evaluation_mode,'report_id',v_r.report_id,
      'resolved_at',v_r.resolved_at,'narrated_at',v_r.narrated_at) end,
    'declarations',case when v_r.id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',d.id,'actor_id',d.actor_id,'actor_name',coalesce(ac.name,ap.nome,aip.nome,'Attore'),
        'actor_kind',aa.actor_kind,'kind',d.kind,
        'target_actor_id',d.target_actor_id,'target_name',coalesce(tc.name,tp.nome,tip.nome,'Attore'),
        'parent_attack_id',d.parent_attack_id,'targets',(select coalesce(jsonb_agg(jsonb_build_object('attack_target_id',t.id,'ordinal',t.ordinal,'target_actor_id',t.target_actor_id,'state',CASE WHEN NOT v_is_master AND NOT public.combat_v2_is_service()
          AND mission_narrative_internal.scene_native_round_bound_v1(v_m.id,v_r.id)
          AND EXISTS(SELECT 1 FROM public.combat_v2_defense_coverages private_coverage
           JOIN public.combat_v2_declarations private_none ON private_none.id=private_coverage.defense_declaration_id
           JOIN public.combat_v2_actors private_png ON private_png.id=private_none.actor_id AND private_png.actor_kind='png'
           WHERE private_coverage.attack_target_id=t.id AND private_none.kind='nessuna' AND coalesce(private_none.declaration_text,'')=''
            AND NOT mission_narrative_internal.scene_native_declaration_public_v1(private_none.id))
          THEN NULL ELSE t.state END,'outcome',case when v_r.state in('risolto','narrazione','narrato')then t.outcome else null end)order by t.ordinal),'[]'::jsonb)from public.combat_v2_attack_targets t where t.attack_declaration_id=d.id),'coverage',(select coalesce(jsonb_agg(jsonb_build_object('attack_target_id',c.attack_target_id,'protected_actor_id',c.protected_actor_id,'mode',c.mode,'state',c.state)order by c.id),'[]'::jsonb)from public.combat_v2_defense_coverages c where c.defense_declaration_id=d.id),'state',d.state,'order_no',d.order_no,
        'text',case when v_is_master or v_is_admin or exam_regia_private.actor_principal(aa.id,aa.controller_user)=v_uid
                         or exam_regia_private.actor_principal(ta.id,ta.controller_user)=v_uid or v_r.state in ('risolto','narrazione','narrato')
                    then d.declaration_text else '' end,
        'choice',jsonb_strip_nulls(jsonb_build_object(
          'kind',d.sanitized_intent->>'kind',
          'reaction',d.sanitized_intent->>'reaction',
          'ability_name',d.sanitized_intent->'server_ability'->>'name')),
        'rating',case
          when rr.id is null then null
          when v_is_admin or (rr.source<>'revisione_admin' and (v_is_master or exam_regia_private.actor_principal(aa.id,aa.controller_user)=v_uid))
          then jsonb_build_object('id',rr.id,'value',rr.value,'reason',rr.reason,
                                 'source',rr.source,'created_at',rr.created_at)
          else null end
      ) order by d.order_no nulls last,d.created_at,d.id)
      from public.combat_v2_declarations d
      join public.combat_v2_actors aa on aa.id=d.actor_id
      left join public.characters ac on ac.id=aa.character_id
      left join public.combat_v2_png_instances ap on ap.id=aa.png_instance_id left join public.combat_v2_provider_instances_v1 aip on aip.id=aa.provider_instance_v1_id
      left join public.combat_v2_actors ta on ta.id=d.target_actor_id
      left join public.characters tc on tc.id=ta.character_id
      left join public.combat_v2_png_instances tp on tp.id=ta.png_instance_id left join public.combat_v2_provider_instances_v1 tip on tip.id=ta.provider_instance_v1_id
      left join lateral (
        select r0.* from public.combat_v2_ratings r0
         where r0.declaration_id=d.id and r0.is_active
         order by r0.created_at desc limit 1
      ) rr on true
      where d.round_id=v_r.id
        AND (aa.actor_kind<>'png' OR NOT mission_narrative_internal.scene_native_round_bound_v1(v_m.id,v_r.id)
          OR v_is_master OR public.combat_v2_is_service()
          OR mission_narrative_internal.scene_native_declaration_public_v1(d.id))
        AND (NOT EXISTS(SELECT 1 FROM mission_generic_owner.unified_round_windows uw WHERE uw.round_id=v_r.id)
          OR mission_generic_owner.unified_service_staging(v_r.id) OR aa.actor_kind<>'png' OR d.kind<>'difesa' OR v_r.state='narrato')
        and (v_is_master or v_is_admin or exam_regia_private.actor_principal(aa.id,aa.controller_user)=v_uid
             or exam_regia_private.actor_principal(ta.id,ta.controller_user)=v_uid or v_r.state in ('risolto','narrazione','narrato'))
    ),'[]'::jsonb) end,
    'pending_defenses',case when v_r.id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
        'attack_declaration_id',d.id,
        'attacker_actor_id',d.actor_id,
        'attacker_name',coalesce(ac.name,ap.nome,aip.nome,'Attore'),
        'target_actor_id',d.target_actor_id,
        'target_name',coalesce(tc.name,tp.nome,tip.nome,'Attore'),
        'text',case when v_is_master or v_is_admin or exam_regia_private.actor_principal(ta.id,ta.controller_user)=v_uid
                    then d.declaration_text else '' end
      ) order by d.created_at,d.id)
      from public.combat_v2_declarations d
      join public.combat_v2_actors aa on aa.id=d.actor_id
      left join public.characters ac on ac.id=aa.character_id
      left join public.combat_v2_png_instances ap on ap.id=aa.png_instance_id left join public.combat_v2_provider_instances_v1 aip on aip.id=aa.provider_instance_v1_id
      join public.combat_v2_actors ta on ta.id=d.target_actor_id
      left join public.characters tc on tc.id=ta.character_id
      left join public.combat_v2_png_instances tp on tp.id=ta.png_instance_id left join public.combat_v2_provider_instances_v1 tip on tip.id=ta.provider_instance_v1_id
      where d.round_id=v_r.id and d.kind='attacco'
        AND (aa.actor_kind<>'png' OR NOT mission_narrative_internal.scene_native_round_bound_v1(v_m.id,v_r.id)
          OR v_is_master OR public.combat_v2_is_service()
          OR mission_narrative_internal.scene_native_declaration_public_v1(d.id))
        and not exists(select 1 from public.combat_v2_declarations x
                        where x.parent_attack_id=d.id and x.kind in ('difesa','nessuna'))
        and (v_is_master or v_is_admin or exam_regia_private.actor_principal(ta.id,ta.controller_user)=v_uid)
    ),'[]'::jsonb) end,
    'ratings_pending',case when not (v_is_master or v_is_admin) or v_r.id is null
      then '[]'::jsonb else coalesce((
        select jsonb_agg(jsonb_build_object(
          'declaration_id',d.id,'kind',d.kind,
          'actor_id',d.actor_id,'actor_name',c.name,
          'text',d.declaration_text
        ) order by d.created_at,d.id)
        from public.combat_v2_declarations d
        join public.combat_v2_actors a on a.id=d.actor_id and a.actor_kind='pg'
        join public.characters c on c.id=a.character_id
        where d.round_id=v_r.id and d.kind in ('attacco','difesa')
          and not exists(select 1 from public.combat_v2_ratings x
                          where x.declaration_id=d.id and x.is_active)
      ),'[]'::jsonb) end,
    'report',case when v_r.id is null or not (v_is_master or v_is_admin) then null else (
      select jsonb_build_object(
        'id',q.id,'sha256',q.mechanics_sha256,'mechanics',q.mechanics,
        'values_written',q.values_written,'narration_state',q.narration_state,
        'narrator_kind',q.narrator_kind,'created_at',q.created_at)
       from public.combat_v2_round_reports q
       where q.round_id=v_r.id OR (v_is_master AND q.id IN (
         select hw.source_report_id from mission_generic_owner.regia_human_windows_v1 hw
          where hw.master_session_id=v_m.id AND hw.next_round_id=v_r.id
            AND hw.state='private' AND hw.source_report_sha256=q.mechanics_sha256
         union all
         select ew.source_report_id from exam_human_private.round_publication_windows_v1 ew
          join exam_human_private.requests er ON er.id=ew.exam_id
          where er.master_session_id=v_m.id AND ew.next_round_id=v_r.id
            AND ew.state='private' AND ew.source_report_sha256=q.mechanics_sha256
       ))
       -- The private window still publishes its frozen source, even if the
       -- successor already has a native report from a non-offensive action.
       order by case when q.round_id=v_r.id then 1 else 0 end, q.created_at desc, q.id limit 1
    ) end
  ));
end
$function$;


CREATE OR REPLACE FUNCTION combat_panel_private.publish_master_declaration(p_declaration uuid, p_text text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.combat_v2_actors%ROWTYPE; d public.combat_v2_declarations%ROWTYPE;
  location uuid; v_message_id uuid; guided_before text;
  human_window boolean:=false; human_stage boolean:=false; human_pg_resolved boolean:=false; native_private boolean:=false; native_pg_resolved boolean:=false;
BEGIN
 SELECT * INTO STRICT d FROM public.combat_v2_declarations WHERE id=p_declaration FOR UPDATE;
  SELECT a0.* INTO a FROM public.combat_v2_actors a0
    JOIN public.combat_v2_rounds r ON r.id=d.round_id AND r.session_id=a0.session_id
    JOIN public.combat_v2_sessions s ON s.id=r.session_id AND s.source_kind='master'
    WHERE a0.id=d.actor_id AND exam_regia_private.actor_principal(a0.id,a0.controller_user)=exam_regia_private.current_principal() AND a0.companion_id IS NULL;
  SELECT EXISTS(SELECT 1 FROM mission_generic_owner.regia_human_windows_v1 hw
    WHERE hw.next_round_id=d.round_id AND hw.state IN('private','published')) INTO human_window;
  IF a.actor_kind='png' AND human_window THEN
    SELECT EXISTS(SELECT 1
      FROM mission_generic_owner.regia_human_stage_permits_v1 hp
      JOIN mission_generic_owner.regia_human_windows_v1 hw
        ON hw.next_round_id=hp.round_id AND hw.master_session_id=hp.master_session_id
      JOIN mission_generic_owner.unified_round_windows uw
        ON uw.round_id=hp.round_id AND uw.batch_id=hw.batch_id
         AND uw.master_session_id=hw.master_session_id
      JOIN public.combat_v2_sessions cs ON cs.id=a.session_id
         AND cs.master_session_id=hw.master_session_id
      JOIN public.master_v2_sessions ms ON ms.id=hw.master_session_id
      WHERE hp.round_id=d.round_id AND hp.actor_id=d.actor_id
        AND hp.request_key=d.request_key AND hp.principal_id=auth.uid()
        AND hp.transaction_id=txid_current() AND hp.backend_pid=pg_backend_pid()
        AND hw.encounter_id=cs.id AND ms.owner_kind='human'
        AND ms.closed_at IS NULL AND ms.master_user=auth.uid()
        AND ms.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
        AND d.controller_user_snapshot=hp.principal_id
        AND d.controller_version_snapshot=a.controller_version
        AND ((hw.state='private' AND hw.side='png' AND uw.side='png'
              AND uw.publication_id IS NULL AND d.actor_id=ANY(uw.expected_actor_ids)
              AND d.kind IN('attacco','movimento','utilita','passa'))
          OR (hw.state='published' AND hw.side='pg' AND uw.side='pg'
              AND uw.publication_id IS NOT NULL AND d.kind IN('difesa','nessuna'))))
      INTO human_stage;
  END IF;
  -- PG Human needs no Master permit. A resolved non-offensive declaration is
  -- accepted only when the published PG window and completed native action
  -- receipt identify this same actor, request, text and controller version.
   IF a.actor_kind='pg' AND d.state='risolta'
     AND d.kind IN ('utilita','movimento','passa')
     AND nullif(btrim(d.declaration_text),'') IS NOT NULL THEN
     SELECT EXISTS(SELECT 1
       FROM mission_generic_owner.regia_human_windows_v1 hw
       JOIN mission_generic_owner.unified_round_windows uw
         ON uw.round_id=hw.next_round_id AND uw.batch_id=hw.batch_id
           AND uw.master_session_id=hw.master_session_id
       JOIN public.combat_v2_sessions cs ON cs.id=hw.encounter_id
         AND cs.master_session_id=hw.master_session_id
       JOIN public.master_v2_sessions ms ON ms.id=hw.master_session_id
       JOIN public.locations loc ON loc.id=ms.location_id
       JOIN public.combat_v2_events ev ON ev.scope_id=d.round_id
         AND ev.request_key=d.request_key AND ev.operation_kind='combat_v2_action_declare'
       WHERE hw.next_round_id=d.round_id AND hw.state='published' AND hw.side='pg'
         AND hw.encounter_id=a.session_id AND uw.side='pg'
         AND uw.publication_id IS NOT NULL AND d.actor_id=ANY(uw.expected_actor_ids)
         AND ms.owner_kind='human' AND ms.closed_at IS NULL AND ms.stato='in_corso'
         AND ms.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
         AND loc.is_active AND loc.is_test
         AND ev.status='completata' AND ev.caller=auth.uid()
         AND ev.result#>>'{data,declaration_id}'=d.id::text
         AND ev.result#>>'{data,phase}'='risolto'
         AND ev.result#>'{data,auto_resolution}' IS NOT NULL
         AND ev.result#>'{data,auto_resolution}'<>'null'::jsonb)
       INTO human_pg_resolved;
   END IF;
  -- A Native PG main may already be resolved by action_declare in this same
  -- transaction. Admit only its exact completed event and protected report.
  IF a.actor_kind='pg' AND d.state='risolta' AND d.kind IN('attacco','utilita','movimento','passa')
   AND auth.uid() IS NOT NULL AND nullif(btrim(d.declaration_text),'') IS NOT NULL
   AND mission_narrative_internal.scene_native_round_bound_v1(
    (SELECT master_session_id FROM public.combat_v2_sessions WHERE id=a.session_id),d.round_id)
  THEN
   SELECT EXISTS(SELECT 1 FROM public.combat_v2_events accepted
    JOIN public.combat_v2_rounds rr ON rr.id=d.round_id AND rr.session_id=a.session_id
    JOIN public.combat_v2_round_reports report ON report.id=rr.report_id AND report.round_id=rr.id
    WHERE accepted.scope_id=d.round_id AND accepted.request_key=d.request_key
     AND accepted.operation_kind='combat_v2_action_declare' AND accepted.status='completata'
     AND accepted.caller=auth.uid() AND accepted.caller=d.controller_user_snapshot
     AND accepted.result#>>'{data,declaration_id}'=d.id::text AND accepted.result#>>'{data,phase}'='risolto'
     AND accepted.result#>>'{data,auto_resolution,data,report_id}'=report.id::text
     AND rr.state='risolto' AND rr.resolved_at IS NOT NULL AND report.narration_state='attesa'
     AND NOT report.values_written AND report.mechanics_sha256=public.combat_v2_sha256(report.mechanics))
   INTO native_pg_resolved;
  END IF;
  -- Native PNG defences remain private until the complete round Fato.
  -- This publisher runs before the final choice/request receipts exist: bind the
  -- live transaction permit; combat_narrative_source later verifies the completed receipts.
  IF a.actor_kind='png' AND d.kind IN('difesa','nessuna','attacco','movimento','utilita','passa')
   AND mission_narrative_internal.scene_native_round_bound_v1(
     (SELECT master_session_id FROM public.combat_v2_sessions WHERE id=a.session_id),d.round_id)
  THEN
   IF auth.uid() IS NOT NULL OR NOT public.combat_v2_is_service() OR NOT EXISTS(
    SELECT 1 FROM mission_generic_owner.panel_permits pp
    JOIN mission_generic_owner.panel_choices pc ON pc.work_id=pp.work_id
      AND pc.master_session_id=pp.master_session_id AND pc.encounter_id=pp.encounter_id
      AND pc.actor_id=pp.actor_id AND pc.principal_id=pp.principal_id AND pc.request_key=pp.request_key
    JOIN mission_generic_owner.work_items wi ON wi.id=pc.work_id
      AND wi.master_session_id=pc.master_session_id AND wi.encounter_id=pc.encounter_id
    WHERE pp.encounter_id=a.session_id AND pp.actor_id=a.id AND pp.request_key=d.request_key
      AND pp.principal_id=exam_regia_private.current_principal()
      AND pp.operation='commit' AND pp.consumed_at IS NULL
      AND pp.transaction_id=txid_current() AND pp.backend_pid=pg_backend_pid()
      AND pc.consumed_at IS NULL AND pc.controller_version=a.controller_version
      AND wi.kind='choice' AND wi.state='provider_started'
      AND wi.dispatch_receipt_id IS NOT NULL)
   THEN RAISE EXCEPTION 'NATIVE_PRIVATE_INTENT_AUTHORITY' USING ERRCODE='42501';END IF;
   native_private:=true;
  END IF;
   IF a.id IS NULL OR d.controller_user_snapshot IS DISTINCT FROM exam_regia_private.current_principal()
     OR d.controller_version_snapshot<>a.controller_version
     OR (d.state<>'inviata' AND NOT native_private AND NOT exam_human_private.round_declaration_permit_v1(d.id)
       AND NOT (
         (d.state='risolta' AND a.actor_kind='png'
           AND EXISTS(SELECT 1 FROM mission_generic_owner.unified_round_windows uw WHERE uw.round_id=d.round_id)
           AND (mission_generic_owner.unified_service_staging(d.round_id) OR human_stage))
         OR (d.state='risolta' AND a.actor_kind='pg'
           AND ((d.kind='passa' AND d.declaration_text='')
             OR (d.kind IN ('utilita','movimento','passa')
               AND nullif(btrim(d.declaration_text),'') IS NOT NULL
               AND EXISTS(SELECT 1 FROM mission_generic_owner.unified_round_windows uw2
                 JOIN mission_generic_owner.flow_staff_sessions fs2 ON fs2.master_session_id=uw2.master_session_id AND fs2.enabled
                 JOIN public.master_v2_sessions ms2 ON ms2.id=fs2.master_session_id
                   AND ms2.owner_kind='ai_service' AND ms2.closed_at IS NULL
                 JOIN public.locations l2 ON l2.id=ms2.location_id AND l2.is_test
                 WHERE uw2.round_id=d.round_id AND uw2.side='pg' AND uw2.publication_id IS NOT NULL
                   AND ms2.id=(SELECT master_session_id FROM public.combat_v2_sessions WHERE id=a.session_id))))
           AND (EXISTS(SELECT 1 FROM mission_generic_owner.unified_round_windows uw WHERE uw.round_id=d.round_id)
             OR combat_panel_private.human_duel_round(d.round_id)))
         OR human_pg_resolved OR native_pg_resolved))
     OR d.declaration_text IS DISTINCT FROM coalesce(p_text,'') THEN
     RAISE EXCEPTION 'panel_role_declaration_scope_invalid' USING ERRCODE='42501'; END IF;
  SELECT location_id INTO STRICT location FROM public.combat_v2_sessions WHERE id=a.session_id;
  IF native_private THEN RETURN NULL;END IF;
  IF a.actor_kind='png' AND exam_human_private.round_declaration_permit_v1(d.id) THEN RETURN NULL; END IF;
  IF a.actor_kind='png' AND human_window THEN
    IF NOT human_stage THEN RAISE EXCEPTION 'REGIA_FATO_PENDING' USING ERRCODE='42501'; END IF;
    RETURN NULL;
  END IF;

 IF a.actor_kind='png' AND EXISTS(
  SELECT 1 FROM mission_generic_owner.unified_batches ub
   WHERE ub.master_session_id=(SELECT master_session_id FROM public.combat_v2_sessions WHERE id=a.session_id)
     AND ub.state IN ('preparing','ready') AND ub.composition_kind='entry_png'
     AND ub.payload->>'schema_version'='mission-generic-narration/4')
  AND (mission_generic_owner.principal_in_session(
   (SELECT master_session_id FROM public.combat_v2_sessions WHERE id=a.session_id),exam_regia_private.current_principal())
   AND mission_generic_owner.actor_principal(a.id)=exam_regia_private.current_principal()) IS NOT TRUE
 THEN RAISE EXCEPTION 'MRS_V4_PUBLISHER_PRINCIPAL_INVALID' USING ERRCODE='42501'; END IF;

 IF a.actor_kind='png' AND mission_generic_owner.principal_in_session(
  (SELECT master_session_id FROM public.combat_v2_sessions WHERE id=a.session_id),exam_regia_private.current_principal())
  AND mission_generic_owner.actor_principal(a.id)=exam_regia_private.current_principal() THEN
  IF nullif(btrim(p_text),'') IS NULL THEN RAISE EXCEPTION 'MG_PNG_ATTEMPT_EMPTY'; END IF;
  IF mission_generic_owner.try_stage_deferred_png_v4(d.id,p_text) THEN RETURN NULL; END IF;
   -- Only the protected Mission Generic Staff path can defer this public text.
   -- Entry PNG v4 keeps its separate sealed-slot publisher and cannot fall through.
   IF EXISTS(SELECT 1 FROM mission_generic_owner.unified_round_windows uw
      JOIN mission_generic_owner.unified_batches ub ON ub.id=uw.batch_id
      JOIN mission_generic_owner.flow_staff_sessions fs ON fs.master_session_id=ub.master_session_id AND fs.enabled
      JOIN public.master_v2_sessions ms ON ms.id=fs.master_session_id
       AND ms.owner_kind='ai_service' AND ms.closed_at IS NULL
      JOIN public.locations loc ON loc.id=ms.location_id AND loc.id=location AND loc.is_test
      WHERE uw.round_id=d.round_id AND ub.master_session_id=(SELECT master_session_id FROM public.combat_v2_sessions WHERE id=a.session_id)
        AND NOT (ub.composition_kind='entry_png' AND ub.payload->>'schema_version'='mission-generic-narration/4'))
   THEN RETURN NULL; END IF;
  INSERT INTO public.messages(location_id,character_id,author_name,body,kind)
   VALUES(location,NULL,'Fato',p_text,'fato') RETURNING id INTO v_message_id;
  INSERT INTO combat_consumer_private.declaration_messages
   VALUES(d.id,v_message_id,public._combat_narrative_sha(v_message_id));
  RETURN v_message_id;
 END IF;
 IF a.actor_kind='png' AND EXISTS(SELECT 1 FROM exam_regia_private.bindings b
 WHERE b.png_actor_id=a.id AND b.combat_session_id=a.session_id
 AND b.service_principal_id=exam_regia_private.current_principal() AND b.state='active') THEN
  -- La dichiarazione resta immutabile; testo PNG pubblicato soltanto via ricevuta SESSION.
  RETURN NULL;
 END IF;
 IF a.actor_kind='pg' AND exam_regia_private.is_bound(a.session_id) THEN
  IF length(btrim(coalesce(p_text,'')))=0 THEN RETURN NULL; END IF;
  v_message_id:=public._esame_testo_candidato(a.session_id,p_text);
  PERFORM combat_consumer_private.record_message(d.id,v_message_id);
  RETURN v_message_id;
 END IF;
 IF length(btrim(coalesce(p_text,'')))=0 THEN RETURN NULL; END IF;
 IF a.actor_kind='pg' THEN
   guided_before:=current_setting('app.combat_guidata',true);
   PERFORM set_config('app.combat_guidata','1',true);
   BEGIN
     v_message_id:=public.post_message(location,p_text,NULL,NULL,NULL);
   EXCEPTION WHEN OTHERS THEN
     PERFORM set_config('app.combat_guidata',coalesce(guided_before,''),true); RAISE;
   END;
   PERFORM set_config('app.combat_guidata',coalesce(guided_before,''),true);
   PERFORM combat_consumer_private.record_message(d.id,v_message_id);
 ELSIF a.actor_kind='png' THEN
   v_message_id:=public.post_fato_manual(location,p_text);
   IF NOT EXISTS(SELECT 1 FROM public.messages m JOIN public.fato_manual_audit f ON f.message_id=m.id
     WHERE m.id=v_message_id AND m.location_id=location AND m.kind='fato' AND m.character_id IS NULL
       AND f.actor_user=exam_regia_private.current_principal() AND f.location_id=location) THEN
     RAISE EXCEPTION 'panel_role_message_scope_invalid' USING ERRCODE='42501'; END IF;
   INSERT INTO combat_consumer_private.declaration_messages
     VALUES(d.id,v_message_id,public._combat_narrative_sha(v_message_id));
 ELSE RAISE EXCEPTION 'panel_role_actor_kind_invalid' USING ERRCODE='22023'; END IF;
 RETURN v_message_id;
END $function$;


CREATE OR REPLACE FUNCTION mission_generic_owner.combat_narrative_source(p_session uuid, p_event uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare scene56_runtime mission_narrative_internal.scene_runtime_v1;scene56_npc jsonb;scene56_last public.messages;
 e mission_generic_owner.encounters%rowtype; b mission_generic_owner.run_bindings%rowtype;
 run public.mission_run_state%rowtype; s public.combat_v2_sessions%rowtype;
 r public.combat_v2_rounds%rowtype; rep public.combat_v2_round_reports%rowtype;
 a public.combat_v2_actors%rowtype; d public.combat_v2_declarations%rowtype;
 place public.locations%rowtype; row record; item jsonb; projected jsonb; narrator jsonb;
 roleless jsonb:='[]'; actors jsonb:='[]'; actions jsonb:='[]'; sources jsonb:='[]'; facts jsonb:='[]'; spatial jsonb:='[]';
 snapshot jsonb; candidate jsonb; scenehash text; body text; sid text; pname text; persona text;
 prior_count integer:=0; included integer:=0;director jsonb;loc text;setting_body text;setting_id text;actor_key text;payload jsonb;knowledge jsonb;knowledge_context jsonb:='[]';input_cap integer;continuity_snapshot jsonb;private_native20 boolean:=false;
begin
 if auth.uid() is not null or not public.combat_v2_is_service() then raise exception 'MG_SERVICE_REQUIRED' using errcode='42501';end if;
 perform mission_generic_owner.assert_runtime(p_session);
 input_cap:=(mission_generic_owner.capacity()->>'input_capacity_bytes')::integer;
 select * into strict b from mission_generic_owner.run_bindings where master_session_id=p_session;
 select * into strict run from public.mission_run_state where master_session_id=p_session;
 select * into strict rep from public.combat_v2_round_reports where id=p_event;
 perform public.combat_v2_lock_round(rep.round_id);
 select * into strict r from public.combat_v2_rounds where id=rep.round_id and report_id=rep.id;
 select * into strict s from public.combat_v2_sessions where id=r.session_id and master_session_id=p_session;
 select * into strict e from mission_generic_owner.encounters where encounter_id=s.id and master_session_id=p_session;
 select * into strict place from public.locations where id=s.location_id;
 if e.step_key<>run.current_step_key or e.run_control_version<>run.control_version
  or b.snapshot_sha256 is distinct from mission_internal.fingerprint(b.snapshot)
  or r.state<>'risolto' or r.resolved_at is null or rep.narration_state<>'attesa'
  or rep.mechanics_sha256 is distinct from public.combat_v2_sha256(rep.mechanics)
  or jsonb_typeof(rep.mechanics->'declarations') is distinct from 'array'
  or (place.is_test and (rep.values_written or public.combat_v2_values_written(s.id)))
 then raise exception 'MG_COMBAT_SOURCE_STALE' using errcode='55000';end if;
 SELECT * INTO scene56_runtime FROM mission_narrative_internal.scene_runtime_v1 WHERE master_session_id=p_session AND is_active;
 director:=mission_creation_owner.director_context(p_session,run.current_step_key);
 if director is null then
  loc:=place.name;setting_body:=place.description;setting_id:='location:'||place.id;
 else
  loc:=case when nullif(btrim(director#>>'{setting,name}'),'') is not null then director#>>'{setting,name}' else 'Ambientazione della missione' end;
  setting_body:=director#>>'{setting,description}';
  setting_id:='mission-setting:'||p_session||':'||run.current_step_key;
  if director->>'schema_version' is distinct from 'mission-director-context/1'
   or nullif(btrim(loc),'') is null or nullif(btrim(setting_body),'') is null
  then raise exception 'MC_DIRECTOR_CONTEXT_INVALID';end if;
 end if;
 for a in select * from public.combat_v2_actors where session_id=s.id order by id loop
  persona:=null;pname:=null;
  if a.actor_kind='pg' then
   select name into strict pname from public.characters where id=a.character_id and user_id=a.controller_user;
  elsif a.actor_kind='png' then
    IF scene56_runtime.id IS NOT NULL THEN
     SELECT map->>'actor_key' INTO STRICT actor_key FROM jsonb_array_elements(e.actor_map)map WHERE map->>'actor_id'=a.id::text;
     SELECT npc INTO STRICT scene56_npc FROM jsonb_array_elements(scene56_runtime.snapshot->'npcs')npc WHERE npc->>'actor_key'=actor_key;
     pname:=scene56_npc->>'name';
     persona:=jsonb_build_object('voice',scene56_npc#>'{profile,skeleton,voice}',
      'gestures',scene56_npc#>'{profile,skeleton,gestures}',
      'life_core',scene56_npc#>'{profile,skeleton}',
      'conduct',scene56_npc#>'{profile,skeleton,conduct}',
      'forbidden',scene56_npc#>'{profile,skeleton,forbidden}')::text;
     knowledge:=jsonb_build_object('actor_id',a.id,'knowledge_limits',scene56_npc#>'{profile,skeleton,knowledge_limits}',
      'knowledge_boundary',scene56_npc->'knowledge');
    ELSE
   select pi.nome,(jsonb_build_object('voice',nv.skeleton->'voice','gestures',nv.skeleton->'gestures',
    'life_core',jsonb_build_object(
    'background',jsonb_strip_nulls(jsonb_build_object('role',nv.skeleton#>'{identity,role}','origin',nv.skeleton#>'{identity,origin}')),
    'motivations',nv.skeleton->'motivations','goals',nv.skeleton->'goals','fears',nv.skeleton->'fears',
    'fragility',nv.skeleton->'fragility','resilience',nv.skeleton->'resilience',
    'character_errors',nv.skeleton->'character_errors','recovery',nv.skeleton->'recovery',
    'relationships',nv.skeleton->'relationships',
    'continuity',jsonb_strip_nulls(jsonb_build_object('emotional',nv.skeleton#>'{continuity,emotional}',
      'relational',nv.skeleton#>'{continuity,relational}','emotional_endings',nv.skeleton#>'{continuity,emotional_endings}')))) || case when mission_academy_owner.staff_carrier_runtime(p_session) then jsonb_build_object('conduct',nv.skeleton->'conduct','forbidden',nv.skeleton->'forbidden') else '{}'::jsonb end)::text,
    jsonb_build_object('actor_id',a.id,'knowledge_limits',nv.skeleton->'knowledge_limits','knowledge_boundary',nv.knowledge_boundary)
    into strict pname,persona,knowledge
    from public.combat_v2_provider_instances_v1 pi join public.nb_template_versions nv on nv.id=pi.narrative_version_ref
    where pi.id=a.provider_instance_v1_id and pi.session_id=s.id;
    END IF;
   if director is not null then
    select x->>'actor_key' into strict actor_key from jsonb_array_elements(e.actor_map) x
     where x->>'actor_id'=a.id::text;
    -- The mapping identifies the approved actor for its private phase notes.
    -- It carries no secret or additional actor authority.
    persona:=(persona::jsonb||jsonb_build_object('mission_actor_key',actor_key))::text;
    knowledge_context:=knowledge_context||jsonb_build_array(knowledge||jsonb_build_object('actor_key',actor_key));
   end if;
  else raise exception 'MG_SCENE_ACTOR_UNSUPPORTED'  using errcode='55000';end if;
  if nullif(btrim(pname),'') is null then raise exception 'MG_SCENE_IDENTITY_MISSING';end if;
  actors:=actors||jsonb_build_array(jsonb_build_object('id',a.id,'name',pname,'kind',upper(a.actor_kind),
    'persona',persona,'may_speak',a.actor_kind='png'));
 end loop;
 if nullif(btrim(setting_body),'') is not null then
  body:=setting_body;
  sources:=jsonb_build_array(jsonb_build_object('id',setting_id,'session_id',s.id,'round_id',r.id,
   'kind','setting','actor_id',null,'sequence',0,'body',body,
   'sha256',encode(extensions.digest(convert_to(body,'UTF8'),'sha256'),'hex'),'visibility','public','complete',true));
 end if;
 -- Staff reads this publication in the certified delta, not twice as a setting.
 -- Legacy public path remains unchanged.
 if not mission_generic_owner.flow_scope_enabled(p_session) then
 -- Only public mission publications tied to this run, never an unfiltered chat.
 for row in select w.id,w.result->>'text' body,
 case when w.payload->>'mode'='unified' then coalesce(w.message_id,(select urp.message_id
  from mission_generic_owner.unified_report_publications urp join mission_generic_owner.unified_batches ub on ub.id=urp.batch_id
  where ub.id=w.authority_receipt_id and ub.master_session_id=w.master_session_id and ub.writer_work_id=w.id
   and ub.state='published' and ub.message_id=urp.message_id and urp.primary_report and urp.report_id=ub.source_report_id))
 else w.message_id end message_id from mission_generic_owner.work_items w
  where w.master_session_id=p_session and w.kind='narration' and w.state='completed' and w.payload->>'mode' in('mission','unified')
  order by w.created_at desc limit 1 loop
  if nullif(btrim(row.body),'') is null or not exists(select 1 from public.messages m where m.id=row.message_id
    and m.location_id=place.id and m.recipient_user is null and m.kind='fato' and m.body=row.body)
  then raise exception 'MG_SCENE_CONTINUITY_CHANGED';end if;
  sources:=sources||jsonb_build_array(jsonb_build_object('id','mission:'||row.id,'session_id',s.id,'round_id',r.id,
   'kind','setting','actor_id',null,'sequence',0,'body',row.body,
   'sha256',encode(extensions.digest(convert_to(row.body,'UTF8'),'sha256'),'hex'),'visibility','public','complete',true));
 end loop;
 end if;
 IF scene56_runtime.id IS NOT NULL AND scene56_runtime.last_publication_id IS NOT NULL THEN
  SELECT * INTO STRICT scene56_last FROM public.messages WHERE id=scene56_runtime.last_publication_id
   AND location_id=place.id AND kind='fato' AND recipient_user IS NULL;
  IF encode(extensions.digest(convert_to(scene56_last.body,'UTF8'),'sha256'),'hex') IS DISTINCT FROM scene56_runtime.last_publication_sha256
   THEN RAISE EXCEPTION 'SCENE56_COMBAT_CONTINUITY_CHANGED' USING ERRCODE='PT409';END IF;
  sources:=sources||jsonb_build_array(jsonb_build_object('id','mission:'||scene56_last.id,'session_id',s.id,'round_id',r.id,
   'kind','setting','actor_id',NULL,'sequence',0,'body',scene56_last.body,'sha256',scene56_runtime.last_publication_sha256,
   'visibility','public','complete',true));
 END IF;
 for d in select * from public.combat_v2_declarations where round_id=r.id order by order_no nulls last,id loop
  private_native20:=false;
  select value into strict item from jsonb_array_elements(rep.mechanics->'declarations') where value->>'id'=d.id::text;
  if item->>'actor' is distinct from d.actor_id::text or item->>'kind' is distinct from d.kind
   or item->>'state' is distinct from d.state or item->'outcome' is distinct from d.outcome
   or d.state not in('risolta','superflua') then raise exception 'MG_SCENE_REPORT_CHANGED';end if;
  if d.state='risolta' then projected:=combat_panel_private.narrative_declaration_facts(d.id);
  else
   projected:=jsonb_build_object('execution','not_executed','result',combat_panel_private.narrative_outcome_facts(d.outcome));
   IF d.state='superflua' AND combat_v2_elemental_internal.suiton_narrative_supported(d.id) THEN
    projected:=projected||combat_v2_elemental_internal.suiton_narrative_projection(d.id)||jsonb_build_object('suiton_technique',(SELECT jsonb_build_object('name',s.profile->'name','description',s.profile->'effect_description','limits',s.profile->'limits','provenance','elementali-frozen-tech/1') FROM combat_v2_elemental_internal.suiton_sources s WHERE s.declaration_id=d.id));
   END IF;
  end if;
  IF d.state='superflua' AND combat_v2_elemental_internal.other_narrative_supported(d.id) THEN projected:=projected||combat_v2_elemental_internal.other_narrative_projection(d.id);END IF;
  facts:=facts||jsonb_build_array(jsonb_build_object('declaration_id',d.id,'actor_id',d.actor_id,
   'target_actor_id',d.target_actor_id,'kind',d.kind,'facts',projected));
  -- Automatic missing-defence receipts are facts, not a newly invented role.
  if d.kind='nessuna' and coalesce(d.declaration_text,'')='' then continue;end if;
  select * into strict a from public.combat_v2_actors where id=d.actor_id and session_id=s.id;
  select m.id::text,m.body into sid,body from combat_consumer_private.declaration_messages l
   join public.messages m on m.id=l.message_id where l.declaration_id=d.id and m.location_id=place.id
    and m.recipient_user is null and m.kind not in('whisper','motore')
    and public._combat_narrative_sha(m.id)=l.message_sha256
    and ((a.actor_kind='pg' and m.character_id=a.character_id and (
        m.sender_user=a.controller_user
        or (m.sender_user is null and exists(select 1 from combat_panel_private.request_receipts q
          where q.principal_user=a.controller_user and q.request_key=d.request_key
            and q.viewer_envelope#>>'{receipt,declaration_id}'=d.id::text))))
      or (a.actor_kind='png' and m.character_id is null and m.sender_user is null and m.kind='fato'));
  if sid is null and a.actor_kind='png' and (exists(select 1 from mission_generic_owner.unified_round_windows uw where uw.round_id=d.round_id) OR mission_narrative_internal.scene_native_round_bound_v1(p_session,d.round_id))
   and not exists(select 1 from mission_generic_owner.unified_round_windows rw
    join mission_generic_owner.unified_batches batch_row on batch_row.id=rw.batch_id
    where rw.round_id=d.round_id and batch_row.payload->>'schema_version'='mission-generic-narration/4'
      and batch_row.composition_kind='entry_png') then
   select 'choice:'||w.id::text,w.result#>>'{command,narrative_text}' into strict sid,body
   from mission_generic_owner.panel_choices c
   join mission_generic_owner.work_items w on w.id=c.work_id and w.master_session_id=p_session
   join mission_narrative_internal.dispatch_audit da on da.receipt_id=w.dispatch_receipt_id and da.event_code='generic_finalized'
   join combat_panel_private.request_receipts q on q.principal_user=c.principal_id and q.request_key=c.request_key
   where c.encounter_id=s.id and c.actor_id=a.id and c.request_key=d.request_key and c.consumed_at is not null
    and c.result=q.viewer_envelope and c.command_sha256=q.command_fingerprint
    and q.viewer_envelope#>>'{receipt,declaration_id}'=d.id::text
    and w.kind='choice' and w.state='completed'
    and da.details->>'result_sha256'=w.result_sha256
    and da.details->>'result_jsonb_sha256'=public.combat_v2_sha256(w.result)
    and w.result#>>'{command,narrative_text}'=d.declaration_text;
   private_native20:=mission_narrative_internal.scene_native_round_bound_v1(p_session,d.round_id);
  end if;
  if a.actor_kind='png' and not exists(select 1 from mission_generic_owner.panel_choices c
    join combat_panel_private.request_receipts q on q.principal_user=c.principal_id and q.request_key=c.request_key
    where c.encounter_id=s.id and c.actor_id=a.id and c.request_key=d.request_key and c.consumed_at is not null
    and c.result=q.viewer_envelope and c.command_sha256=q.command_fingerprint
    and q.viewer_envelope#>>'{receipt,declaration_id}'=d.id::text)
  then raise exception 'MG_SCENE_PNG_RECEIPT_MISSING';end if;
  if a.actor_kind='png' and (exists(select 1 from mission_generic_owner.unified_round_windows urw where urw.round_id=r.id) OR mission_narrative_internal.scene_native_round_bound_v1(p_session,r.id)) then
   if exists(select 1 from mission_generic_owner.unified_round_windows rw
      join mission_generic_owner.unified_batches batch_row on batch_row.id=rw.batch_id
      where rw.round_id=d.round_id and batch_row.payload->>'schema_version'='mission-generic-narration/4'
       and batch_row.composition_kind='entry_png') then
    select v.source_id::text,v.body into sid,body
     from mission_generic_owner.verified_deferred_source_v4(d.id) v;
    if sid is null then raise exception 'MRS_V4_SCENE_DEFERRED_SOURCE_MISSING';end if;
   else
    sid:=CASE WHEN private_native20 THEN 'native-intent:'||d.id::text ELSE d.id::text END;body:=d.declaration_text;
   end if;
  end if;
  if d.kind='passa' and coalesce(btrim(d.declaration_text),'')='' then
   IF mission_narrative_internal.scene_native_round_bound_v1(p_session,r.id) THEN
    -- The original consumed offer required no role. Keep its mechanics fact; do not invent text or a Unified window.
    PERFORM mission_generic_owner.unified_roleless_receipt(d.id);CONTINUE;
   ELSIF exists(select 1 from mission_generic_owner.unified_round_windows urw where urw.round_id=r.id) THEN
    roleless:=roleless||jsonb_build_array(mission_generic_owner.unified_roleless_receipt(d.id));continue;
   END IF;
  end if;
  if sid is null or nullif(btrim(body),'') is null then raise exception 'MG_SCENE_ROLE_MISSING';end if;
  actions:=actions||jsonb_build_array(jsonb_build_object('actor_id',a.id,'role',case when d.kind='difesa' then 'difesa' else 'azione' end,'source_id',sid));
  sources:=sources||jsonb_build_array(jsonb_build_object('id',sid,'session_id',s.id,'round_id',r.id,'kind',CASE WHEN private_native20 THEN 'native_intent' ELSE 'role' END,
   'actor_id',a.id,'sequence',r.round_no,'body',body,'sha256',encode(extensions.digest(convert_to(body,'UTF8'),'sha256'),'hex'),
   'visibility',CASE WHEN private_native20 THEN 'private_intention' ELSE 'public' END,'complete',true));
 end loop;
 if (jsonb_array_length(actions)=0 and jsonb_array_length(roleless)=0) or jsonb_array_length(facts)<>jsonb_array_length(rep.mechanics->'declarations')
 then raise exception 'MG_SCENE_BARRIER_INCOMPLETE';end if;
 for item in select value from jsonb_array_elements(coalesce(rep.mechanics->'substitution_receipts','[]')) loop
  narrator:=item->'narrator_payload';
  if item->>'round_id' is distinct from r.id::text or narrator->>'schema_version' is distinct from 'common-substitution-narrator/1.0'
   or not exists(select 1 from jsonb_array_elements(actors) ar where ar->>'id'=item->>'actor_id')
  then raise exception 'MG_SCENE_SUBSTITUTION_CHANGED';end if;
  spatial:=spatial||jsonb_build_array(jsonb_build_object('actor_id',item->'actor_id','kind','substitution',
   'outcome',narrator#>'{impact,outcome}','anchor',narrator#>'{anchor,semantic_label}','after',narrator#>'{after,semantic_region}'));
 end loop;
 select count(*) into prior_count from public.combat_v2_narratives n join public.combat_v2_rounds old on old.id=n.round_id
   join public.combat_v2_round_reports q on q.id=n.report_id where old.session_id=s.id and old.round_no<r.round_no
   and old.state='narrato' and q.narration_state='pubblicata';
 if mission_generic_owner.flow_scope_enabled(p_session) then
  continuity_snapshot:=mission_generic_owner.continuity_snapshot(p_session);
 end if;
 snapshot:=jsonb_build_object('schema_version','combat-scene/1','session_id',s.id,'round_id',r.id,
  'report_sha256',rep.mechanics_sha256,'control_version',run.control_version,'location',loc,'actors',actors,'actions',actions,
  'resolved_facts',jsonb_build_object('schema_version','mission-generic-resolved-facts/1','round_no',r.round_no,
   'declarations',facts,'spatial',spatial)::text,'sources',sources,
  'selection',jsonb_build_object('max_input_bytes',input_cap,'previous_available',prior_count,'previous_included',0));
 if octet_length(snapshot::text)>input_cap then raise exception 'MG_SCENE_REQUIRED_CONTEXT_OVERFLOW' using errcode='54000';end if;
 if not mission_generic_owner.flow_scope_enabled(p_session) then
 for row in select n.id,n.round_id,n.body,old.round_no,q.message_id from public.combat_v2_narratives n
  join public.combat_v2_rounds old on old.id=n.round_id and old.session_id=s.id
  join public.combat_v2_round_reports q on q.id=n.report_id and q.round_id=old.id
  where old.round_no<r.round_no and old.state='narrato' and q.narration_state='pubblicata' and not exists(select 1 from mission_generic_owner.unified_report_publications urp where urp.report_id=q.id and not urp.primary_report) order by old.round_no desc,n.id loop
  if not exists(select 1 from public.messages m where m.id=row.message_id and m.location_id=place.id and m.body=row.body
    and m.character_id is null and m.sender_user is null and m.recipient_user is null and m.kind='fato')
  then raise exception 'MG_SCENE_PREVIOUS_CHANGED';end if;
  candidate:=jsonb_set(snapshot,'{sources}',snapshot->'sources'||jsonb_build_array(jsonb_build_object('id',row.id,
   'session_id',s.id,'round_id',row.round_id,'kind','fato','actor_id',null,'sequence',row.round_no,'body',row.body,
   'sha256',encode(extensions.digest(convert_to(row.body,'UTF8'),'sha256'),'hex'),'visibility','public','complete',true)));
  candidate:=jsonb_set(candidate,'{selection,previous_included}',to_jsonb(included+1));
  if octet_length(candidate::text)<=input_cap then snapshot:=candidate;included:=included+1;end if;
 end loop;
 end if;
 scenehash:=public.combat_v2_sha256(snapshot);
 payload:=jsonb_build_object('schema_version',case when director is null then 'mission-generic-narration/1' else 'mission-generic-narration/2' end,
   'mode','combat','scene',jsonb_build_object('snapshot',snapshot,'snapshot_sha256',scenehash),
   'scene_binding',jsonb_build_object('session_id',s.id,'round_id',r.id,'report_sha256',rep.mechanics_sha256,
    'control_version',run.control_version,'hash_authority','combat_v2_sha256/jsonb','scene_sha256',scenehash),
   'barrier',jsonb_build_object('closed',true,'required_receipt_ids',jsonb_build_array(rep.id),'receipt_ids',jsonb_build_array(rep.id)));
 if director is not null then
  payload:=payload||jsonb_build_object('director_context',director,'knowledge_context',knowledge_context,
   'source_cursor',jsonb_build_object('scope','combat_declarations','through',r.resolved_at));
 end if;
 if continuity_snapshot is not null then
  payload:=payload||jsonb_build_object('continuity',continuity_snapshot->'continuity',
   'history_chain_sha256',continuity_snapshot->'history_chain_sha256',
   'history_count',continuity_snapshot->'history_count',
   'continuity_delta',continuity_snapshot->'delta');
 end if;
 if jsonb_array_length(roleless)>0 then payload:=payload||jsonb_build_object('roleless_declarations',roleless);end if;
 return jsonb_build_object('master_session_id',p_session,'step_key',run.current_step_key,'run_control_version',run.control_version,
  'encounter_id',s.id,'authority_receipt_id',rep.id,'payload',payload);
end $function$;


CREATE OR REPLACE FUNCTION mission_generic_owner.native_combat_writer_reissue_proof_v1(p_work uuid, p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE w mission_generic_owner.work_items;su mission_generic_owner.work_items;
 m public.master_v2_sessions;rep public.combat_v2_round_reports;dr mission_narrative_internal.dispatch_receipts;
 wc mission_public_owner.work_contracts_v1;au mission_narrative_internal.dispatch_audit;
 root mission_generic_owner.event_outbox_v1;wake mission_generic_owner.event_outbox_v1;
 who uuid;sid uuid;ev uuid;rq uuid;req jsonb;published boolean:=false;descendant20 jsonb;final_publication21 uuid;
BEGIN
 IF p_work IS NULL OR p_user IS NULL OR(auth.uid() IS NOT NULL AND auth.uid()<>p_user) THEN RETURN NULL;END IF;
 SELECT * INTO w FROM mission_generic_owner.work_items WHERE id=p_work;
 IF NOT FOUND OR w.kind IS DISTINCT FROM 'narration' OR w.state IS DISTINCT FROM 'failed'
  OR w.payload->>'schema_version' IS DISTINCT FROM 'mission-generic-narration/2' OR w.payload->>'mode' IS DISTINCT FROM 'combat'
  OR w.message_id IS NOT NULL OR w.finalized_at IS NULL OR w.authorization_id IS NOT NULL OR w.dispatch_id IS NOT NULL
  OR w.payload_sha256 IS DISTINCT FROM public.combat_v2_sha256(w.payload)
  OR w.result_sha256 IS DISTINCT FROM public.combat_v2_sha256(w.result)
  OR w.result->>'schema_version' IS DISTINCT FROM 'mission-generic-pre-provider-failure/1'
  OR w.result->>'failure_code' IS DISTINCT FROM 'request_validation_failed'
  OR w.result->>'work_id' IS DISTINCT FROM w.id::text OR w.result->>'master_session_id' IS DISTINCT FROM w.master_session_id::text
  OR w.result->>'event_id' IS DISTINCT FROM w.event_id::text OR w.result->>'request_key' IS DISTINCT FROM w.request_key::text
  OR w.result->>'provider_calls' IS DISTINCT FROM '0' OR (w.result->>'charged_cost_usd')::numeric IS DISTINCT FROM 0
 THEN RETURN NULL;END IF;
 SELECT * INTO m FROM public.master_v2_sessions WHERE id=w.master_session_id;
 IF m.owner_kind IS DISTINCT FROM 'ai_service' OR m.master_user IS NOT NULL
  OR m.location_id IS DISTINCT FROM '0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
  OR NOT EXISTS(SELECT 1 FROM public.locations l WHERE l.id=m.location_id AND l.is_test AND l.is_active)
  OR NOT EXISTS(SELECT 1 FROM public.profiles pr JOIN public.master_v2_participants mp ON mp.user_id_snapshot=pr.id
    JOIN public.characters ch ON ch.id=mp.character_id AND ch.user_id=mp.user_id_snapshot
    WHERE pr.id=p_user AND pr.role IN('admin','master') AND mp.session_id=m.id)
  OR mission_generic_owner.manual_staff_scope_v1(m.id) IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO wc FROM mission_public_owner.work_contracts_v1 WHERE work_id=w.id;
 IF wc.contract_sha256 IS DISTINCT FROM public.combat_v2_sha256(wc.contract)
  OR wc.contract->>'schema_version' IS DISTINCT FROM 'mission-narrative-admission/3'
  OR wc.contract->>'scope' IS DISTINCT FROM 'staff_mission'
  OR wc.contract->>'work_id' IS DISTINCT FROM w.id::text OR wc.contract->>'payload_sha256' IS DISTINCT FROM w.payload_sha256
  OR wc.contract->>'payload_schema_version' IS DISTINCT FROM 'mission-generic-narration/2'
  OR wc.contract#>>'{source_attestation,execution_authority,schema_version}' IS DISTINCT FROM 'c1266-work-execution-attestation/3'
  OR wc.contract#>>'{source_attestation,execution_authority,execution_context}' IS DISTINCT FROM 'staff_mission'
  OR NOT(wc.contract->'features'?'execution_authority_v1') THEN RETURN NULL;END IF;
 SELECT * INTO dr FROM mission_narrative_internal.dispatch_receipts WHERE id=w.dispatch_receipt_id;
 IF NOT FOUND OR dr.master_session_id IS DISTINCT FROM m.id OR dr.authority_receipt_id IS DISTINCT FROM w.id
  OR dr.request_key IS DISTINCT FROM w.request_key OR dr.status IS DISTINCT FROM 'failed' OR dr.dispatch_count IS DISTINCT FROM 0
  OR dr.finalized_at IS NULL OR dr.charged_cost_usd IS DISTINCT FROM 0 OR dr.upper_bound_cost_usd IS DISTINCT FROM 0
  OR dr.envelope_sha256 IS DISTINCT FROM public.combat_v2_sha256(dr.envelope) OR dr.authority_sha256 IS DISTINCT FROM dr.envelope_sha256
  OR dr.envelope->>'work_id' IS DISTINCT FROM w.id::text OR dr.envelope->>'payload_sha256' IS DISTINCT FROM w.payload_sha256
  OR EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_attempts x WHERE x.receipt_id=dr.id)
  OR EXISTS(SELECT 1 FROM mission_narrative_internal.provider_authorizations x WHERE x.receipt_id=dr.id)
  OR EXISTS(SELECT 1 FROM staff_ai_quota_private.calls x WHERE x.producer='mission_generic_ai' AND x.source_id=dr.id)
  OR NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_audit a WHERE a.receipt_id=dr.id
   AND a.event_code='generic_pre_provider_failed' AND a.details->>'work_id'=w.id::text
   AND a.details->>'receipt_id'=w.receipt_id::text AND a.details->>'result_sha256'=w.result_sha256
   AND a.details->>'failure_code'='request_validation_failed' AND a.details->>'provider_calls'='0'
   AND (a.details->>'charged_cost_usd')::numeric=0) THEN RETURN NULL;END IF;
 SELECT (a.details->>'actor_user_id')::uuid INTO who FROM mission_narrative_internal.dispatch_audit a
  WHERE a.receipt_id=dr.id AND a.event_code='c1266_async_owner_v1' AND a.details->>'work_id'=w.id::text
   AND a.details->>'envelope_sha256'=dr.envelope_sha256;
 SELECT * INTO root FROM mission_generic_owner.event_outbox_v1 WHERE master_session_id=m.id AND event_domain='start' AND event_version=1;
 IF who IS NULL OR who IS DISTINCT FROM root.root_principal THEN RETURN NULL;END IF;
 SELECT * INTO rep FROM public.combat_v2_round_reports WHERE id=w.authority_receipt_id;
 IF NOT FOUND OR rep.mechanics_sha256 IS DISTINCT FROM public.combat_v2_sha256(rep.mechanics) OR rep.values_written IS DISTINCT FROM false
  OR rep.mechanics_sha256 IS DISTINCT FROM w.payload#>>'{scene_binding,report_sha256}'
  OR rep.round_id::text IS DISTINCT FROM w.payload#>>'{scene_binding,round_id}'
  OR NOT EXISTS(SELECT 1 FROM public.combat_v2_rounds r JOIN public.combat_v2_sessions s ON s.id=r.session_id
   WHERE r.id=rep.round_id AND s.id=w.encounter_id AND s.master_session_id=m.id AND s.location_id=m.location_id
    AND NOT public.combat_v2_values_written(s.id)) THEN RETURN NULL;END IF;
 sid:=mission_ai_service_owner.uuid5(w.id,'native-combat-writer-reissue/1:work');
 ev:=mission_ai_service_owner.uuid5(w.id,'native-combat-writer-reissue/1:event');
 rq:=mission_ai_service_owner.uuid5(w.id,'native-combat-writer-reissue/1:request');
 SELECT * INTO su FROM mission_generic_owner.work_items WHERE id=sid;
 SELECT * INTO au FROM mission_narrative_internal.dispatch_audit a WHERE a.receipt_id=dr.id AND a.event_code='native_combat_writer_preprovider_reissued_v1';
 IF su.id IS NOT NULL THEN
  IF su.master_session_id IS DISTINCT FROM w.master_session_id OR su.kind IS DISTINCT FROM 'narration'
   OR su.authority_receipt_id IS DISTINCT FROM rep.id OR su.encounter_id IS DISTINCT FROM w.encounter_id
   OR su.event_id IS DISTINCT FROM ev OR su.request_key IS DISTINCT FROM rq
   OR su.payload IS DISTINCT FROM w.payload OR su.payload_sha256 IS DISTINCT FROM w.payload_sha256
   OR su.step_key IS DISTINCT FROM w.step_key OR su.run_control_version IS DISTINCT FROM w.run_control_version
   OR su.definition_sha256 IS DISTINCT FROM w.definition_sha256 OR au.id IS NULL
   OR au.details->>'failed_work_id' IS DISTINCT FROM w.id::text OR au.details->>'old_result_sha256' IS DISTINCT FROM w.result_sha256
   OR au.details->>'successor_work_id' IS DISTINCT FROM su.id::text OR au.details->>'actor_user_id' IS DISTINCT FROM who::text
   OR au.details->>'payload_sha256' IS DISTINCT FROM w.payload_sha256 OR au.details->>'report_sha256' IS DISTINCT FROM rep.mechanics_sha256
   OR au.details->>'report_id' IS DISTINCT FROM rep.id::text OR au.details->>'provider_calls' IS DISTINCT FROM '0'
  THEN RETURN NULL;END IF;
  req:=jsonb_build_object('schema_version','mission-generic-request/1','master_session_id',m.id,'event_id',su.event_id,'request_key',su.request_key,'expected_revision',su.revision);
  SELECT * INTO wake FROM mission_generic_owner.event_outbox_v1 WHERE event_key=mission_ai_service_owner.uuid5(su.id,'server-event:writer-ready') AND event_version=1;
  IF wake.work_id IS DISTINCT FROM su.id OR wake.canonical_request IS DISTINCT FROM req OR wake.root_principal IS DISTINCT FROM who
   OR wake.source_id IS DISTINCT FROM su.id OR wake.source_sha256 IS DISTINCT FROM su.payload_sha256
   OR wake.root_event_key IS DISTINCT FROM root.root_event_key THEN RETURN NULL;END IF;
  published:=su.state='completed' AND su.message_id=rep.message_id AND rep.narration_state='pubblicata'
   AND su.finalized_at IS NOT NULL AND su.receipt_id IS NOT NULL
   AND EXISTS(SELECT 1 FROM public.combat_v2_rounds rr
    JOIN public.messages msg ON msg.id=rep.message_id AND msg.kind='fato' AND msg.location_id=m.location_id
     AND msg.character_id IS NULL AND msg.sender_user IS NULL AND msg.recipient_user IS NULL
    JOIN public.combat_v2_narratives n ON n.round_id=rr.id AND n.report_id=rep.id AND n.request_key=su.request_key
     AND n.kind='fato_ia' AND n.author_user IS NULL AND n.body=msg.body
    JOIN mission_narrative_internal.dispatch_audit da ON da.receipt_id=su.dispatch_receipt_id
     AND da.event_code='generic_finalized' AND da.details->>'work_id'=su.id::text
     AND da.details->>'receipt_id'=su.receipt_id::text AND da.details->>'state'='completed'
     AND da.details->>'result_sha256'=su.result_sha256 AND da.details->>'result_jsonb_sha256'=public.combat_v2_sha256(su.result)
     AND da.details->>'message_id'=msg.id::text AND da.details->>'stale'='false'
     AND da.details->>'outcome_uncertain'='false' AND da.details->'application_error_sqlstate'='null'::jsonb
    WHERE rr.id=rep.round_id AND rr.session_id=w.encounter_id AND rr.state='narrato' AND msg.body=su.result->>'text');
  IF published THEN final_publication21:=su.message_id;END IF;
  IF NOT published AND su.state='failed' THEN
   descendant20:=mission_generic_owner.native_combat_writer_reissue_proof_v1(su.id,p_user);
   IF descendant20->>'published'='true' AND descendant20->>'failed_work_id'=su.id::text
    AND descendant20->>'master_session_id'=m.id::text AND descendant20->>'report_id'=rep.id::text
    AND descendant20->>'payload_sha256'=w.payload_sha256 AND descendant20->>'report_sha256'=rep.mechanics_sha256
    AND descendant20->>'actor_user_id'=who::text
    AND (descendant20->>'successor_publication_id' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') IS TRUE
    AND descendant20->>'successor_publication_id'=rep.message_id::text THEN
     published:=true;final_publication21:=(descendant20->>'successor_publication_id')::uuid;
   END IF;
  END IF;
 ELSE
  IF au.id IS NOT NULL THEN RETURN NULL;END IF;
 END IF;
 IF NOT published THEN
  IF m.closed_at IS NOT NULL OR m.suspended_at IS NOT NULL OR rep.narration_state IS DISTINCT FROM 'attesa' OR rep.message_id IS NOT NULL
   OR NOT EXISTS(SELECT 1 FROM public.master_v2_participants mp WHERE mp.session_id=m.id AND mp.user_id_snapshot=p_user
     AND mp.left_at IS NULL AND mp.engagement_state='attivo')
   OR NOT EXISTS(SELECT 1 FROM public.mission_run_state rs JOIN public.combat_v2_rounds rr ON rr.id=rep.round_id AND rr.state='risolto'
    WHERE rs.master_session_id=m.id AND rs.run_phase='in_corso' AND rs.current_step_key=w.step_key AND rs.control_version=w.run_control_version)
   OR NOT mission_narrative_internal.scene_native_round_bound_v1(m.id,rep.round_id)
   OR w.payload#>>'{scene_binding,session_id}' IS DISTINCT FROM w.encounter_id::text
   OR w.payload#>>'{scene,snapshot_sha256}' IS DISTINCT FROM public.combat_v2_sha256(w.payload#>'{scene,snapshot}')
   OR w.payload#>'{barrier,closed}' IS DISTINCT FROM 'true'::jsonb
   OR w.payload#>'{barrier,required_receipt_ids}' IS DISTINCT FROM jsonb_build_array(rep.id)
   OR w.payload#>'{barrier,receipt_ids}' IS DISTINCT FROM jsonb_build_array(rep.id)
  THEN RETURN NULL;END IF;
 END IF;
 RETURN jsonb_build_object('schema_version','mission-native-combat-writer-reissue-proof/1',
  'master_session_id',m.id,'failed_work_id',w.id,'authority_receipt_id',rep.id,'report_id',rep.id,
  'report_sha256',rep.mechanics_sha256,'payload_sha256',w.payload_sha256,'owned_by_me',who=p_user,
  'can_reissue',who=p_user AND su.id IS NULL,'successor_work_id',su.id,'successor_request',req,
  'successor_publication_id',CASE WHEN published THEN final_publication21 ELSE NULL END,
  'can_resume',who=p_user AND su.id IS NOT NULL AND su.state='ready' AND su.finalized_at IS NULL,
  'actor_user_id',who,'audit_sha256',CASE WHEN au.id IS NULL THEN NULL ELSE public.combat_v2_sha256(au.details) END,'published',published);
END $function$;


CREATE OR REPLACE FUNCTION mission_generic_owner.progress_step(p_session uuid, p_user uuid, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m public.master_v2_sessions;r public.mission_run_state;e mission_generic_owner.encounters;
 s public.combat_v2_sessions;roundrow public.combat_v2_rounds;rep public.combat_v2_round_reports;
 sc jsonb;spec jsonb;settings jsonb;term jsonb;cap uuid;actor uuid;res jsonb;n integer;pending jsonb;c7_budget jsonb;c21_owned boolean;
begin
 perform mission_ai_board_owner.service_only();
 -- C9: freeze policy DML through proof, Native reserve and authorization.
 LOCK TABLE mission_narrative_internal.runtime_policy IN SHARE MODE;
 perform 1 from public.locations where id=(select location_id from mission_factory_owner.quest_run_sources where session_id=p_session) for update;
 if p_request is null then raise exception 'MGP_REQUEST_REQUIRED';end if;
 perform mission_generic_owner.dispatch_user(p_session,p_user);
 perform public.master_v2_lock_scope(p_session);
 select * into strict m from public.master_v2_sessions where id=p_session for update;
 perform mission_generic_owner.assert_runtime(p_session);
 select * into strict r from public.mission_run_state where master_session_id=p_session for update;
 if m.closed_at is not null then return jsonb_build_object('schema_version','mission-generic-progress/1','master_session_id',p_session,'state','closed','dispatch',null);end if;
 c21_owned:=(EXISTS(SELECT 1 FROM mission_public_owner.work_contracts_v1 sticky_wc
 WHERE sticky_wc.master_session_id=p_session AND sticky_wc.scope='staff_mission'
 AND sticky_wc.contract_sha256=public.combat_v2_sha256(sticky_wc.contract)
 AND sticky_wc.contract->>'schema_version'='mission-narrative-admission/3'
 AND sticky_wc.contract->'features' ? 'execution_authority_v1'
 AND (sticky_wc.contract#>>'{source_attestation,execution_authority,schema_version}'='c1266-work-execution-attestation/1' OR ((mission_generic_owner.c1266_historical_work_v1(sticky_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND sticky_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(sticky_wc.work_id)))
 AND sticky_wc.contract#>>'{source_attestation,execution_authority,execution_context}'='staff_mission'
 AND sticky_wc.contract#>>'{source_attestation,execution_authority,admission,kind}'='staff_finite'
 AND sticky_wc.contract#>>'{source_attestation,execution_authority,admission,resource_scope}'='staff_simulation'
 AND (sticky_wc.contract#>>'{source_attestation,execution_authority,source_scope,mission_id}'='5878822d-dc03-4ac2-ad0b-1547f0ab3fc0' OR ((mission_generic_owner.c1266_historical_work_v1(sticky_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND sticky_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(sticky_wc.work_id)))
 AND sticky_wc.contract#>>'{source_attestation,execution_authority,release_sha256}'=sticky_wc.release_sha256
 AND sticky_wc.contract#>>'{source_attestation,execution_authority,binding_sha256}'=sticky_wc.definition_sha256) OR EXISTS(SELECT 1 FROM mission_generic_owner.simulation_sources ss21
 JOIN mission_generic_owner.board_starts bs21 ON bs21.request_key=ss21.request_key
 JOIN mission_generic_owner.start_claims sc22 ON sc22.session_id=bs21.master_session_id
 JOIN mission_generic_owner.run_bindings rb21 ON rb21.master_session_id=bs21.master_session_id
 JOIN public.master_v2_sessions ms21 ON ms21.id=bs21.master_session_id
  AND ms21.mission_id=ss21.carrier_mission_id
 WHERE NOT EXISTS(SELECT 1 FROM mission_generic_owner.manual_staff_admissions_v1 manual_source WHERE manual_source.master_session_id=bs21.master_session_id) AND bs21.master_session_id=p_session
 AND ms21.owner_kind='ai_service' AND ms21.master_user IS NULL
 AND ms21.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
 AND (ss21.source_mission_id='5878822d-dc03-4ac2-ad0b-1547f0ab3fc0'::uuid OR (mission_generic_owner.c1266_staff_source_scope_v1(bs21.master_session_id) IS NOT NULL AND ss21.source_mission_id::text=mission_generic_owner.c1266_staff_source_scope_v1(bs21.master_session_id)#>>'{source_scope,mission_id}'))
 AND sc22.state='bound' AND sc22.simulation
 AND sc22.mission_id=ms21.mission_id AND sc22.location_id=ms21.location_id
 AND sc22.request_key=bs21.request_key
 AND bs21.simulation AND bs21.snapshot->'simulation'='true'::jsonb
 AND bs21.snapshot_sha256=mission_internal.fingerprint(bs21.snapshot)
 AND bs21.snapshot->>'schema_version'='mission-generic-opening-source/1'
 AND bs21.snapshot->>'mission_id'=ss21.carrier_mission_id::text
 AND bs21.snapshot->>'location_id'='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'
 AND rb21.snapshot_sha256=mission_internal.fingerprint(rb21.snapshot)
 AND rb21.snapshot->>'schema_version'='mission-generic-run/1'));
 c7_budget:=mission_generic_owner.c7_run_budget_v1(p_session,
 CASE WHEN c21_owned THEN false ELSE
 not exists(select 1 from mission_generic_owner.work_items pending_work where pending_work.master_session_id=p_session
 and pending_work.state in('claimed','authorized','provider_started')) END,null);
 if c7_budget->>'allowed'='false' then
  IF c21_owned THEN INSERT INTO public.mission_run_audit(master_session_id,event_code,metadata) VALUES(p_session,'C1266_CAMPAIGN_PROVIDER_STOP',jsonb_build_object('reason_code',c7_budget->>'reason_code','stop_causes',c7_budget->'stop_causes','boundary','progress'));END IF;
  perform mission_generic_owner.c7_run_budget_stop_v1(p_session);
  return jsonb_build_object('schema_version','mission-generic-progress/1','master_session_id',p_session,'state','paused','dispatch',null,'reason_code','MGPG_C7_RUN_BUDGET_STOP');
 end if;
 select id into strict cap from mission_ai_service_owner.capabilities where master_session_id=p_session and state='active';
 pending:=public.mission_generic_dispatch_next_v1(p_session,p_user);
 if pending->'request' is not null then return mission_generic_owner.progress_result(p_session,p_user,'work_pending');end if;
 if m.stato='preparazione' and r.run_phase='preparazione' and exists(select 1 from mission_generic_owner.work_items
 where master_session_id=p_session and state='failed' and payload ? 'opening_start_receipt_id') then
  res:=mission_generic_owner.abort_opening(p_session,p_user,mission_ai_service_owner.uuid5(p_session,'generic-abort-opening'));
  return jsonb_build_object('schema_version','mission-generic-progress/1','master_session_id',p_session,'state','aborted','dispatch',null);
 end if;
 if m.stato<>'in_corso' or m.suspended_at is not null or r.run_phase<>'in_corso'
 then return mission_generic_owner.progress_result(p_session,p_user,'paused');end if;
 perform mission_generic_owner.assert_combat_scope(p_session,cap);
 if exists(select 1 from mission_generic_owner.work_items wi where wi.master_session_id=p_session
 and wi.step_key=r.current_step_key and wi.run_control_version=r.control_version and wi.state='failed'
 and not (wi.kind='narration' AND wi.result->>'schema_version'='c1266-count-terminal-failure/1'
  AND wi.result->>'failure_code'='MISSION_INPUT_COUNT_OVERFLOW' AND EXISTS(
   SELECT 1 FROM LATERAL(SELECT mission_generic_owner.writer_count_reissue_proof_v1(wi.id,NULL) proof) solved49
   WHERE solved49.proof->>'schema_version'='mission-writer-count-reissue-proof/1'
    AND solved49.proof->>'old_work_id'=wi.id::text AND solved49.proof->>'master_session_id'=wi.master_session_id::text
    AND solved49.proof->'published'='true'::jsonb))
 and not (wi.kind='director' AND wi.result->'failure_codes' ? 'MISSION_PROVIDER_OUTPUT_RETENTION_FAILED'
  AND mission_generic_owner.retained_director_adoption_v1(wi.id,true) IS NOT NULL)
 and not (wi.kind='narration' AND wi.payload->>'schema_version'='mission-generic-narration/2'
  AND wi.payload->>'mode'='combat' AND EXISTS(SELECT 1 FROM LATERAL(
   SELECT mission_generic_owner.native_combat_writer_reissue_proof_v1(wi.id,p_user) proof) resolved_native
   WHERE resolved_native.proof->>'published'='true'))
 and not (wi.kind='narration' AND wi.payload->>'schema_version'='mission-generic-narration/3'
  AND wi.result->>'schema_version'='mission-generic-pre-provider-failure/1'
  AND wi.result->>'failure_code'='request_validation_failed'
  AND wi.result->>'provider_calls'='0' AND wi.result->>'charged_cost_usd'='0'
  AND EXISTS(
   SELECT 1
   FROM LATERAL(SELECT mission_generic_owner.combat_narration_reissue_proof_v1(wi.id,p_user) x) native_reissue
   JOIN mission_generic_owner.work_items successor ON successor.id=(native_reissue.x->>'successor_work_id')::uuid
     AND successor.master_session_id=wi.master_session_id AND successor.authority_receipt_id=wi.authority_receipt_id
     AND successor.kind='narration' AND successor.state='completed' AND successor.finalized_at IS NOT NULL
     AND successor.receipt_id IS NOT NULL AND successor.result_sha256 ~ '^[0-9a-f]{64}$'
     AND successor.payload=wi.payload AND successor.payload_sha256=wi.payload_sha256
   JOIN mission_narrative_internal.dispatch_receipts native_receipt ON native_receipt.id=successor.dispatch_receipt_id
     AND native_receipt.master_session_id=p_session AND native_receipt.authority_receipt_id=successor.id
     AND native_receipt.request_key=successor.request_key AND native_receipt.status='success' AND native_receipt.finalized_at IS NOT NULL
     AND native_receipt.request_fingerprint=mission_internal.fingerprint(jsonb_build_object('schema_version','mission-generic-request/1','master_session_id',successor.master_session_id,'event_id',successor.event_id,'request_key',successor.request_key,'expected_revision',successor.revision))
     AND native_receipt.envelope_sha256=public.combat_v2_sha256(native_receipt.envelope)
     AND native_receipt.authority_sha256=native_receipt.envelope_sha256
   JOIN mission_generic_owner.unified_batches native_batch ON native_batch.id=successor.authority_receipt_id
     AND native_batch.master_session_id=p_session AND native_batch.writer_work_id=successor.id
     AND native_batch.retired_at IS NULL AND native_batch.state='published' AND native_batch.published_at IS NOT NULL
     AND native_batch.message_id=successor.message_id AND native_batch.source_window_id IS NULL
     AND native_batch.payload=successor.payload AND native_batch.payload_sha256=successor.payload_sha256
   JOIN public.combat_v2_round_reports native_report ON native_report.id=native_batch.source_report_id
     AND native_report.round_id=native_batch.source_round_id
     AND native_report.narration_state='pubblicata' AND native_report.message_id=successor.message_id
     AND native_report.values_written IS FALSE
     AND native_report.mechanics_sha256=public.combat_v2_sha256(native_report.mechanics)
   JOIN public.combat_v2_rounds native_round ON native_round.id=native_report.round_id
     AND native_round.session_id=native_batch.encounter_id AND native_round.state='narrato'
   JOIN mission_generic_owner.unified_report_publications native_publication ON native_publication.report_id=native_report.id
     AND native_publication.round_id=native_round.id AND native_publication.batch_id=native_batch.id
     AND native_publication.primary_report AND native_publication.message_id=successor.message_id
   JOIN public.messages native_message ON native_message.id=successor.message_id AND native_message.kind='fato'
     AND native_message.location_id=m.location_id AND native_message.character_id IS NULL AND native_message.recipient_user IS NULL
     AND native_message.body=successor.result->>'text'
   JOIN public.combat_v2_narratives native_narrative ON native_narrative.report_id=native_report.id
     AND native_narrative.round_id=native_round.id AND native_narrative.request_key=successor.request_key
     AND native_narrative.kind='fato_ia' AND native_narrative.author_user IS NULL AND native_narrative.body=native_message.body
   WHERE native_reissue.x->>'schema_version'='mission-combat-narration-reissue-proof/1'
     AND native_reissue.x->>'published'='true'
     AND native_reissue.x->>'master_session_id'=p_session::text AND native_reissue.x->>'failed_work_id'=wi.id::text
     AND native_reissue.x->>'batch_id'=native_batch.id::text
     AND native_reissue.x->>'payload_sha256'=wi.payload_sha256
     AND mission_generic_owner.c1266_historical_work_v1(successor.id)->>'schema_version'='c1266-work-execution-attestation/3'
     AND EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_audit finalized
       WHERE finalized.receipt_id=native_receipt.id AND finalized.event_code='generic_finalized'
         AND finalized.details->>'work_id'=successor.id::text AND finalized.details->>'receipt_id'=successor.receipt_id::text
         AND finalized.details->>'message_id'=native_message.id::text AND finalized.details->>'state'='completed'
         AND finalized.details->>'result_sha256'=successor.result_sha256
         AND finalized.details->>'result_jsonb_sha256'=public.combat_v2_sha256(successor.result)
         AND finalized.details->>'stale'='false' AND finalized.details->>'outcome_uncertain'='false'
         AND finalized.details->'application_error_sqlstate'='null'::jsonb)
     AND (native_batch.secondary_report_id IS NULL OR EXISTS(
       SELECT 1 FROM public.combat_v2_round_reports secondary_report
       JOIN mission_generic_owner.unified_report_publications secondary_publication
         ON secondary_publication.report_id=secondary_report.id AND secondary_publication.round_id=secondary_report.round_id
         AND secondary_publication.batch_id=native_batch.id AND NOT secondary_publication.primary_report
         AND secondary_publication.message_id=native_message.id
       WHERE secondary_report.id=native_batch.secondary_report_id AND secondary_report.narration_state='pubblicata'
         AND secondary_report.message_id IS NULL AND secondary_report.values_written IS FALSE
         AND secondary_report.mechanics_sha256=public.combat_v2_sha256(secondary_report.mechanics)))
  ))
 and NOT ((wi.id='e76f31f2-eded-495e-9c5f-f03461c5cc3a'::uuid AND wi.master_session_id='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid AND wi.kind='director' AND wi.state='failed' AND wi.message_id IS NULL
 AND wi.payload_sha256='f962403b87a5c6bf6930818e4d5655e57451d1adebbd404702f4a75ae7bcf03a' AND wi.payload_sha256=public.combat_v2_sha256(wi.payload)
 AND wi.result_sha256='73c3158fe44061c34b1dc410daec3fda85cd98ee3fadbbc063bbfdea5982571d' AND public.combat_v2_sha256(wi.result)='cee81d0c273baaf64705be7b53c884778f063bcd739461c777666cdcbd440ad4'
 AND wi.result->>'ok'='true' AND wi.result->>'provider_calls'='1' AND wi.result->>'outcome_uncertain'='false'
 AND EXISTS(SELECT 1 FROM mission_public_owner.work_contracts_v1 wc WHERE wc.work_id=wi.id AND wc.contract_sha256='ad13df1382af67d4af779f9f16790085468f3c14a9dd9c2c16d145477038f302' AND wc.contract_sha256=public.combat_v2_sha256(wc.contract) AND wc.release_sha256='feaf314957d5dab65a2420748e935015e5aa2e16fb2aed996e38e11e57189243' AND wc.contract->'features'?'provider_output_retention_v1')
 AND EXISTS(SELECT 1 FROM mission_narrative_internal.provider_outputs_v1 raw WHERE raw.id=(wi.result->>'output_receipt_id')::uuid AND raw.work_id=wi.id AND raw.authorization_id=wi.authorization_id AND raw.dispatch_id=wi.dispatch_id AND raw.dispatch_receipt_id=wi.dispatch_receipt_id AND raw.raw_sha256=wi.result->>'raw_sha256' AND raw.raw_sha256=encode(extensions.digest(convert_to(raw.raw_output,'UTF8'),'sha256'),'hex'))
 AND EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts dr JOIN mission_narrative_internal.dispatch_audit fa ON fa.receipt_id=dr.id AND fa.event_code='generic_finalized'
  JOIN staff_ai_quota_private.calls q ON q.producer='mission_generic_ai' AND q.source_id=dr.id AND q.scope_id=wi.master_session_id AND q.call_no=1 AND q.state='settled' AND q.charged_usd=dr.charged_cost_usd
 WHERE dr.id=wi.dispatch_receipt_id AND dr.master_session_id=wi.master_session_id AND dr.authority_receipt_id=wi.id AND dr.request_key=wi.request_key AND dr.status='success' AND dr.dispatch_count=1 AND dr.finalized_at IS NOT NULL
 AND fa.details->>'work_id'=wi.id::text AND fa.details->>'receipt_id'=wi.receipt_id::text AND fa.details->>'result_sha256'=wi.result_sha256 AND fa.details->>'result_jsonb_sha256'=public.combat_v2_sha256(wi.result)
 AND fa.details->>'application_error_sqlstate'='23505' AND fa.details->'command_receipt'='null'::jsonb AND fa.details->>'stale'='false' AND fa.details->>'outcome_uncertain'='false')) AND EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_audit ap JOIN mission_generic_owner.unified_batches ab ON ab.decision_work_id=wi.id AND ab.master_session_id=wi.master_session_id
 JOIN mission_generic_owner.work_items aw ON aw.id=ab.writer_work_id AND aw.master_session_id=wi.master_session_id AND aw.authority_receipt_id=ab.id AND aw.kind='narration'
 WHERE ap.receipt_id=wi.dispatch_receipt_id AND ap.event_code='c1266_saved_director_applied' AND ap.details->>'schema_version'='c1266-saved-director-application/1'
 AND ap.details->>'master_session_id'=wi.master_session_id::text AND ap.details->>'work_id'=wi.id::text AND ap.details->>'result_sha256'=wi.result_sha256 AND ap.details->>'batch_id'=ab.id::text AND ap.details->>'writer_work_id'=aw.id::text AND ap.details->>'generation_http_calls'='0' AND ap.details->>'failed_work_preserved'='true'
 AND ab.retired_at IS NULL AND ab.state='published' AND aw.state='completed' AND ab.message_id=aw.message_id AND EXISTS(SELECT 1 FROM public.messages pm JOIN mission_generic_owner.unified_source_windows ps ON ps.id=ab.source_window_id AND ps.consumed_message_id=pm.id JOIN mission_generic_owner.unified_segment_publications_v4 pp ON pp.work_id=aw.id AND pp.message_id=pm.id WHERE pm.id=aw.message_id AND pm.kind='fato' AND pm.recipient_user IS NULL AND pm.body=aw.result->>'text')))
 and NOT (wi.kind='director' AND wi.state='failed' AND wi.result->>'ok'='true'
 AND wi.payload_sha256=public.combat_v2_sha256(wi.payload)
 AND EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts healed_dr
  JOIN mission_narrative_internal.dispatch_audit healed_a ON healed_a.receipt_id=healed_dr.id AND healed_a.event_code='c1266_saved_director_applied'
  JOIN mission_narrative_internal.dispatch_audit healed_f ON healed_f.receipt_id=healed_dr.id AND healed_f.event_code='generic_finalized'
  JOIN mission_generic_owner.unified_batches healed_b ON healed_b.decision_work_id=wi.id AND healed_b.master_session_id=p_session
  JOIN mission_generic_owner.unified_source_windows healed_s ON healed_s.id=healed_b.source_window_id AND healed_s.work_id=wi.id AND healed_s.master_session_id=p_session
  JOIN mission_generic_owner.work_items healed_writer ON healed_writer.id=healed_b.writer_work_id AND healed_writer.master_session_id=p_session AND healed_writer.authority_receipt_id=healed_b.id
  JOIN public.messages healed_msg ON healed_msg.id=healed_writer.message_id AND healed_msg.kind='fato' AND healed_msg.recipient_user IS NULL AND healed_msg.body=healed_writer.result->>'text'
  WHERE healed_dr.id=wi.dispatch_receipt_id AND healed_dr.master_session_id=p_session AND healed_dr.authority_receipt_id=wi.id AND healed_dr.request_key=wi.request_key
   AND healed_dr.status='success' AND healed_dr.dispatch_count=1 AND healed_dr.finalized_at IS NOT NULL
   AND healed_a.details->>'schema_version'='c1266-saved-director-application/1' AND healed_a.details->>'master_session_id'=p_session::text
   AND healed_a.details->>'work_id'=wi.id::text AND healed_a.details->>'result_sha256'=wi.result_sha256
   AND healed_a.details->>'batch_id'=healed_b.id::text AND healed_a.details->>'writer_work_id'=healed_writer.id::text
   AND healed_a.details->>'generation_http_calls'='0' AND healed_a.details->>'failed_work_preserved'='true'
   AND healed_f.details->>'work_id'=wi.id::text AND healed_f.details->>'receipt_id'=wi.receipt_id::text
   AND healed_f.details->>'result_sha256'=wi.result_sha256 AND healed_f.details->>'result_jsonb_sha256'=public.combat_v2_sha256(wi.result)
   AND healed_b.state='published' AND healed_b.published_at IS NOT NULL AND healed_b.message_id=healed_writer.message_id
   AND healed_s.consumed_message_id=healed_b.message_id AND healed_s.superseded_at IS NULL
   AND healed_s.source_sha256=wi.payload_sha256 AND healed_writer.kind='narration' AND healed_writer.state='completed'
   AND healed_writer.payload=healed_b.payload AND healed_writer.payload_sha256=healed_b.payload_sha256
   AND healed_writer.payload_sha256=public.combat_v2_sha256(healed_writer.payload)
   AND EXISTS(SELECT 1 FROM mission_generic_owner.unified_segment_publications_v4 healed_pub WHERE healed_pub.work_id=healed_writer.id AND healed_pub.message_id=healed_msg.id)
   AND EXISTS(SELECT 1 FROM staff_ai_quota_private.calls healed_q WHERE healed_q.producer='mission_generic_ai' AND healed_q.scope_id=p_session AND healed_q.source_id=healed_dr.id AND healed_q.call_no=1 AND healed_q.state='settled' AND healed_q.charged_usd=healed_dr.charged_cost_usd)))
 and not (wi.id='849c4dac-280f-4331-9d6e-4197445f5ae4'::uuid
   and wi.kind='narration'
   and wi.authority_receipt_id='44639b01-ea89-4368-847c-0e40c6eaf9cc'::uuid
   and wi.result->'failure_codes'='["MISSION_PROFILE_AUDIT_INVALID"]'::jsonb
   and wi.payload_sha256=public.combat_v2_sha256(wi.payload)
   and exists (
     select 1 from mission_generic_owner.unified_batches recovered
     join mission_generic_owner.work_items successor on successor.id=recovered.writer_work_id
     join mission_generic_owner.flow_staff_sessions staff on staff.master_session_id=recovered.master_session_id and staff.enabled
     join public.master_v2_sessions session on session.id=staff.master_session_id and session.owner_kind='ai_service' and session.closed_at is null
     join public.locations location on location.id=session.location_id and location.is_test
     where recovered.id=wi.authority_receipt_id and recovered.master_session_id=p_session
       and recovered.state='published' and recovered.message_id is not null
       and recovered.payload_sha256=wi.payload_sha256
       and successor.id='6027edf0-355d-47c9-b88c-9a9e1a2d795b'::uuid
       and successor.master_session_id=p_session and successor.kind='narration'
       and successor.state='completed' and successor.message_id=recovered.message_id
       and successor.authority_receipt_id=recovered.id
       and successor.payload_sha256=recovered.payload_sha256
   ))
 and not exists(select 1 from mission_generic_owner.unified_source_windows released_source
   join mission_generic_owner.role_window_cursors staff_cursor
     on staff_cursor.master_session_id=released_source.master_session_id
   where (released_source.work_id=wi.id
     or exists(select 1 from mission_generic_owner.unified_batches released_batch
       where released_batch.source_window_id=released_source.id
         and released_batch.writer_work_id=wi.id))
     and released_source.master_session_id=p_session
     and mission_generic_owner.role_source_released_v4(released_source.id))
 and not (wi.id='d7c28505-7b5e-4e80-a148-3dceb6884174'::uuid
   and p_session='b70b23cf-bad8-475d-a56a-d9c549e35d84'::uuid
   and mission_generic_owner.flow_scope_enabled(p_session)
   and wi.kind='director' and wi.result->>'ok'='true'
   and wi.result_sha256='103cb96c6026f2dd043eaa3486bb39dac68a1765a7d01995ca5dcaefb5b46b3d'
   and exists(select 1 from mission_generic_owner.unified_batches repaired
      where repaired.decision_work_id=wi.id and repaired.source_window_id=wi.authority_receipt_id
       and repaired.master_session_id=p_session and repaired.step_key=wi.step_key
       and repaired.run_control_version=wi.run_control_version
       and repaired.composition_kind='narrative_continuation'
       and repaired.decision=wi.result->'decision'
       and repaired.decision_sha256=public.combat_v2_sha256(wi.result->'decision')
       and repaired.writer_work_id is not null and repaired.state in('ready','published')))
 and not (p_session='b70b23cf-bad8-475d-a56a-d9c549e35d84'::uuid
   and mission_generic_owner.flow_scope_enabled(p_session)
   and exists(select 1 from mission_generic_owner.unified_source_windows superseded
     where superseded.id=wi.id and superseded.work_id=wi.id
       and superseded.master_session_id=p_session
       and superseded.superseded_at is not null and superseded.consumed_message_id is null))
 and (wi.result->>'schema_version'='mission-generic-pre-provider-failure/1'
  and wi.result->>'failure_code'='request_validation_failed'
  and wi.result->>'provider_calls'='0' and wi.result->>'charged_cost_usd'='0'
  and wi.result_sha256=public.combat_v2_sha256(wi.result)
  and wi.payload_sha256=public.combat_v2_sha256(wi.payload)
  and (select count(*) from public.mission_run_audit qa
   join mission_generic_owner.work_items rw on rw.id::text=qa.metadata->>'new_work_id'
   join mission_generic_owner.unified_batches ub on ub.id=wi.authority_receipt_id and ub.writer_work_id=rw.id
   where qa.master_session_id=p_session and qa.event_code='QA_PREPROVIDER_NARRATION_RECOVERED'
    and qa.metadata->>'failed_work_id'=wi.id::text and qa.metadata->>'batch_id'=ub.id::text
    and qa.metadata->>'recovery_dedupe'=rw.dedupe_key
    and rw.master_session_id=wi.master_session_id and rw.authority_receipt_id=wi.authority_receipt_id
    and rw.kind=wi.kind and rw.state='completed' and ub.master_session_id=wi.master_session_id
    and ub.state='published' and rw.payload=ub.payload and rw.payload_sha256=ub.payload_sha256
    and rw.payload_sha256=public.combat_v2_sha256(rw.payload))=1) is not true
  and not (
    wi.id='3076c471-37c5-438e-8f50-0a790b787e05'::uuid
    and wi.kind='choice'
    and p_session='93d78313-abde-4087-9eb7-7b96bc0fa089'::uuid
    and wi.encounter_id='deadfef6-5b16-4921-aa86-b86ffad6f2f2'::uuid
    and wi.payload->>'actor_id'='1f662f89-447a-4cd3-9873-a5953a0e0d91'
    and wi.payload->>'round_id'='44061137-17a3-43fa-9225-d29aaa26e58a'
    and (
      (
        (select md5(prosrc) from pg_proc where oid='mission_generic_owner.enqueue_choice(uuid,uuid,uuid)'::regprocedure)
          ='76a88f0e93752e1456c90d160a7a855d'
        and exists (
          select 1 from mission_generic_owner.unified_batches ub
          where ub.master_session_id=p_session
            and ub.id='fbfc8e29-8724-4241-b2fe-22dbc17eb9e7'::uuid
            and ub.encounter_id=wi.encounter_id
            and ub.state='preparing' and ub.entry_side='png'
            and ub.next_round_id='44061137-17a3-43fa-9225-d29aaa26e58a'::uuid
        )
        and not exists (
          select 1 from mission_generic_owner.work_items rw
          where rw.master_session_id=p_session
            and rw.dedupe_key=wi.dedupe_key||':recovery:'||wi.id::text
        )
        and not exists (
          select 1 from public.combat_v2_declarations d
          where d.round_id='44061137-17a3-43fa-9225-d29aaa26e58a'::uuid
            and d.actor_id='1f662f89-447a-4cd3-9873-a5953a0e0d91'::uuid
        )
      )
      or exists (
        select 1 from mission_generic_owner.work_items rw
        where rw.master_session_id=p_session
          and rw.dedupe_key=wi.dedupe_key||':recovery:'||wi.id::text
          and rw.kind='choice' and rw.state='completed'
          and rw.encounter_id=wi.encounter_id
          and rw.payload->>'actor_id'=wi.payload->>'actor_id'
          and rw.payload->>'round_id'=wi.payload->>'round_id'
          and rw.payload_sha256=public.combat_v2_sha256(rw.payload)
          and rw.result_sha256=public.combat_v2_sha256(rw.result)
          and exists (
            select 1 from public.combat_v2_declarations d
            where d.round_id='44061137-17a3-43fa-9225-d29aaa26e58a'::uuid
              and d.actor_id='1f662f89-447a-4cd3-9873-a5953a0e0d91'::uuid
          )
      )
    )
  )
)
 then return mission_generic_owner.progress_result(p_session,p_user,'needs_attention');end if;
 if exists(select 1 from public.mission_run_outbox uo where uo.master_session_id=p_session and uo.state='pending' and not exists(select 1 from mission_generic_owner.unified_batches ub where ub.master_session_id=p_session and ub.state='preparing' and ub.route->>'event_id'=uo.event_id::text))
 then return mission_generic_owner.progress_result(p_session,p_user,'narration_pending');end if;
 if not exists(select 1 from mission_factory_owner.quest_run_sources where session_id=p_session) then
 res:=mission_rapid_owner.try_native_terminal(p_session);
 if res is not null then return mission_generic_owner.progress_result(p_session,p_user,'transitioned');end if;
 settings:=mission_generic_owner.run_plan_settings(p_session);
 select count(*),jsonb_agg(x)->0 into n,term from jsonb_array_elements(settings->'terminal_steps') x where x->>'step_key'=r.current_step_key;
 if n>1 then raise exception 'MGP_PLAN_TERMINAL_AMBIGUOUS';end if;
 if n=1 AND mission_generic_owner.staff_finish_policy_v1(p_session) IS DISTINCT FROM true then
  res:=mission_generic_owner.finish_mission(p_session,term->>'outcome');
  return jsonb_build_object('schema_version','mission-generic-progress/1','master_session_id',p_session,'state','closed','dispatch',null);
 end if;
 end if;
 res:=mission_generic_owner.unified_advance(p_session,p_user,p_request);
 if res is not null then return res;end if;
 sc:=mission_generic_owner.scene(p_session,r.current_step_key);
 select count(*) into n from mission_generic_owner.encounters x join public.combat_v2_sessions y on y.id=x.encounter_id
 where x.master_session_id=p_session and y.closed_at is null;
 if n>1 then raise exception 'MGP_MULTIPLE_ACTIVE_ENCOUNTERS';end if;
 select x.* into e from mission_generic_owner.encounters x join public.combat_v2_sessions y on y.id=x.encounter_id
 where x.master_session_id=p_session and y.closed_at is null;
 if e.encounter_id is null then
  select count(*),jsonb_agg(x)->0 into n,spec from jsonb_array_elements(sc->'encounters') x
  where not exists(select 1 from mission_generic_owner.encounters z where z.master_session_id=p_session
   and z.step_key=r.current_step_key and z.run_control_version=r.control_version and z.encounter_key=x->>'encounter_key');
  if n=0 then return mission_generic_owner.progress_result(p_session,p_user,'waiting_choice');end if;
  if n>1 then raise exception 'MGP_ENCOUNTER_OPEN_POINT_AMBIGUOUS' using errcode='22023';end if;
  res:=public.mission_generic_combat_open_v1(p_session,spec->>'encounter_key',r.control_version,
    mission_ai_service_owner.uuid5(p_session,'encounter:'||r.control_version||':'||(spec->>'encounter_key')));
  select * into strict e from mission_generic_owner.encounters where encounter_id=(res->>'encounter_id')::uuid;
 end if;
 if e.step_key<>r.current_step_key or e.run_control_version<>r.control_version then raise exception 'MGP_ENCOUNTER_VISIT_DRIFT';end if;
 select * into strict s from public.combat_v2_sessions where id=e.encounter_id for update;
 if s.state='risolto' then
  res:=mission_generic_owner.advance_combat_terminal(p_session,s.id);
  return mission_generic_owner.progress_result(p_session,p_user,'transitioned');
 end if;
 if s.state<>'in_corso' then raise exception 'MGP_ENCOUNTER_STATE';end if;
 select * into strict roundrow from public.combat_v2_rounds where session_id=s.id order by round_no desc limit 1 for update;
 if roundrow.state in('risolto','narrazione') then
  select * into strict rep from public.combat_v2_round_reports where round_id=roundrow.id;
  if rep.narration_state<>'attesa' then raise exception 'MGP_REPORT_STATE';end if;
  return mission_public_owner.enqueue_combat_unified_v1(p_session,rep.id,p_user);
 end if;
 -- Common offre difese soltanto nella fase nativa raccolta_difese. Un target
 -- già creato durante raccolta_azioni non anticipa la scelta del PNG.
 select a.id into actor from public.combat_v2_actors a where a.session_id=s.id and a.actor_kind='png' and a.state='attivo'
 and roundrow.phase='raccolta_difese' and roundrow.state='raccolta_difese'
 and exists(select 1 from jsonb_array_elements(e.actor_map) x where x->>'actor_id'=a.id::text and x->>'mechanical_binding_id' is not null)
 and exists(select 1 from public.combat_v2_attack_targets t where t.round_id=roundrow.id and t.target_actor_id=a.id
  and not exists(select 1 from public.combat_v2_defense_coverages c where c.attack_target_id=t.id)) order by a.id limit 1;
 if actor is not null then
  res:=mission_generic_owner.enqueue_choice(p_session,s.id,actor);
  return mission_generic_owner.progress_result(p_session,p_user,'choice_ready');
 end if;
 if exists(select 1 from public.combat_v2_actors a where a.session_id=s.id and a.actor_kind='pg' and a.state='attivo'
 and clan_marionettisti_private.can_declare(a.id) and not exists(select 1 from public.combat_v2_declarations d
  where d.round_id=roundrow.id and d.actor_id=a.id and d.kind in('attacco','movimento','utilita','passa')))
 then return mission_generic_owner.progress_result(p_session,p_user,'waiting_player');end if;
 -- La barriera PG precedente resta obbligatoria; ogni PNG riceve una
 -- principale soltanto se manca e il round raccoglie ancora azioni.
 IF mission_narrative_internal.scene_opening_receipt_v1(roundrow.id) IS NULL THEN
 select a.id into actor from public.combat_v2_actors a where a.session_id=s.id and a.actor_kind='png' and a.state='attivo'
 and roundrow.phase='raccolta_azioni' and roundrow.state='raccolta_azioni'
 and clan_marionettisti_private.can_declare(a.id)
 and exists(select 1 from jsonb_array_elements(e.actor_map) x where x->>'actor_id'=a.id::text and x->>'mechanical_binding_id' is not null)
 and not exists(select 1 from public.combat_v2_declarations d where d.round_id=roundrow.id and d.actor_id=a.id
 and d.kind in('attacco','movimento','utilita','passa')) order by a.id limit 1;
 ELSE actor:=NULL;END IF;
 if actor is not null then
  res:=mission_generic_owner.enqueue_choice(p_session,s.id,actor);
  return mission_generic_owner.progress_result(p_session,p_user,'choice_ready');
 end if;
 IF mission_narrative_internal.scene_native_round_bound_v1(p_session,roundrow.id)
  AND roundrow.phase='raccolta_difese'
  AND EXISTS(SELECT 1 FROM public.combat_v2_attack_targets pg_target
    JOIN public.combat_v2_actors pg ON pg.id=pg_target.target_actor_id AND pg.actor_kind='pg'
    WHERE pg_target.round_id=roundrow.id AND pg_target.state='attesa_difesa'
     AND NOT EXISTS(SELECT 1 FROM public.combat_v2_defense_coverages covered WHERE covered.attack_target_id=pg_target.id))
  AND NOT EXISTS(SELECT 1 FROM public.combat_v2_attack_targets npc_target
    JOIN public.combat_v2_actors png ON png.id=npc_target.target_actor_id AND png.actor_kind='png' AND png.state='attivo'
    WHERE npc_target.round_id=roundrow.id
     AND NOT EXISTS(SELECT 1 FROM public.combat_v2_defense_coverages covered WHERE covered.attack_target_id=npc_target.id))
  AND EXISTS(SELECT 1 FROM public.combat_v2_declarations dd JOIN public.combat_v2_actors png ON png.id=dd.actor_id
    WHERE dd.round_id=roundrow.id AND png.actor_kind='png' AND dd.kind IN('attacco','movimento','utilita','passa','difesa','nessuna')
     AND NOT(dd.kind='nessuna' AND coalesce(dd.declaration_text,'')='')
     AND NOT mission_narrative_internal.scene_native_declaration_public_v1(dd.id))
 THEN res:=mission_narrative_internal.scene_combat_intent_prepare_v1(p_session,roundrow.id);
  IF res IS NOT NULL THEN RETURN mission_generic_owner.progress_result(p_session,p_user,'narration_ready');END IF;
 END IF;
 if (select count(*) from public.combat_v2_declarations where round_id=roundrow.id and kind in('attacco','movimento','utilita','passa'))
 <>combat_consumer_private.expected_main_count(roundrow.id)
 then return mission_generic_owner.progress_result(p_session,p_user,'waiting_player');end if;
 if not combat_v2_multitarget_internal.round_complete(roundrow.id)
 then return mission_generic_owner.progress_result(p_session,p_user,'waiting_defense');end if;
 if roundrow.evaluation_mode<>'neutra' and exists(select 1 from public.combat_v2_declarations d
 join public.combat_v2_actors a on a.id=d.actor_id where d.round_id=roundrow.id and a.actor_kind='pg' and d.kind in('attacco','difesa')
 and not exists(select 1 from public.combat_v2_ratings x where x.declaration_id=d.id and x.is_active))
 then return mission_generic_owner.progress_result(p_session,p_user,'waiting_quality');end if;
 -- Neutra: il resolver nativo registra zero con fonte neutralita_sistema. Nessun voto IA.
 if (select is_test from public.locations where id=m.location_id) and (public.combat_v2_values_written(s.id)
 or not combat_panel_private.uses_simulated_pools(s.id)) then raise exception 'MGP_SIMULATION_SCOPE' using errcode='42501';end if;
 res:=public.combat_v2_round_resolve(roundrow.id,mission_ai_service_owner.uuid5(roundrow.id,'generic-resolve'));
 select * into strict rep from public.combat_v2_round_reports where id=(res#>>'{data,report_id}')::uuid and round_id=roundrow.id;
 return mission_public_owner.enqueue_combat_unified_v1(p_session,rep.id,p_user);
end $function$;


CREATE OR REPLACE FUNCTION mission_narrative_internal.scene_publish_v1(p_work uuid, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE w mission_generic_owner.work_items;s mission_narrative_internal.scene_sources_v1;
 r mission_narrative_internal.scene_runtime_v1;m public.master_v2_sessions;run public.mission_run_state;
 bs mission_generic_owner.board_starts;ev public.mission_run_events;ob public.mission_run_outbox;
 upd jsonb;phase jsonb;step text;target text;memory jsonb;mid uuid;body_sha text;pub uuid;opened jsonb;history jsonb;
BEGIN
 PERFORM mission_ai_board_owner.service_only();
 PERFORM 1 FROM public.locations WHERE id=(SELECT master.location_id FROM public.master_v2_sessions master JOIN mission_generic_owner.work_items work ON work.master_session_id=master.id WHERE work.id=p_work) FOR UPDATE;
 SELECT * INTO STRICT w FROM mission_generic_owner.work_items WHERE id=p_work FOR UPDATE;
 PERFORM 1 FROM mission_generic_owner.role_window_cursors WHERE master_session_id=w.master_session_id FOR UPDATE;
 SELECT * INTO STRICT s FROM mission_narrative_internal.scene_sources_v1 WHERE work_id=w.id FOR UPDATE;
 SELECT * INTO STRICT r FROM mission_narrative_internal.scene_runtime_v1 WHERE id=s.scene_id FOR UPDATE;
 SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=w.master_session_id FOR UPDATE;
 SELECT * INTO STRICT run FROM public.mission_run_state WHERE master_session_id=w.master_session_id FOR UPDATE;
 IF s.published_message_id IS NOT NULL THEN
  IF NOT EXISTS(SELECT 1 FROM public.messages WHERE id=s.published_message_id AND kind='fato'
   AND location_id=m.location_id AND body=p_result->>'text') THEN RAISE EXCEPTION 'SCENE56_PUBLICATION_REPLAY_CONFLICT' USING ERRCODE='PT409';END IF;
  RETURN jsonb_build_object('message_id',s.published_message_id,'replayed',true);
 END IF;
 PERFORM mission_narrative_internal.scene_source_assert_v1(w.id);
 upd:=p_result->'scene_update';memory:=upd->'scene_memory';step:=upd->>'next_step';
 SELECT x INTO STRICT phase FROM jsonb_array_elements(r.snapshot->'phases')x WHERE x->>'phase_key'=r.current_phase_key;
 IF p_result->'ok' IS DISTINCT FROM 'true'::jsonb OR jsonb_typeof(p_result->'text') IS DISTINCT FROM 'string'
  OR length(p_result->>'text') NOT BETWEEN 1 AND 5000
  OR NOT mission_factory_owner.keys_exact_v2(upd,ARRAY['schema_version','scene_id','source_window_id','source_revision','state_version','snapshot_sha256','next_step','scene_memory'])
  OR upd->>'schema_version' IS DISTINCT FROM 'mission-narrative-scene-update/1'
  OR upd->>'scene_id' IS DISTINCT FROM r.id::text OR upd->>'source_window_id' IS DISTINCT FROM s.id::text
  OR upd->>'source_revision' IS DISTINCT FROM s.source_revision
  OR upd->>'state_version' IS DISTINCT FROM s.state_version::text
  OR upd->>'snapshot_sha256' IS DISTINCT FROM s.snapshot_sha256
  OR (s.request_kind<>'combat_intent' AND (phase->'next_steps' ? step) IS DISTINCT FROM true)
  OR (s.request_kind IN('initial_opening','combat_intent') AND step IS DISTINCT FROM 'stay')
  OR NOT mission_factory_owner.keys_exact_v2(memory,ARRAY['state','known','open','used'])
  OR jsonb_typeof(memory->'state') IS DISTINCT FROM 'string' OR length(memory->>'state')>600
  OR jsonb_typeof(memory->'known') IS DISTINCT FROM 'array' OR jsonb_typeof(memory->'open') IS DISTINCT FROM 'array'
  OR jsonb_typeof(memory->'used') IS DISTINCT FROM 'array'
 THEN RAISE EXCEPTION 'SCENE56_RESULT_TECHNICAL_SHAPE' USING ERRCODE='22023';END IF;
 IF jsonb_array_length(memory->'known')>16 OR jsonb_array_length(memory->'open')>10 OR jsonb_array_length(memory->'used')>20
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(memory->'known')x WHERE jsonb_typeof(x)<>'string' OR length(x#>>'{}')>180)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(memory->'open')x WHERE jsonb_typeof(x)<>'string' OR length(x#>>'{}')>180)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(memory->'used')x WHERE jsonb_typeof(x)<>'string' OR length(x#>>'{}')>90)
 THEN RAISE EXCEPTION 'SCENE56_MEMORY_TECHNICAL_BOUND' USING ERRCODE='22023';END IF;
 target:=CASE WHEN step IN('stay','complete') THEN r.current_phase_key ELSE substring(step from position(':' in step)+1) END;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r.snapshot->'phases')x WHERE x->>'phase_key'=target)
 THEN RAISE EXCEPTION 'SCENE56_PHASE_REFERENCE' USING ERRCODE='22023';END IF;
 mid:=gen_random_uuid();body_sha:=encode(extensions.digest(convert_to(p_result->>'text','UTF8'),'sha256'),'hex');
 UPDATE mission_narrative_internal.scene_sources_v1 SET message_permit_id=mid,message_permit_sha256=body_sha,
  message_permit_txid=txid_current(),message_permit_backend=pg_backend_pid(),publication_next_step=step WHERE id=s.id;
 INSERT INTO public.messages(id,location_id,character_id,author_name,body,kind,sender_user,recipient_user,created_at)
 VALUES(mid,m.location_id,NULL,'Fato',p_result->>'text','fato',NULL,NULL,clock_timestamp());
 IF s.request_kind='initial_opening' THEN
  SELECT * INTO STRICT bs FROM mission_generic_owner.board_starts WHERE id=s.board_start_receipt_id AND master_session_id=w.master_session_id FOR UPDATE;
  SELECT * INTO STRICT ev FROM public.mission_run_events WHERE id=bs.event_id AND master_session_id=w.master_session_id FOR UPDATE;
  SELECT * INTO STRICT ob FROM public.mission_run_outbox WHERE event_id=ev.id AND master_session_id=w.master_session_id FOR UPDATE;
  IF NOT bs.simulation OR ev.status<>'committed' OR ob.state<>'pending' OR ev.version_after<>w.run_control_version
   OR ob.event_version_after<>ev.version_after OR ev.step_after<>w.step_key OR ob.step_key<>w.step_key
   OR ob.context_fingerprint<>ev.context_fingerprint THEN RAISE EXCEPTION 'SCENE56_OPENING_SOURCE_CHANGED' USING ERRCODE='PT409';END IF;
  pub:=gen_random_uuid();
  INSERT INTO public.mission_run_publications(id,master_session_id,event_id,request_key_sha256,request_fingerprint,source,
   expected_run_control_version,expected_event_version_after,expected_step_key,context_fingerprint,body_sha256,status)
  VALUES(pub,w.master_session_id,ev.id,mission_internal.request_key_sha256(w.request_key),
   mission_internal.fingerprint(jsonb_build_object('schema_version','mission-narrative-scene-publication/1','work_id',w.id,
    'source_id',s.id,'payload_sha256',w.payload_sha256,'body_sha256',body_sha)),
   'model',w.run_control_version,ev.version_after,w.step_key,ev.context_fingerprint,body_sha,'committed');
  INSERT INTO public.mission_run_messages(publication_id,message_id,body_sha256) VALUES(pub,mid,body_sha);
  PERFORM set_config('app.mission_outbox_publish','on',true);
  UPDATE public.mission_run_outbox SET state='published',publication_id=pub,published_at=clock_timestamp() WHERE event_id=ev.id;
  PERFORM set_config('app.mission_outbox_publish','off',true);
 END IF;
 SELECT coalesce(jsonb_agg(q.x ORDER BY (q.x->>'sequence')::bigint),'[]'::jsonb) INTO history FROM(
  SELECT x FROM jsonb_array_elements(r.last_fati||jsonb_build_array(jsonb_build_object('message_id',mid,
   'sequence',r.state_version+1,'body',p_result->>'text','body_sha256',body_sha)))x
  ORDER BY (x->>'sequence')::bigint DESC LIMIT 4)q;
 UPDATE mission_narrative_internal.scene_runtime_v1 SET current_phase_key=target,scene_memory=memory,
  last_publication_id=mid,last_publication_sha256=body_sha,last_fati=history,updated_at=clock_timestamp()
 WHERE id=r.id;
 IF target IS DISTINCT FROM r.current_phase_key THEN
  UPDATE mission_narrative_internal.scene_runtime_v1 SET
   arena_receipt=arena_by_phase#>ARRAY[target,'receipt'],
   arena_phase_key=CASE WHEN arena_by_phase ? target THEN target ELSE NULL END,
   arena_receipt_sha256=arena_by_phase#>>ARRAY[target,'receipt_sha256'],
   encounter_key=arena_by_phase#>>ARRAY[target,'encounter_key'] WHERE id=r.id;
 END IF;
 UPDATE mission_narrative_internal.scene_sources_v1 SET published_message_id=mid WHERE id=s.id;
 IF s.request_kind='initial_opening' THEN PERFORM mission_generic_owner.opening_published(w.master_session_id,pub);END IF;
 -- Only technical phase/control changes. The live trigger catalogue proves panel_mission_entry
 -- runs only on INSERT/UPDATE master_session_id, never on these phase/control columns.
 IF s.request_kind NOT IN('initial_opening','combat_intent') THEN
  UPDATE public.mission_run_state SET current_step_key=target,control_version=control_version+1,updated_at=clock_timestamp()
   WHERE master_session_id=w.master_session_id AND control_version=run.control_version;
  IF NOT FOUND THEN RAISE EXCEPTION 'SCENE56_PHASE_CAS' USING ERRCODE='PT409';END IF;
 END IF;
 IF s.request_kind='combat_intent' THEN
  UPDATE mission_narrative_internal.scene_runtime_v1 SET state_version=state_version+1,mode='combat',turn_owner='combat' WHERE id=r.id;
 ELSIF left(step,7)='combat:' THEN
  opened:=mission_narrative_internal.scene_open_current_v1(s.id,w.request_key);
 ELSE
  UPDATE mission_narrative_internal.scene_runtime_v1 SET state_version=state_version+1,
   mode=CASE WHEN step='complete' THEN 'closed' ELSE 'narrative' END,
   turn_owner=CASE WHEN step='complete' THEN 'closed' ELSE 'players' END WHERE id=r.id;
  IF step='complete' THEN
   UPDATE public.mission_run_state SET run_phase='conclusa',updated_at=clock_timestamp() WHERE master_session_id=w.master_session_id;
  END IF;
 END IF;
 IF s.request_kind NOT IN('initial_opening','combat_intent') THEN PERFORM mission_generic_owner.role_window_advance_v1(w.master_session_id,mid);END IF;
 RETURN jsonb_build_object('message_id',mid,'replayed',false,'next_step',step,'combat_open',opened);
END $function$;


CREATE OR REPLACE FUNCTION mission_narrative_internal.scene_source_assert_v1(p_work uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE w mission_generic_owner.work_items; s mission_narrative_internal.scene_sources_v1;
 r mission_narrative_internal.scene_runtime_v1; role_body jsonb; src jsonb;
BEGIN
 PERFORM mission_ai_board_owner.service_only();
 SELECT * INTO STRICT w FROM mission_generic_owner.work_items WHERE id=p_work;
 IF NOT EXISTS(SELECT 1 FROM mission_factory_owner.editor_release_readiness root56 WHERE root56.singleton AND root56.state='enabled' AND root56.scope='staff' AND root56.revision_sha256=root56.observed_revision_sha256 AND root56.canonical_preimage::jsonb#>'{config,c1266_narrative_scene}'='{"schema_version":"mission-narrative-scene-policy/1","enabled":true,"scope":"staff"}'::jsonb) THEN RAISE EXCEPTION 'SCENE56_DISABLED' USING ERRCODE='42501';END IF;
 IF w.kind<>'narration' OR w.payload->>'schema_version'<>'mission-narrative-scene/1'
  OR w.payload->>'mode'<>'narrative_scene' THEN RAISE EXCEPTION 'SCENE56_WORK_TYPE' USING ERRCODE='22023';END IF;
 PERFORM mission_generic_owner.work_assert(w);
 SELECT * INTO STRICT s FROM mission_narrative_internal.scene_sources_v1 WHERE work_id=w.id;
 SELECT * INTO STRICT r FROM mission_narrative_internal.scene_runtime_v1 WHERE id=s.scene_id;
 IF NOT r.is_active OR (s.request_kind='combat_intent' AND (r.mode<>'combat' OR r.turn_owner<>'fato') OR s.request_kind<>'combat_intent' AND r.mode<>'narrative') OR r.master_session_id<>w.master_session_id
  OR r.state_version<>s.state_version OR r.current_phase_key<>s.current_phase_key
  OR r.snapshot_sha256<>s.snapshot_sha256 OR public.combat_v2_sha256(r.snapshot)<>r.snapshot_sha256
  OR r.last_publication_id IS DISTINCT FROM s.last_publication_id
  OR r.last_publication_sha256 IS DISTINCT FROM s.last_publication_sha256
  OR public.combat_v2_sha256(coalesce(r.scene_memory,'null'::jsonb))<>s.scene_memory_sha256
  OR s.retired_at IS NOT NULL OR s.published_message_id IS NOT NULL
  OR s.id<>w.authority_receipt_id OR s.payload_sha256<>w.payload_sha256
  OR w.payload_sha256<>public.combat_v2_sha256(w.payload)
  OR w.payload->>'source_window_id'<>s.id::text
  OR w.payload->>'scene_id'<>r.id::text
  OR w.payload->>'source_revision'<>s.source_revision
  OR w.payload->>'state_version'<>s.state_version::text
  OR w.payload->>'snapshot_sha256'<>s.snapshot_sha256
  OR w.payload->'snapshot' IS DISTINCT FROM r.snapshot
 THEN RAISE EXCEPTION 'SCENE56_SOURCE_CHANGED' USING ERRCODE='PT409';END IF;
 IF s.request_kind='combat_intent' AND (s.technical_request IS DISTINCT FROM w.payload->'combat_intent'
  OR s.technical_request IS DISTINCT FROM mission_narrative_internal.scene_combat_intent_source_v1(w.master_session_id,(s.technical_request->>'round_id')::uuid)
  OR cardinality(s.accepted_role_ids)<>0) THEN RAISE EXCEPTION 'NATIVE_INTENT_SOURCE_CHANGED' USING ERRCODE='PT409';END IF;
 SELECT jsonb_agg(jsonb_build_object('message_id',rs.message_id,'user_id',rs.user_id,
  'character_id',rs.character_id,'sequence',rs.submission_order,'body',m.body,'body_sha256',rs.body_sha256)
  ORDER BY rs.submission_order,rs.message_id) INTO role_body
 FROM mission_generic_owner.role_submissions rs JOIN public.messages m ON m.id=rs.message_id
 WHERE rs.master_session_id=w.master_session_id AND rs.message_id=ANY(s.accepted_role_ids)
 AND rs.valid IS TRUE AND rs.invalid_reason IS NULL
 AND EXISTS(SELECT 1 FROM public.master_v2_participants part
  WHERE part.session_id=rs.master_session_id AND part.user_id_snapshot=rs.user_id
   AND part.character_id=rs.character_id AND part.left_at IS NULL AND part.engagement_state='attivo')
 AND EXISTS(SELECT 1 FROM jsonb_array_elements(r.snapshot->'players') captured_player
  WHERE captured_player->>'user_id'=rs.user_id::text AND captured_player->>'character_id'=rs.character_id::text)
 AND m.character_id=rs.character_id AND m.kind='say' AND m.recipient_user IS NULL
 AND m.location_id=(SELECT sess.location_id FROM public.master_v2_sessions sess WHERE sess.id=rs.master_session_id)
 AND encode(extensions.digest(convert_to(m.body,'UTF8'),'sha256'),'hex')=rs.body_sha256;
 role_body:=coalesce(role_body,'[]'::jsonb);
 IF jsonb_array_length(role_body)<>cardinality(s.accepted_role_ids)
  OR role_body IS DISTINCT FROM w.payload->'accepted_roles'
  OR public.combat_v2_sha256(role_body)<>s.accepted_roles_sha256
 THEN RAISE EXCEPTION 'SCENE56_ACCEPTED_ROLE_CHANGED' USING ERRCODE='PT409';END IF;
 src:=jsonb_build_object('schema_version','mission-narrative-scene-source/1','scene_id',r.id,
  'snapshot_sha256',s.snapshot_sha256,'state_version',s.state_version,'source_revision',s.source_revision,
  'accepted_role_ids',to_jsonb(s.accepted_role_ids),'accepted_roles_sha256',s.accepted_roles_sha256,
  'last_publication_id',s.last_publication_id,'last_publication_sha256',s.last_publication_sha256,
  'current_phase_key',s.current_phase_key,'scene_memory_sha256',s.scene_memory_sha256);
 RETURN src;
END $function$;


CREATE OR REPLACE FUNCTION mission_public_owner.work_contract_issue_v1(p_work uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w mission_generic_owner.work_items;b mission_generic_owner.run_bindings;
 a mission_public_owner.session_admissions_v1;q mission_factory_owner.quest_run_sources;
 pub mission_factory_owner.publications;source_scope text;release_sha text;profile text;
 q49 jsonb;source_attestation jsonb;payload_version text;features jsonb:='[]'::jsonb;doc jsonb;old jsonb;ignored jsonb;c5_proof jsonb;c5_native jsonb;c5_stamp jsonb;template_policy jsonb;
begin
 select * into strict w from mission_generic_owner.work_items where id=p_work for update;
 old:=mission_public_owner.work_contract_v1(w.id);
 if old is not null then return old;end if;
 IF w.kind='narration' AND w.payload->>'schema_version'='mission-narrative-scene/1'
  AND w.payload->>'mode'='narrative_scene' THEN
  IF w.state<>'ready' THEN RAISE EXCEPTION 'SCENE56_CONTRACT_WORK_STATE' USING ERRCODE='PT409';END IF;
  ignored:=mission_narrative_internal.scene_source_assert_v1(w.id);
  c5_proof:=mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true);
  q49:=mission_generic_owner.manual_staff_scope_v1(w.master_session_id);
  c5_native:=mission_generic_owner.manual_staff_native_v1(w.master_session_id,false,true);
  IF c5_proof IS NULL OR q49 IS NULL OR c5_native IS NULL
   OR c5_proof->>'execution_context'<>'staff_mission' THEN
   RAISE EXCEPTION 'SCENE56_ADMISSION_CLOSED' USING ERRCODE='42501';END IF;
  release_sha:=c5_proof->>'release_sha256';
  c5_stamp:=jsonb_build_object('schema_version','c1266-work-execution-attestation/3',
   'execution_context',c5_proof->>'execution_context','admission',c5_proof->'admission',
   'release_sha256',release_sha,'binding_sha256',c5_proof->>'binding_sha256',
   'financial_qualification_sha256',c5_proof->>'financial_qualification_sha256',
   'c7_budget_qualification_sha256',c5_proof->>'c7_budget_qualification_sha256',
   'start_receipt_id',c5_native->>'start_receipt_id',
   'start_snapshot_sha256',c5_native#>>'{eligibility,board_snapshot_sha256}',
   'source_scope',q49->'source_scope','source_qualification',q49,
   'source_qualification_sha256',public.combat_v2_sha256(q49));
  source_attestation:=jsonb_build_object('schema_version','mission-narrative-scene-attestation/1',
   'work_id',w.id,'authority_receipt_id',w.authority_receipt_id,'payload_sha256',w.payload_sha256,
   'master_session_id',w.master_session_id,'definition_sha256',w.definition_sha256,
   'release_sha256',release_sha,'execution_authority',c5_stamp,'scene',ignored);
  doc:=jsonb_build_object('schema_version','mission-narrative-admission/3','scope','staff_mission',
   'release_sha256',release_sha,'work_id',w.id,'master_session_id',w.master_session_id,
   'definition_sha256',w.definition_sha256,'payload_sha256',w.payload_sha256,
   'payload_schema_version','mission-narrative-scene/1','editorial_profile','cinematic_master_1',
   'features',jsonb_build_array('execution_authority_v1','provider_output_retention_v1','direct_scene_narration_v1')||CASE WHEN w.payload ? 'combat_intent' THEN '["native_scene_combat_intent_v1"]'::jsonb ELSE '[]'::jsonb END,
   'source_attestation',source_attestation);
  INSERT INTO mission_public_owner.work_contracts_v1(work_id,master_session_id,scope,release_sha256,
   definition_sha256,payload_sha256,contract,contract_sha256)
  VALUES(w.id,w.master_session_id,'staff_mission',release_sha,w.definition_sha256,w.payload_sha256,doc,public.combat_v2_sha256(doc));
  RETURN doc;
 END IF;

  template_policy:=mission_generic_owner.manual_staff_template_policy_v1(w.master_session_id);
 IF mission_generic_owner.c1266_opening_named_v1(w.master_session_id) THEN
  c5_proof:=mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true);
  c5_native:=mission_generic_owner.c1266_native_start_v1(w.master_session_id,false,true);
  IF c5_proof IS NULL OR c5_native IS NULL THEN RAISE EXCEPTION 'C1266_NARRATIVE5_ISSUE_CLOSED' USING ERRCODE='42501';END IF;
  release_sha:=c5_proof->>'release_sha256';source_scope:=CASE WHEN c5_proof#>>'{admission,resource_scope}'='world' THEN 'public_mission' ELSE 'staff_mission' END;
  c5_stamp:=jsonb_build_object('schema_version','c1266-work-execution-attestation/1','execution_context',c5_proof->>'execution_context',
   'admission',c5_proof->'admission','release_sha256',release_sha,'binding_sha256',c5_proof->>'binding_sha256',
   'financial_qualification_sha256',c5_proof->>'financial_qualification_sha256','c7_budget_qualification_sha256',c5_proof->>'c7_budget_qualification_sha256',
   'start_receipt_id',c5_native->>'start_receipt_id','start_snapshot_sha256',c5_native#>>'{eligibility,board_snapshot_sha256}',
   'source_scope',(SELECT canonical_preimage::jsonb#>'{config,c1266_opening,source_scope}' FROM mission_factory_owner.editor_release_readiness WHERE singleton));
 q49:=mission_generic_owner.c1266_staff_source_scope_v1(w.master_session_id);
 IF q49 IS NOT NULL THEN
 c5_stamp:=c5_stamp||jsonb_build_object('schema_version','c1266-work-execution-attestation/2','source_scope',q49->'source_scope','source_qualification',q49,'source_qualification_sha256',public.combat_v2_sha256(q49));
 END IF;
 q49:=mission_generic_owner.manual_staff_scope_v1(w.master_session_id);
 IF q49 IS NOT NULL THEN
  c5_stamp:=c5_stamp||jsonb_build_object('schema_version','c1266-work-execution-attestation/3','source_scope',q49->'source_scope','source_qualification',q49,'source_qualification_sha256',public.combat_v2_sha256(q49));
 END IF;
 ELSIF mission_generic_owner.c1266_role_scope_v1(w.master_session_id,true) THEN
  ignored:=mission_generic_owner.c1266_clean_staff_admission_v1(w.master_session_id,true,true);
  release_sha:=ignored->>'release_sha256';source_scope:='staff_mission';
 ELSIF exists(select 1 from mission_factory_owner.quest_run_sources qs where qs.session_id=w.master_session_id and qs.availability_scope='public' and qs.state in('prepared','opening_pending','uncertain','started')) then
  ignored:=mission_factory_owner.quest_run_source_assert_v1(w.master_session_id);
  select * into strict q from mission_factory_owner.quest_run_sources where session_id=w.master_session_id;
  release_sha:=q.public_release_sha256;source_scope:='public_quest';
 elsif mission_public_owner.role_session_allowed_v1(w.master_session_id) then
  select * into strict a from mission_public_owner.session_admissions_v1 where master_session_id=w.master_session_id;
  release_sha:=a.release_sha256;source_scope:='public_mission';
 elsif exists(select 1 from mission_launch_owner.dual_decisions d
  join mission_launch_owner.dual_scopes s on s.mission_id=d.mission_id and s.activation_id=d.activation_id
  where d.master_session_id=w.master_session_id) then
  ignored:=mission_public_owner.launch_provenance_v1(w.master_session_id);
  if ignored->>'availability_scope' is distinct from 'staff'
  then raise exception 'NARRATIVE_STAFF_LAUNCH_PROVENANCE' using errcode='42501';end if;
  release_sha:=ignored->>'release_sha256';source_scope:='staff_mission';
 elsif exists(select 1 from mission_factory_owner.quest_run_sources qs
  join public.master_v2_sessions ms on ms.id=qs.session_id
  join public.locations l on l.id=ms.location_id
  where qs.session_id=w.master_session_id and l.id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
   and l.is_active and l.is_test and ms.owner_kind='ai_service' and ms.mission_id is null
   and ms.closed_at is null and ms.suspended_at is null
   and qs.state in('prepared','opening_pending','uncertain','started')) then
  -- Same authoritative Factory assertion, not a second Quest engine.
  ignored:=mission_factory_owner.quest_run_source_assert_v1(w.master_session_id);
  select * into strict q from mission_factory_owner.quest_run_sources where session_id=w.master_session_id;
  select p.* into strict pub from mission_public_owner.publications_v2 p
   join mission_factory_owner.quest_arcs arc on arc.publication_request=p.request_key where arc.id=q.arc_id;
  if pub.target<>'staff' or pub.state<>'staff' or pub.quest_arc_id is distinct from q.arc_id
  then raise exception 'NARRATIVE_QUEST_PUBLICATION_SCOPE' using errcode='42501';end if;
  release_sha:=pub.release_revision_sha256;source_scope:='staff_quest';
 else return null;end if;
 if w.state<>'ready' or w.kind not in('director','narration','choice')
 or w.payload_sha256 is distinct from public.combat_v2_sha256(w.payload)
 then raise exception 'NARRATIVE_WORK_CONTRACT_SOURCE' using errcode='40001';end if;
 select * into strict b from mission_generic_owner.run_bindings where master_session_id=w.master_session_id;
 if b.snapshot_sha256 is distinct from w.definition_sha256
 or b.snapshot_sha256 is distinct from mission_internal.fingerprint(b.snapshot)
 then raise exception 'NARRATIVE_WORK_CONTRACT_BINDING' using errcode='40001';end if;
 payload_version:=w.payload->>'schema_version';
 profile:=case when w.kind in('narration','director') then 'cinematic_master_1' else 'legacy' end;
 if w.kind='director' and (payload_version in('mission-director-work/1','mission-director-work/2','mission-director-work/3') OR(payload_version='mission-director-work/4' AND mission_generic_owner.c1266_role_scope_v2(w.master_session_id,true) AND mission_generic_owner.c1266_role_work_attest_v2(w.id) IS NOT NULL)) then
  if not exists(select 1 from mission_generic_owner.unified_source_windows sw
   where sw.id=w.authority_receipt_id and sw.master_session_id=w.master_session_id
    and sw.work_id=w.id and sw.definition_sha256=w.definition_sha256
    and sw.step_key=w.step_key and sw.run_control_version=w.run_control_version)
  then raise exception 'NARRATIVE_DIRECTOR_SOURCE_RECEIPT' using errcode='40001';end if;
  features:=jsonb_build_array('director_progression','speech_intent');
 elsif w.kind='narration' and payload_version in('mission-generic-narration/3','mission-generic-narration/4') then
  if not exists(select 1 from mission_generic_owner.unified_batches ub
   where ub.id=w.authority_receipt_id and ub.master_session_id=w.master_session_id
    and ub.writer_work_id=w.id and ub.payload_sha256=w.payload_sha256
    and ub.state='ready')
  then raise exception 'NARRATIVE_WRITER_BATCH_RECEIPT' using errcode='40001';end if;
  features:=jsonb_build_array(case payload_version when 'mission-generic-narration/3'
    then 'unified_narration_v3' else 'segmented_narration_v4' end);
 elsif w.kind='narration' and payload_version in('mission-generic-narration/1','mission-generic-narration/2') then
  if jsonb_array_length(coalesce(w.payload->'roleless_declarations','[]'::jsonb))>0 then
   raise exception 'NARRATIVE_ROLELESS_REQUIRES_NATIVE_UNIFIED_ROUTE' using errcode='55000';end if;
 elsif w.kind<>'choice' then
  raise exception 'NARRATIVE_WORK_PROFILE_UNSUPPORTED' using errcode='55000';
 end if;
 source_attestation:=mission_public_owner.narrative_source_attest_v1(w.id)||jsonb_build_object('master_session_id',w.master_session_id,'definition_sha256',w.definition_sha256,'release_sha256',release_sha);
 IF source_attestation#>>'{role_intents,schema_version}' IN('mission-role-intent-attestation/2','mission-role-intent-attestation/3','mission-role-intent-attestation/4') THEN
  IF source_attestation#>>'{role_intents,schema_version}'='mission-role-intent-attestation/4' AND(source_scope IS DISTINCT FROM 'staff_mission' OR source_attestation#>>'{role_intents,temporal_contract_sha256}' IS DISTINCT FROM '0603ab23e76750b5babeb41421bc84b551b959945f21267ffd7169140732f1e8' OR source_attestation#>>'{role_intents,peer_confirmation,schema_version}' IS DISTINCT FROM 'mission-peer-confirmation-contract/2') THEN RAISE EXCEPTION 'C1266_PEER_FEATURE_SCOPE' USING ERRCODE='42501';END IF;
  IF source_attestation#>>'{role_intents,schema_version}'='mission-role-intent-attestation/3' AND (source_scope IS DISTINCT FROM 'staff_mission' OR source_attestation#>>'{role_intents,temporal_contract_sha256}' IS DISTINCT FROM '3fdeaa942bcf3ba217a976f7b0896f4594721fa45cde9ff8ed7bddf15391feda' OR source_attestation#>>'{role_intents,peer_confirmation,schema_version}' IS DISTINCT FROM 'mission-peer-confirmation-contract/1') THEN RAISE EXCEPTION 'C1266_PEER_FEATURE_SCOPE' USING ERRCODE='42501';END IF;
  IF NOT mission_generic_owner.c1266_role_scope_v2(w.master_session_id,true) OR (source_scope IS DISTINCT FROM 'staff_mission' AND c5_proof IS NULL) THEN RAISE EXCEPTION 'C1266_TEMPORAL_FEATURE_SCOPE' USING ERRCODE='42501';END IF;
  features:=features||jsonb_build_array('role_intents_v2');
 ELSIF source_attestation->'role_intents' IS NOT NULL THEN
  IF NOT mission_generic_owner.c1266_role_scope_v1(w.master_session_id,true)
   OR (source_scope IS DISTINCT FROM 'staff_mission' AND c5_proof IS NULL)
  THEN RAISE EXCEPTION 'C1266_ROLE_FEATURE_SCOPE' USING ERRCODE='42501';END IF;
  features:=features||jsonb_build_array('role_intents_v1');
 END IF;
 if jsonb_typeof(source_attestation->'peaceful_exit')='object' then features:=features||jsonb_build_array('peaceful_exit_v1');end if;
 if jsonb_array_length(source_attestation->'continuity_sources')>0 then
  features:=features||jsonb_build_array('continuity_sources_v1');
 end if;
 -- peaceful_exit is not inferred from the profile, caller or an arbitrary UUID.
 -- It requires a separate native legal capability; none is minted here.
 IF c5_stamp IS NOT NULL THEN source_attestation:=source_attestation||jsonb_build_object('execution_authority',c5_stamp);features:=features||jsonb_build_array('execution_authority_v1');END IF;
 IF source_scope='staff_mission' AND c5_stamp IS NOT NULL
  AND mission_generic_owner.manual_staff_scope_v1(w.master_session_id) IS NOT NULL
  AND EXISTS(SELECT 1 FROM mission_factory_owner.editor_release_readiness r WHERE r.singleton AND r.state='enabled'
    AND r.revision_sha256=r.observed_revision_sha256
    AND r.canonical_preimage::jsonb#>>'{config,c1266_free_narrative,enabled}'='true'
    AND (r.canonical_preimage::jsonb#>>'{config,c1266_free_narrative,master_session_id}'=w.master_session_id::text OR template_policy IS NOT NULL))
  AND (w.kind='director' OR(w.kind='narration' AND payload_version='mission-generic-narration/4')) THEN
  features:=features||jsonb_build_array('provider_output_retention_v1');
  IF w.kind='narration' THEN features:=features||jsonb_build_array('free_narrative_v1');END IF;
 END IF;
 IF source_scope='staff_mission' AND c5_stamp IS NOT NULL AND mission_generic_owner.native_intent_policy_v1(w.master_session_id) IS NOT NULL
  AND ((w.kind='director' AND payload_version IN('mission-director-work/3','mission-director-work/4'))
   OR(w.kind='narration' AND payload_version='mission-generic-narration/4' AND features?'free_narrative_v1' AND features?'provider_output_retention_v1')) THEN
  features:=features||jsonb_build_array('native_intent_resolution_v1');
 END IF;
 IF source_scope='staff_mission' AND c5_stamp IS NOT NULL AND w.kind='narration' AND payload_version='mission-generic-narration/3'
  AND w.payload->>'composition_kind' IN('combat_defense_resolved','combat_resolved_no_pending','combat_resolved_then_png_offensive','combat_exit')
  AND mission_generic_owner.manual_staff_scope_v1(w.master_session_id) IS NOT NULL
  AND (template_policy IS NOT NULL OR EXISTS(SELECT 1 FROM mission_factory_owner.editor_release_readiness rr WHERE rr.singleton AND rr.state='enabled' AND rr.revision_sha256=rr.observed_revision_sha256
   AND rr.canonical_preimage::jsonb#>>'{config,c1266_combat_snapshot_recovery,enabled}'='true' AND rr.canonical_preimage::jsonb#>>'{config,c1266_combat_snapshot_recovery,master_session_id}'=w.master_session_id::text
   AND rr.canonical_preimage::jsonb#>>'{config,c1266_combat_snapshot_recovery,ordinary_public_enabled}'='false')) THEN
  features:=features||jsonb_build_array('combat_snapshot_origin_budget_v1');
 END IF;
 IF source_scope='staff_mission' AND c5_stamp IS NOT NULL AND w.kind='narration'
  AND payload_version='mission-generic-narration/2' AND w.payload->>'mode'='combat'
  AND c5_stamp->>'schema_version'='c1266-work-execution-attestation/3'
  AND mission_generic_owner.manual_staff_scope_v1(w.master_session_id) IS NOT NULL
  AND mission_generic_owner.role_native_combat_work_class_v4(w.id)='native_combat_narration' THEN
  features:=features||jsonb_build_array('combat_snapshot_origin_budget_v1','native_scene_writer_context_v1');
 END IF;
 -- Independently scoped speech is a frozen future-work capability, never a reinterpretation of old contracts.
 IF source_scope='staff_mission' AND c5_stamp IS NOT NULL AND template_policy IS NOT NULL
  AND source_attestation#>>'{role_intents,schema_version}'='mission-role-intent-attestation/4'
  AND source_attestation#>>'{role_intents,peer_confirmation,schema_version}'='mission-peer-confirmation-contract/2'
  AND EXISTS(SELECT 1 FROM mission_factory_owner.editor_release_readiness sp27_root WHERE sp27_root.singleton AND sp27_root.state='enabled'
   AND sp27_root.revision_sha256=sp27_root.observed_revision_sha256 AND sp27_root.revision_sha256=release_sha
   AND sp27_root.canonical_preimage::jsonb#>>'{config,c1266_npc_speech_context,schema_version}'='c1266-npc-speech-context-policy/1'
   AND sp27_root.canonical_preimage::jsonb#>'{config,c1266_npc_speech_context,enabled}'='true'::jsonb)
  AND ((w.kind='director' AND payload_version='mission-director-work/4')
   OR(w.kind='narration' AND payload_version='mission-generic-narration/4' AND features?'free_narrative_v1'
    AND EXISTS(SELECT 1 FROM mission_public_owner.work_contracts_v1 sp27_parent_contract
     JOIN mission_generic_owner.work_items sp27_parent ON sp27_parent.id=sp27_parent_contract.work_id
     WHERE sp27_parent.id=(source_attestation#>>'{role_intents,decision_work_id}')::uuid
      AND sp27_parent.master_session_id=w.master_session_id AND sp27_parent.kind='director'
      AND sp27_parent_contract.scope='staff_mission' AND sp27_parent_contract.payload_sha256=sp27_parent.payload_sha256
      AND sp27_parent_contract.contract_sha256=public.combat_v2_sha256(sp27_parent_contract.contract)
      AND sp27_parent_contract.contract->'features'?'npc_speech_context_v1'))) THEN
  features:=features||jsonb_build_array('npc_speech_context_v1');
 END IF;
 -- Wire opt-in is frozen ONLY in new contracts; existing contracts return above unchanged.
 IF w.kind='director' AND payload_version='mission-director-work/4' AND source_scope='staff_mission'
  AND c5_stamp IS NOT NULL AND template_policy IS NOT NULL
  AND source_attestation#>>'{role_intents,schema_version}'='mission-role-intent-attestation/4'
  AND EXISTS(SELECT 1 FROM mission_factory_owner.editor_release_readiness np39_root
   WHERE np39_root.singleton AND np39_root.state='enabled'
   AND np39_root.revision_sha256=np39_root.observed_revision_sha256 AND np39_root.revision_sha256=release_sha
   AND np39_root.canonical_preimage::jsonb#>>'{config,c1266_numeric_peer_wire,schema_version}'='c1266-numeric-peer-wire-policy/1'
   AND np39_root.canonical_preimage::jsonb#>'{config,c1266_numeric_peer_wire,enabled}'='true'::jsonb
   AND np39_root.canonical_preimage::jsonb#>>'{config,c1266_numeric_peer_wire,wire_version}'='mission-director-peer-confirmation/3') THEN
  features:=features||jsonb_build_array('numeric_peer3_wire_v1');
 END IF;
 -- A distinct provider-output capability for the one approved paid incomplete successor.
 -- Source financial attestation remains sealed and unchanged; no proof getter is called while issuing this contract.
 IF w.id='4fb5ea83-f90a-4b76-a6f5-722641d9da43'::uuid AND w.master_session_id='4c7b05e0-b5b7-4586-9aa9-2a77ae03deb4'::uuid
 AND w.kind='director' AND payload_version='mission-director-work/4' AND source_scope='staff_mission'
 AND template_policy IS NOT NULL AND source_attestation#>>'{execution_authority,schema_version}'='c1266-work-execution-attestation/3'
 AND EXISTS(SELECT 1 FROM mission_factory_owner.editor_release_readiness rr50
 WHERE rr50.singleton AND rr50.scope='staff' AND rr50.state='enabled'
 AND rr50.revision_sha256=rr50.observed_revision_sha256 AND rr50.revision_sha256=release_sha
 AND rr50.revision_sha256=encode(extensions.digest(convert_to(rr50.canonical_preimage,'UTF8'),'sha256'),'hex')
 AND rr50.canonical_preimage::jsonb#>'{config,c1266_director_incomplete_recovery}'='{"schema_version":"c1266-director-incomplete-recovery/1","enabled":true,"master_session_id":"4c7b05e0-b5b7-4586-9aa9-2a77ae03deb4","old_work_id":"48df8786-3b66-4b44-a1bd-c92473ee5e55","old_payload_sha256":"58d06c515d3ea564a71075b69596d9823e4453688e50b64d7c061ca3f7a648ca","raw_sha256":"f2918095e64fabbd6910ec8566b2e2ccb8193be4ac5d6c0fc3fa8b1477d55c88","successor_work_id":"4fb5ea83-f90a-4b76-a6f5-722641d9da43","max_successors":1,"target_output_tokens":32000}'::jsonb)
 AND EXISTS(SELECT 1 FROM mission_generic_owner.work_items parent50
 JOIN mission_generic_owner.unified_source_windows src50 ON src50.id=parent50.authority_receipt_id AND src50.work_id=parent50.id
 JOIN mission_generic_owner.unified_source_windows child50 ON child50.id=w.authority_receipt_id AND child50.work_id=w.id
 JOIN mission_narrative_internal.dispatch_audit prepared50 ON prepared50.receipt_id=parent50.dispatch_receipt_id AND prepared50.event_code='staff_director_incomplete_prepared_v1'
 JOIN mission_narrative_internal.dispatch_audit issued50 ON issued50.receipt_id=parent50.dispatch_receipt_id AND issued50.event_code='staff_director_incomplete_reissued_v1'
 WHERE parent50.id='48df8786-3b66-4b44-a1bd-c92473ee5e55'::uuid AND parent50.master_session_id=w.master_session_id
 AND parent50.kind='director' AND parent50.state='failed' AND parent50.result->'failure_codes'='["MISSION_PROVIDER_INCOMPLETE"]'::jsonb
 AND parent50.payload_sha256='58d06c515d3ea564a71075b69596d9823e4453688e50b64d7c061ca3f7a648ca'
 AND src50.superseded_at IS NOT NULL AND src50.superseded_reason='staff_failed_director_incomplete_retry' AND src50.consumed_message_id IS NULL
 AND child50.role_ids=src50.role_ids AND child50.context->>'source_revision'=src50.context->>'source_revision'
 AND child50.master_session_id=w.master_session_id AND child50.step_key=src50.step_key AND child50.run_control_version=src50.run_control_version
 AND child50.source_sha256=w.payload_sha256 AND child50.context=w.payload->'context'
 AND prepared50.details->>'old_work_id'=parent50.id::text AND prepared50.details->>'successor_work_id'=w.id::text
 AND issued50.details->>'prepared_sha256'=public.combat_v2_sha256(prepared50.details)
 AND issued50.details->>'successor_work_id'=w.id::text AND issued50.details->>'successor_payload_sha256'=w.payload_sha256)
 THEN features:=features||jsonb_build_array('director_output_32k_v1');END IF;
 doc:=jsonb_build_object('schema_version',case when c5_proof IS NOT NULL OR source_scope='public_quest' then 'mission-narrative-admission/3' else 'mission-narrative-admission/2' end,'scope',source_scope,
  'release_sha256',release_sha,'work_id',w.id,'master_session_id',w.master_session_id,
  'definition_sha256',w.definition_sha256,'payload_sha256',w.payload_sha256,
  'payload_schema_version',payload_version,'editorial_profile',profile,'features',features,'source_attestation',source_attestation);
 insert into mission_public_owner.work_contracts_v1(work_id,master_session_id,scope,release_sha256,
 definition_sha256,payload_sha256,contract,contract_sha256)
 values(w.id,w.master_session_id,source_scope,release_sha,w.definition_sha256,w.payload_sha256,doc,public.combat_v2_sha256(doc));
 return doc;
end $function$;


CREATE OR REPLACE FUNCTION mission_public_owner.work_contract_v1(p_work uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE wc mission_public_owner.work_contracts_v1;w mission_generic_owner.work_items;
 scene56_source mission_narrative_internal.scene_sources_v1;scene56_doc jsonb;scene56_history jsonb;scene56_descriptor jsonb;scene56_ids jsonb;
 a jsonb;descriptor jsonb;path text[];actual jsonb;node jsonb;seen text[]:='{}'::text[];
BEGIN
 SELECT * INTO wc FROM mission_public_owner.work_contracts_v1 WHERE work_id=p_work;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT * INTO STRICT w FROM mission_generic_owner.work_items WHERE id=p_work;
 -- Typed Scene contracts have immutable historical authority, not legacy Director grammar.
 IF w.payload->>'schema_version'='mission-narrative-scene/1'
  OR wc.contract->>'payload_schema_version'='mission-narrative-scene/1'
  OR wc.contract#>>'{source_attestation,schema_version}'='mission-narrative-scene-attestation/1'
  OR wc.contract->'features' ? 'direct_scene_narration_v1' THEN
  scene56_doc:=wc.contract;a:=scene56_doc->'source_attestation';
  IF (wc.master_session_id,wc.definition_sha256,wc.payload_sha256)
    IS DISTINCT FROM (w.master_session_id,w.definition_sha256,w.payload_sha256)
   OR wc.contract_sha256 IS DISTINCT FROM public.combat_v2_sha256(scene56_doc)
   OR w.payload_sha256 IS DISTINCT FROM public.combat_v2_sha256(w.payload)
   OR w.kind IS DISTINCT FROM 'narration' OR w.payload->>'schema_version' IS DISTINCT FROM 'mission-narrative-scene/1'
   OR w.payload->>'mode' IS DISTINCT FROM 'narrative_scene' OR wc.scope IS DISTINCT FROM 'staff_mission'
   OR NOT mission_factory_owner.keys_exact_v2(scene56_doc,ARRAY['schema_version','scope','release_sha256','work_id','master_session_id','definition_sha256','payload_sha256','payload_schema_version','editorial_profile','features','source_attestation'])
   OR scene56_doc->>'schema_version' IS DISTINCT FROM 'mission-narrative-admission/3'
   OR scene56_doc->>'scope' IS DISTINCT FROM 'staff_mission'
   OR scene56_doc->>'editorial_profile' IS DISTINCT FROM 'cinematic_master_1'
   OR scene56_doc->>'payload_schema_version' IS DISTINCT FROM 'mission-narrative-scene/1'
   OR (scene56_doc->>'work_id',scene56_doc->>'master_session_id',scene56_doc->>'definition_sha256',scene56_doc->>'payload_sha256',scene56_doc->>'release_sha256')
    IS DISTINCT FROM (w.id::text,w.master_session_id::text,w.definition_sha256,w.payload_sha256,wc.release_sha256)
   OR coalesce(wc.release_sha256,'')!~'^[a-f0-9]{64}$'
   OR scene56_doc->'features' IS DISTINCT FROM ('["execution_authority_v1","provider_output_retention_v1","direct_scene_narration_v1"]'::jsonb||CASE WHEN w.payload ? 'combat_intent' THEN '["native_scene_combat_intent_v1"]'::jsonb ELSE '[]'::jsonb END)
   OR NOT mission_factory_owner.keys_exact_v2(a,ARRAY['schema_version','work_id','authority_receipt_id','payload_sha256','master_session_id','definition_sha256','release_sha256','execution_authority','scene'])
   OR a->>'schema_version' IS DISTINCT FROM 'mission-narrative-scene-attestation/1'
   OR (a->>'work_id',a->>'master_session_id',a->>'definition_sha256',a->>'payload_sha256',a->>'release_sha256',a->>'authority_receipt_id')
    IS DISTINCT FROM (w.id::text,w.master_session_id::text,w.definition_sha256,w.payload_sha256,wc.release_sha256,w.authority_receipt_id::text)
   OR NOT mission_factory_owner.keys_exact_v2(a->'scene',ARRAY['schema_version','scene_id','snapshot_sha256','state_version','source_revision','accepted_role_ids','accepted_roles_sha256','last_publication_id','last_publication_sha256','current_phase_key','scene_memory_sha256'])
   OR a#>>'{scene,schema_version}' IS DISTINCT FROM 'mission-narrative-scene-source/1'
  THEN RAISE EXCEPTION 'SCENE56_READER_TYPED_CONTRACT_BINDING' USING ERRCODE='PT409';END IF;
  scene56_history:=mission_generic_owner.c1266_historical_work_v1(w.id);
  IF scene56_history IS NULL OR scene56_history->>'schema_version' IS DISTINCT FROM 'c1266-work-execution-attestation/3'
   OR a->'execution_authority' IS DISTINCT FROM scene56_history
  THEN RAISE EXCEPTION 'SCENE56_READER_HISTORICAL_AUTHORITY' USING ERRCODE='PT409';END IF;
  SELECT * INTO scene56_source FROM mission_narrative_internal.scene_sources_v1
   WHERE work_id=w.id AND id=w.authority_receipt_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'SCENE56_READER_SOURCE_MISSING' USING ERRCODE='PT409';END IF;
  scene56_descriptor:=jsonb_build_object('schema_version','mission-narrative-scene-source/1','scene_id',scene56_source.scene_id,
   'snapshot_sha256',scene56_source.snapshot_sha256,'state_version',scene56_source.state_version,'source_revision',scene56_source.source_revision,
   'accepted_role_ids',to_jsonb(scene56_source.accepted_role_ids),'accepted_roles_sha256',scene56_source.accepted_roles_sha256,
   'last_publication_id',scene56_source.last_publication_id,'last_publication_sha256',scene56_source.last_publication_sha256,
   'current_phase_key',scene56_source.current_phase_key,'scene_memory_sha256',scene56_source.scene_memory_sha256);
  IF a->'scene' IS DISTINCT FROM scene56_descriptor
   OR NOT mission_factory_owner.keys_exact_v2(w.payload,ARRAY['schema_version','mode','scene_id','source_window_id','source_revision','state_version','snapshot_sha256','snapshot','current_phase_key','scene_memory','accepted_roles','last_publication','last_fati']||CASE WHEN scene56_source.request_kind='combat_intent' THEN ARRAY['combat_intent'] ELSE '{}'::text[] END)
   OR w.payload->>'scene_id' IS DISTINCT FROM scene56_source.scene_id::text
   OR w.payload->>'source_window_id' IS DISTINCT FROM scene56_source.id::text
   OR w.payload->>'source_revision' IS DISTINCT FROM scene56_source.source_revision
   OR w.payload->'state_version' IS DISTINCT FROM to_jsonb(scene56_source.state_version)
   OR w.payload->>'snapshot_sha256' IS DISTINCT FROM scene56_source.snapshot_sha256
   OR w.payload->>'current_phase_key' IS DISTINCT FROM scene56_source.current_phase_key
   OR scene56_source.payload_sha256 IS DISTINCT FROM w.payload_sha256
   OR jsonb_typeof(w.payload->'snapshot') IS DISTINCT FROM 'object'
   OR public.combat_v2_sha256(w.payload->'snapshot') IS DISTINCT FROM scene56_source.snapshot_sha256
   OR jsonb_typeof(w.payload->'accepted_roles') IS DISTINCT FROM 'array'
   OR jsonb_typeof(w.payload->'last_fati') IS DISTINCT FROM 'array'
   OR (w.payload->'scene_memory' IS DISTINCT FROM 'null'::jsonb AND jsonb_typeof(w.payload->'scene_memory') IS DISTINCT FROM 'object')
   OR public.combat_v2_sha256(coalesce(w.payload->'scene_memory','null'::jsonb)) IS DISTINCT FROM scene56_source.scene_memory_sha256
  THEN RAISE EXCEPTION 'SCENE56_READER_IMMUTABLE_SOURCE_BINDING' USING ERRCODE='PT409';END IF;
  SELECT coalesce(jsonb_agg(role.value->'message_id' ORDER BY role.ordinality),'[]'::jsonb)
   INTO scene56_ids FROM jsonb_array_elements(w.payload->'accepted_roles') WITH ORDINALITY role(value,ordinality);
  IF scene56_ids IS DISTINCT FROM to_jsonb(scene56_source.accepted_role_ids)
   OR public.combat_v2_sha256(w.payload->'accepted_roles') IS DISTINCT FROM scene56_source.accepted_roles_sha256
   OR w.payload->'last_publication' IS DISTINCT FROM (CASE WHEN scene56_source.last_publication_id IS NULL THEN 'null'::jsonb
    ELSE jsonb_build_object('message_id',scene56_source.last_publication_id,'body_sha256',scene56_source.last_publication_sha256) END)
   OR (scene56_source.request_kind='initial_opening' AND (cardinality(scene56_source.accepted_role_ids)<>0 OR scene56_source.last_publication_id IS NOT NULL OR scene56_source.board_start_receipt_id IS NULL))
   OR (scene56_source.request_kind='narration' AND cardinality(scene56_source.accepted_role_ids)<1)
   OR (scene56_source.request_kind='combat_intent' AND (cardinality(scene56_source.accepted_role_ids)<>0 OR w.payload->'combat_intent' IS DISTINCT FROM scene56_source.technical_request))
   OR scene56_source.request_kind NOT IN('initial_opening','narration','combat_intent')
  THEN RAISE EXCEPTION 'SCENE56_READER_FROZEN_ROLES_OR_PUBLICATION' USING ERRCODE='PT409';END IF;
  RETURN scene56_doc;
 END IF;
 IF (wc.master_session_id,wc.definition_sha256,wc.payload_sha256)
  IS DISTINCT FROM (w.master_session_id,w.definition_sha256,w.payload_sha256)
 OR wc.contract_sha256 IS DISTINCT FROM public.combat_v2_sha256(wc.contract)
 OR w.payload_sha256 IS DISTINCT FROM public.combat_v2_sha256(w.payload)
 THEN RAISE EXCEPTION 'NARRATIVE_WORK_CONTRACT_DRIFT' USING ERRCODE='40001'; END IF;
 IF NOT(wc.contract->'features' ? 'execution_authority_v1') AND (wc.scope='public_quest') IS DISTINCT FROM (wc.contract->>'schema_version'='mission-narrative-admission/3') THEN RAISE EXCEPTION 'NARRATIVE_ADMISSION_SCOPE_VERSION' USING ERRCODE='40001';END IF;
 IF wc.contract->>'schema_version' IN('mission-narrative-admission/2','mission-narrative-admission/3') THEN
  a:=wc.contract->'source_attestation';
  IF jsonb_typeof(a) IS DISTINCT FROM 'object'
   OR a->>'schema_version' IS DISTINCT FROM 'mission-narrative-source-attestation/1'
   OR (a->>'work_id',a->>'master_session_id',a->>'definition_sha256',a->>'payload_sha256',a->>'release_sha256',a->>'authority_receipt_id')
    IS DISTINCT FROM (w.id::text,w.master_session_id::text,w.definition_sha256,w.payload_sha256,wc.release_sha256,w.authority_receipt_id::text)
   OR jsonb_typeof(a->'continuity_sources') IS DISTINCT FROM 'array'
   OR jsonb_typeof(a->'director_progression_sources') IS DISTINCT FROM 'array'
  THEN RAISE EXCEPTION 'NARRATIVE_ATTESTATION_BINDING' USING ERRCODE='40001'; END IF;
  FOR descriptor IN SELECT value FROM jsonb_array_elements(a->'continuity_sources') LOOP
   IF jsonb_typeof(descriptor->'path') IS DISTINCT FROM 'array'
   THEN RAISE EXCEPTION 'NARRATIVE_CONTINUITY_PATH_SHAPE'; END IF;
   SELECT coalesce(array_agg(value ORDER BY ordinality),'{}'::text[]) INTO path
    FROM jsonb_array_elements_text(descriptor->'path') WITH ORDINALITY;
   IF w.kind<>'narration' OR NOT (
    (cardinality(path)=0 AND w.payload->>'schema_version' IN ('mission-generic-narration/1','mission-generic-narration/2'))
    OR (w.payload->>'schema_version' IN ('mission-generic-narration/3','mission-generic-narration/4') AND (
      (cardinality(path)=1 AND path[1] IN ('mission_context','source_context'))
      OR (cardinality(path) IN (2,3) AND path[1]='resolved_scenes' AND path[2]~'^[0-9]+$'
        AND (cardinality(path)=2 OR path[3]='native_scene')))))
   OR path::text=ANY(seen)
   THEN RAISE EXCEPTION 'NARRATIVE_CONTINUITY_PATH_FORBIDDEN' USING ERRCODE='42501'; END IF;
   seen:=array_append(seen,path::text);node:=w.payload#>path;
   actual:=mission_public_owner.continuity_node_attest_v1(node,path,descriptor->>'shape');
   IF actual IS NULL OR actual IS DISTINCT FROM descriptor
   THEN RAISE EXCEPTION 'NARRATIVE_CONTINUITY_NODE_DRIFT' USING ERRCODE='40001'; END IF;
  END LOOP;
  IF (jsonb_array_length(a->'continuity_sources')>0) IS DISTINCT FROM (wc.contract->'features' ? 'continuity_sources_v1')
  THEN RAISE EXCEPTION 'NARRATIVE_CONTINUITY_FEATURE_DRIFT'; END IF;
  FOR descriptor IN SELECT value FROM jsonb_array_elements(a->'director_progression_sources') LOOP
   IF w.kind<>'director' OR descriptor->'path' IS DISTINCT FROM '["context","prior_progression"]'::jsonb
    OR descriptor->>'node_sha256' IS DISTINCT FROM public.combat_v2_sha256(w.payload#>'{context,prior_progression}')
   THEN RAISE EXCEPTION 'NARRATIVE_DIRECTOR_PROGRESSION_DRIFT' USING ERRCODE='40001'; END IF;
  END LOOP;
  IF jsonb_array_length(a->'director_progression_sources')>1
  THEN RAISE EXCEPTION 'NARRATIVE_DIRECTOR_PROGRESSION_MULTIPLE'; END IF;
  IF (jsonb_typeof(a->'peaceful_exit')='object') IS DISTINCT FROM (wc.contract->'features' ? 'peaceful_exit_v1')
  THEN RAISE EXCEPTION 'NARRATIVE_PEACEFUL_FEATURE_DRIFT'; END IF;
 END IF;
 IF wc.contract->'features' ? 'execution_authority_v1' THEN
  IF mission_generic_owner.c1266_historical_work_v1(w.id) IS NULL OR wc.scope NOT IN('staff_mission','public_mission') THEN RAISE EXCEPTION 'C1266_NARRATIVE5_HISTORY_BINDING' USING ERRCODE='40001';END IF;
 END IF;
 IF wc.contract->'features' ? 'role_intents_v2' THEN
  IF wc.contract->'features' ? 'role_intents_v1' OR (wc.scope IS DISTINCT FROM 'staff_mission' AND mission_generic_owner.c1266_historical_work_v1(w.id) IS NULL) OR wc.contract#>'{source_attestation,role_intents}' IS DISTINCT FROM mission_generic_owner.c1266_role_work_attest_v2(w.id) THEN RAISE EXCEPTION 'C1266_TEMPORAL_FEATURE_ATTESTATION_DRIFT' USING ERRCODE='40001';END IF;
 ELSIF wc.contract->'features' ? 'role_intents_v1' THEN
  IF (wc.scope IS DISTINCT FROM 'staff_mission' AND NOT(wc.contract->'features' ? 'execution_authority_v1'))
   OR wc.contract#>'{source_attestation,role_intents}' IS DISTINCT FROM mission_generic_owner.c1266_role_work_attest_v1(w.id)
  THEN RAISE EXCEPTION 'C1266_ROLE_FEATURE_ATTESTATION_DRIFT' USING ERRCODE='40001';END IF;
 ELSIF w.payload->>'schema_version' IN('mission-director-work/3','mission-director-work/4') OR w.payload ? 'role_interpretation' THEN
  RAISE EXCEPTION 'C1266_ROLE_FEATURE_REQUIRED' USING ERRCODE='42501';
 END IF;
 RETURN wc.contract;
END $function$;


CREATE OR REPLACE FUNCTION public.mission_generic_staff_republish_failed_v1(p_session uuid, p_work uuid, p_staff uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '30s'
AS $function$
declare
 native_root17 mission_generic_owner.event_outbox_v1;native_cfg17 jsonb;native_req17 jsonb;native_event17 uuid;native_wake17 bigint;
  w mission_generic_owner.work_items;
  b mission_generic_owner.unified_batches;
  source_row mission_generic_owner.unified_source_windows;
  m public.master_v2_sessions;
  run_row public.mission_run_state;
  receipt mission_narrative_internal.dispatch_receipts;
  result_row jsonb;recovery_combat jsonb;
  error_state text;
  error_message text;
  error_constraint text;
  error_table text;
  error_schema text;
  safe_code text;
  message_ref uuid;
  factory_cached boolean:=false; saved_manual jsonb; saved_request jsonb;
  diagnostic_column text;
  diagnostic_context text;
  diagnostic_frames jsonb;
  native_selection_detail text;native_selection_diagnostic jsonb;
  successor mission_generic_owner.work_items;
  successor_id uuid;
  successor_event uuid;
  successor_key uuid; old_director mission_generic_owner.work_items; recovery_progress mission_generic_owner.progress_receipts; recovery_root jsonb;
begin
  perform mission_ai_board_owner.service_only();
  if p_session is null or p_work is null or p_staff is null then
    raise exception 'MCR_INPUT' using errcode='22023';
  end if;
  select * into strict m from public.master_v2_sessions where id=p_session;

 -- Native scene Combat /2 owns a real report, never a Unified batch.
 IF EXISTS(SELECT 1 FROM mission_generic_owner.work_items x WHERE x.id=p_work AND x.master_session_id=p_session
  AND x.kind='narration' AND x.payload->>'schema_version'='mission-generic-narration/2' AND x.payload->>'mode'='combat'
  AND x.result->>'schema_version'='mission-generic-pre-provider-failure/1' AND x.result->>'failure_code'='request_validation_failed') THEN
  PERFORM 1 FROM mission_generic_owner.role_window_cursors WHERE master_session_id=p_session FOR UPDATE;
  PERFORM public.master_v2_lock_scope(p_session);
  SELECT * INTO STRICT w FROM mission_generic_owner.work_items WHERE id=p_work AND master_session_id=p_session FOR UPDATE;
  PERFORM public.combat_v2_lock_round((w.payload#>>'{scene_binding,round_id}')::uuid);
  recovery_combat:=mission_generic_owner.native_combat_writer_reissue_proof_v1(w.id,p_staff);
  IF recovery_combat IS NULL OR recovery_combat->>'owned_by_me' IS DISTINCT FROM 'true' THEN
   RAISE EXCEPTION 'MCR_NATIVE_WRITER_PROOF' USING ERRCODE='42501';END IF;
  IF recovery_combat->>'successor_work_id' IS NOT NULL THEN
   IF recovery_combat->>'published'='true' THEN
    message_ref:=(recovery_combat->>'successor_publication_id')::uuid;
    IF message_ref IS NULL THEN RAISE EXCEPTION 'MCR_NATIVE_WRITER_PUBLICATION_PROOF' USING ERRCODE='40001';END IF;
    RETURN jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1',
     'status','published','message_id',message_ref,'replayed',true);
   END IF;
   RETURN jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1',
    'status','recovered','master_session_id',p_session,
    'work_id',(recovery_combat->>'successor_work_id')::uuid,'replayed',true);
  END IF;
  IF recovery_combat->>'can_reissue' IS DISTINCT FROM 'true' OR EXISTS(SELECT 1 FROM mission_generic_owner.work_items x
   WHERE x.master_session_id=p_session AND x.state IN('ready','claimed','authorized','provider_started','uncertain')) THEN
   RAISE EXCEPTION 'MCR_NATIVE_WRITER_PENDING' USING ERRCODE='40001';END IF;
  PERFORM mission_generic_owner.dispatch_user(p_session,p_staff);
  PERFORM mission_generic_owner.work_assert(w);
  IF mission_generic_owner.role_native_combat_work_class_v4(w.id) IS DISTINCT FROM 'native_combat_narration'
   OR (mission_generic_owner.combat_narrative_source(p_session,w.authority_receipt_id)->'payload') IS DISTINCT FROM w.payload
  THEN RAISE EXCEPTION 'MCR_NATIVE_WRITER_SOURCE_CHANGED' USING ERRCODE='40001';END IF;
  successor_id:=mission_ai_service_owner.uuid5(w.id,'native-combat-writer-reissue/1:work');
  successor_event:=mission_ai_service_owner.uuid5(w.id,'native-combat-writer-reissue/1:event');
  successor_key:=mission_ai_service_owner.uuid5(w.id,'native-combat-writer-reissue/1:request');
  INSERT INTO mission_generic_owner.work_items(id,master_session_id,event_id,request_key,dedupe_key,step_key,
   run_control_version,definition_sha256,encounter_id,authority_receipt_id,kind,revision,payload,payload_sha256)
   VALUES(successor_id,p_session,successor_event,successor_key,'native-combat-writer-reissue:'||w.id::text,
    w.step_key,w.run_control_version,w.definition_sha256,w.encounter_id,w.authority_receipt_id,'narration',w.revision,w.payload,w.payload_sha256)
   RETURNING * INTO successor;
  INSERT INTO mission_narrative_internal.dispatch_audit(receipt_id,event_code,details)
   VALUES(w.dispatch_receipt_id,'native_combat_writer_preprovider_reissued_v1',jsonb_build_object(
    'schema_version','mission-native-combat-writer-reissue/1','master_session_id',p_session,'failed_work_id',w.id,
    'old_receipt_id',w.receipt_id,'old_result_sha256',w.result_sha256,'successor_work_id',successor.id,
    'successor_request_key',successor.request_key,'report_id',w.authority_receipt_id,
    'report_sha256',recovery_combat->>'report_sha256','payload_sha256',w.payload_sha256,
    'actor_user_id',p_staff,'provider_calls',0,'old_failure_preserved',true));
  result_row:=mission_public_owner.work_contract_issue_v1(successor.id);
  IF (result_row->'features'?'combat_snapshot_origin_budget_v1') IS DISTINCT FROM true THEN
   RAISE EXCEPTION 'MCR_NATIVE_WRITER_CONTRACT' USING ERRCODE='40001';END IF;
  SELECT * INTO STRICT native_root17 FROM mission_generic_owner.event_outbox_v1
   WHERE master_session_id=p_session AND event_domain='start' AND event_version=1;
  SELECT rr.canonical_preimage::jsonb#>'{config,c1266_server_events}' INTO native_cfg17
   FROM mission_factory_owner.editor_release_readiness rr WHERE rr.singleton AND rr.state='enabled'
    AND rr.scope='staff' AND rr.revision_sha256=rr.observed_revision_sha256;
  IF native_root17.root_principal IS DISTINCT FROM p_staff OR native_cfg17->>'schema_version' IS DISTINCT FROM 'c1266-server-events/1'
   OR native_cfg17->'enabled' IS DISTINCT FROM 'true'::jsonb THEN
   RAISE EXCEPTION 'MCR_NATIVE_WRITER_WAKE_SCOPE' USING ERRCODE='42501';END IF;
  native_req17:=jsonb_build_object('schema_version','mission-generic-request/1','master_session_id',p_session,
   'event_id',successor.event_id,'request_key',successor.request_key,'expected_revision',successor.revision);
  native_event17:=mission_ai_service_owner.uuid5(successor.id,'server-event:writer-ready');
  INSERT INTO mission_generic_owner.event_outbox_v1(event_key,event_version,master_session_id,event_domain,source_id,
   source_sha256,root_event_key,root_request_key,root_principal,root_receipt_sha256,work_id,canonical_request)
   VALUES(native_event17,1,p_session,'writer_ready',successor.id,successor.payload_sha256,
    native_root17.root_event_key,native_root17.root_request_key,native_root17.root_principal,
    native_root17.root_receipt_sha256,successor.id,native_req17);
  native_wake17:=net.http_post(native_cfg17->>'endpoint',jsonb_build_object('schema_version','mission-event-wake/2',
   'event_key',native_event17,'event_version',1),'{}'::jsonb,
   jsonb_build_object('Content-Type','application/json','x-tus-server-event','event42'),5000);
  UPDATE mission_generic_owner.event_outbox_v1 SET wake_request_id=native_wake17 WHERE event_key=native_event17 AND event_version=1;
  IF mission_generic_owner.native_combat_writer_reissue_proof_v1(w.id,p_staff) IS NULL THEN
   RAISE EXCEPTION 'MCR_NATIVE_WRITER_ATTESTATION' USING ERRCODE='40001';END IF;
  RETURN jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1','status','recovered',
   'master_session_id',p_session,'work_id',successor.id,'replayed',false);
 END IF;

 -- Saved-success native narration/3: publication only, no provider operation.
 IF EXISTS(SELECT 1 FROM mission_generic_owner.work_items x
   WHERE x.id=p_work AND x.master_session_id=p_session AND x.kind='narration'
    AND x.payload->>'schema_version'='mission-generic-narration/3'
    AND x.payload->>'mode'='unified' AND x.state IN('failed','completed')
    AND x.result->>'ok'='true' AND x.result->>'provider_calls'='1'
    AND x.result->>'outcome_uncertain'='false') THEN
  saved_manual:=mission_generic_owner.manual_staff_scope_v1(p_session);
  IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_staff AND role IN('admin','master'))
   OR saved_manual IS NULL OR m.owner_kind IS DISTINCT FROM 'ai_service' OR m.master_user IS NOT NULL
   OR m.location_id IS DISTINCT FROM '0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
   OR NOT EXISTS(SELECT 1 FROM public.locations loc WHERE loc.id=m.location_id AND loc.is_test AND loc.is_active)
   THEN RAISE EXCEPTION 'MCR_NATIVE_SAVED_SCOPE' USING ERRCODE='42501';END IF;
  PERFORM 1 FROM mission_generic_owner.role_window_cursors WHERE master_session_id=p_session FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MCR_CURSOR_MISSING' USING ERRCODE='55000';END IF;
  PERFORM public.master_v2_lock_scope(p_session);
  SELECT * INTO STRICT w FROM mission_generic_owner.work_items WHERE id=p_work AND master_session_id=p_session FOR UPDATE;
  SELECT * INTO STRICT b FROM mission_generic_owner.unified_batches WHERE id=w.authority_receipt_id
    AND master_session_id=p_session AND writer_work_id=w.id FOR UPDATE;
  SELECT * INTO STRICT receipt FROM mission_narrative_internal.dispatch_receipts WHERE id=w.dispatch_receipt_id FOR SHARE;
  saved_request:=jsonb_build_object('schema_version','mission-generic-request/1',
    'master_session_id',w.master_session_id,'event_id',w.event_id,'request_key',w.request_key,'expected_revision',w.revision);
  IF mission_generic_owner.c1266_historical_work_manual_v1(w.id,saved_manual)->>'execution_context' IS DISTINCT FROM 'staff_mission'
   OR w.result_sha256 !~ '^[a-f0-9]{64}$' OR w.result->>'raw_sha256' !~ '^[a-f0-9]{64}$'
   OR w.payload_sha256 IS DISTINCT FROM public.combat_v2_sha256(w.payload)
   OR w.result->>'work_id' IS DISTINCT FROM w.id::text
   OR w.result->>'master_session_id' IS DISTINCT FROM p_session::text
   OR w.result->>'request_key' IS DISTINCT FROM w.request_key::text
   OR w.result->>'payload_sha256' IS DISTINCT FROM w.payload_sha256
   OR w.result->>'authorization_id' IS DISTINCT FROM w.authorization_id::text
   OR w.result->>'dispatch_id' IS DISTINCT FROM w.dispatch_id::text
   OR receipt.master_session_id IS DISTINCT FROM p_session OR receipt.authority_receipt_id IS DISTINCT FROM w.id
   OR receipt.request_key IS DISTINCT FROM w.request_key OR receipt.status IS DISTINCT FROM 'success'
   OR receipt.dispatch_count IS DISTINCT FROM 1 OR receipt.finalized_at IS NULL
   OR receipt.event_kind IS DISTINCT FROM 'mission_generic_event' OR receipt.renderer_version IS DISTINCT FROM 'mission-generic-runtime/1'
   OR receipt.request_fingerprint IS DISTINCT FROM mission_internal.fingerprint(saved_request)
   OR receipt.envelope_sha256 IS DISTINCT FROM public.combat_v2_sha256(receipt.envelope)
   OR receipt.authority_sha256 IS DISTINCT FROM receipt.envelope_sha256
   OR receipt.envelope->>'work_id' IS DISTINCT FROM w.id::text
   OR receipt.envelope->>'master_session_id' IS DISTINCT FROM p_session::text
   OR receipt.envelope->>'event_id' IS DISTINCT FROM w.event_id::text
   OR receipt.envelope->>'authority_receipt_id' IS DISTINCT FROM w.authority_receipt_id::text
   OR receipt.envelope->>'payload_sha256' IS DISTINCT FROM w.payload_sha256
   OR receipt.envelope->>'definition_sha256' IS DISTINCT FROM w.definition_sha256
   OR receipt.envelope->'revision' IS DISTINCT FROM to_jsonb(w.revision)
   OR (SELECT count(*) FROM mission_narrative_internal.dispatch_audit own_a
       WHERE own_a.receipt_id=receipt.id AND own_a.event_code='c1266_async_owner_v1')<>1
   OR NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_audit own_a
     WHERE own_a.receipt_id=receipt.id AND own_a.event_code='c1266_async_owner_v1'
       AND mission_factory_owner.keys_exact_v2(own_a.details,ARRAY['schema_version','actor_user_id','work_id','request_sha256','envelope_sha256','provider_timeout_ms'])
       AND own_a.details->>'schema_version'='mission-generic-async-owner/1'
       AND own_a.details->>'actor_user_id'=p_staff::text AND own_a.details->>'work_id'=w.id::text
       AND own_a.details->>'request_sha256'=public.combat_v2_sha256(saved_request)
       AND own_a.details->>'envelope_sha256'=receipt.envelope_sha256 AND own_a.details->'provider_timeout_ms'='240000'::jsonb)
   OR NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_audit ga
     WHERE ga.receipt_id=receipt.id AND ga.event_code='generic_finalized'
       AND ga.details->>'work_id'=w.id::text AND ga.details->>'receipt_id'=w.receipt_id::text
       AND ga.details->>'result_sha256'=w.result_sha256 AND ga.details->>'result_jsonb_sha256'=public.combat_v2_sha256(w.result)
       AND ga.details->>'state'='failed' AND ga.details->>'stale'='false'
       AND ga.details->>'outcome_uncertain'='false' AND ga.details->>'application_error_sqlstate' IS NOT NULL)
   OR NOT EXISTS(SELECT 1 FROM mission_narrative_internal.provider_authorizations pa
       JOIN mission_narrative_internal.dispatch_attempts da ON da.id=pa.attempt_id AND da.receipt_id=pa.receipt_id
       WHERE pa.id=w.authorization_id AND pa.receipt_id=receipt.id AND da.status='success'
         AND da.finalized_at IS NOT NULL AND da.cost_basis='exact' AND da.actual_cost_usd=receipt.charged_cost_usd)
   OR NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_audit count_a
     WHERE count_a.receipt_id=receipt.id AND count_a.event_code='c8_count_success'
       AND count_a.details->>'work_id'=w.id::text AND count_a.details->>'state'='success'
       AND count_a.details->>'generation_allowed'='true')
   OR (SELECT count(*) FROM staff_ai_quota_private.calls q WHERE q.producer='mission_generic_ai' AND q.source_id=receipt.id)<>2
   OR EXISTS(SELECT 1 FROM staff_ai_quota_private.calls q WHERE q.producer='mission_generic_ai' AND q.source_id=receipt.id
       AND (q.scope_id IS DISTINCT FROM p_session OR q.call_no NOT IN(1,2) OR q.state NOT IN('settled','unknown_billable')
         OR (q.state='settled' AND (q.charged_usd IS NULL OR q.charged_usd<0))
         OR (q.state='unknown_billable' AND (q.reserved_usd IS NULL OR q.reserved_usd<receipt.upper_bound_cost_usd))))
   OR NOT EXISTS(SELECT 1 FROM staff_ai_quota_private.calls q WHERE q.producer='mission_generic_ai' AND q.source_id=receipt.id
       AND q.scope_id=p_session AND q.state='settled' AND q.charged_usd=receipt.charged_cost_usd)
   OR b.retired_at IS NOT NULL OR b.source_window_id IS NOT NULL OR b.decision_work_id IS NOT NULL OR b.decision IS NOT NULL
   OR b.encounter_id IS DISTINCT FROM w.encounter_id OR b.step_key IS DISTINCT FROM w.step_key
   OR b.run_control_version IS DISTINCT FROM w.run_control_version OR b.payload IS DISTINCT FROM w.payload
   OR b.payload_sha256 IS DISTINCT FROM w.payload_sha256 OR w.payload->>'batch_id' IS DISTINCT FROM b.id::text
   OR w.payload->>'composition_kind' IS DISTINCT FROM b.composition_kind OR w.payload->'source_windows' IS DISTINCT FROM '[]'::jsonb
   OR w.payload#>>'{publication_barrier,closed}' IS DISTINCT FROM 'true'
   OR w.payload#>'{publication_barrier,receipt_ids}' IS DISTINCT FROM w.payload#>'{publication_barrier,required_receipt_ids}'
   OR (w.payload#>'{publication_barrier,receipt_ids}' @> jsonb_build_array(b.id,b.source_report_id)) IS DISTINCT FROM TRUE
   OR NOT EXISTS(SELECT 1 FROM public.combat_v2_round_reports rr JOIN public.combat_v2_rounds rnd ON rnd.id=rr.round_id
     JOIN mission_generic_owner.encounters enc ON enc.encounter_id=rnd.session_id AND enc.master_session_id=p_session
     WHERE rr.id=b.source_report_id AND rnd.id=b.source_round_id AND rnd.session_id=b.encounter_id
       AND rr.values_written IS FALSE AND rr.mechanics_sha256=public.combat_v2_sha256(rr.mechanics)
       AND EXISTS(SELECT 1 FROM jsonb_array_elements(w.payload->'resolved_scenes') rs
         WHERE rs#>>'{scene_binding,round_id}'=rnd.id::text AND rs#>>'{scene_binding,session_id}'=b.encounter_id::text
           AND rs#>>'{scene_binding,report_sha256}'=rr.mechanics_sha256
           AND rs#>'{barrier,required_receipt_ids}' @> jsonb_build_array(rr.id)))
   OR (b.secondary_report_id IS NOT NULL AND NOT EXISTS(
     SELECT 1 FROM public.combat_v2_round_reports rr JOIN public.combat_v2_rounds rnd ON rnd.id=rr.round_id
     WHERE rr.id=b.secondary_report_id AND rnd.session_id=b.encounter_id AND rr.values_written IS FALSE
       AND rr.mechanics_sha256=public.combat_v2_sha256(rr.mechanics)
       AND w.payload#>'{publication_barrier,receipt_ids}' @> jsonb_build_array(rr.id)
       AND EXISTS(SELECT 1 FROM jsonb_array_elements(w.payload->'resolved_scenes') rs
         WHERE rs#>>'{scene_binding,round_id}'=rnd.id::text AND rs#>>'{scene_binding,report_sha256}'=rr.mechanics_sha256)))
   THEN RAISE EXCEPTION 'MCR_NATIVE_SAVED_PROOF' USING ERRCODE='42501';END IF;
  -- Replay requires real publication, never terminal work state alone.
  IF w.state='completed' AND w.message_id IS NOT NULL AND b.state='published'
    AND b.message_id=w.message_id AND b.published_at IS NOT NULL
    AND EXISTS(SELECT 1 FROM public.messages mm WHERE mm.id=w.message_id AND mm.body=w.result->>'text'
      AND mm.kind='fato' AND mm.recipient_user IS NULL AND mm.location_id=m.location_id)
    AND EXISTS(SELECT 1 FROM mission_generic_owner.unified_report_publications up
      JOIN public.combat_v2_round_reports rr ON rr.id=up.report_id AND rr.message_id=up.message_id
      JOIN public.combat_v2_rounds rnd ON rnd.id=rr.round_id AND rnd.state='narrato'
      WHERE up.batch_id=b.id AND up.report_id=b.source_report_id AND up.primary_report
       AND up.message_id=w.message_id AND rr.narration_state='pubblicata')
    AND (b.secondary_report_id IS NULL OR EXISTS(SELECT 1 FROM mission_generic_owner.unified_report_publications up
      JOIN public.combat_v2_round_reports rr ON rr.id=up.report_id AND rr.narration_state='pubblicata' AND rr.message_id IS NULL
      JOIN public.combat_v2_rounds rnd ON rnd.id=rr.round_id AND rnd.state='narrato'
      WHERE up.batch_id=b.id AND up.report_id=b.secondary_report_id AND NOT up.primary_report AND up.message_id=w.message_id)) THEN
   RETURN jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1',
      'status','published','message_id',w.message_id,'replayed',true);
  END IF;
  PERFORM mission_generic_owner.dispatch_user(p_session,p_staff);
  IF w.state IS DISTINCT FROM 'failed' OR w.message_id IS NOT NULL OR w.finalized_at IS NULL
    OR b.state IS DISTINCT FROM 'ready' OR b.message_id IS NOT NULL OR b.retired_at IS NOT NULL
    OR b.source_window_id IS NOT NULL OR b.decision_work_id IS NOT NULL
    OR b.source_round_id IS NULL OR b.source_report_id IS NULL
    OR w.payload IS DISTINCT FROM b.payload OR w.payload_sha256 IS DISTINCT FROM b.payload_sha256
    OR w.payload_sha256 IS DISTINCT FROM public.combat_v2_sha256(w.payload)
    OR w.result->>'text' IS DISTINCT FROM btrim(w.result->>'text')
    OR length(coalesce(w.result->>'text','')) NOT BETWEEN 1 AND 5000
    OR receipt.status IS DISTINCT FROM 'success' OR receipt.dispatch_count IS DISTINCT FROM 1
    OR receipt.authority_receipt_id IS DISTINCT FROM w.id OR receipt.master_session_id IS DISTINCT FROM p_session
    OR receipt.request_key IS DISTINCT FROM w.request_key OR receipt.finalized_at IS NULL
    OR EXISTS(SELECT 1 FROM mission_generic_owner.work_items other WHERE other.master_session_id=p_session
      AND other.id<>w.id AND other.state IN('ready','claimed','authorized','provider_started','uncertain'))
   THEN RAISE EXCEPTION 'MCR_NATIVE_SAVED_BINDING' USING ERRCODE='P0001';END IF;
  PERFORM mission_generic_owner.work_assert(w);
  BEGIN
   -- No authorization, Count, Generation or provider dispatch is issued by this branch.
   UPDATE mission_generic_owner.work_items SET state='provider_started',finalized_at=NULL,
      lease_expires_at=greatest(lease_expires_at,clock_timestamp()+interval '60 seconds')
    WHERE id=w.id AND state='failed';
   IF NOT FOUND THEN RAISE EXCEPTION 'MCR_NATIVE_SAVED_CAS' USING ERRCODE='P0001';END IF;
   result_row:=mission_generic_owner.unified_publish(w.id,w.result->>'text',w.request_key);
   message_ref:=(result_row->>'message_id')::uuid;
   IF message_ref IS NULL OR NOT EXISTS(SELECT 1 FROM mission_generic_owner.unified_batches ub
      JOIN public.messages mm ON mm.id=ub.message_id WHERE ub.id=b.id AND ub.state='published'
      AND ub.writer_work_id=w.id AND ub.message_id=message_ref AND mm.body=w.result->>'text')
     THEN RAISE EXCEPTION 'MCR_NATIVE_SAVED_PUBLICATION' USING ERRCODE='P0001';END IF;
   UPDATE mission_generic_owner.work_items SET state='completed',message_id=message_ref,
      finalized_at=clock_timestamp(),lease_expires_at=w.lease_expires_at
    WHERE id=w.id AND state='provider_started' AND result IS NOT DISTINCT FROM w.result
      AND result_sha256 IS NOT DISTINCT FROM w.result_sha256;
   IF NOT FOUND THEN RAISE EXCEPTION 'MCR_NATIVE_SAVED_RESULT_CHANGED' USING ERRCODE='P0001';END IF;
  EXCEPTION WHEN OTHERS THEN
   GET STACKED DIAGNOSTICS error_state=returned_sqlstate,error_message=message_text,
      diagnostic_context=pg_exception_context;
   safe_code:=CASE WHEN error_message ~ '^[A-Z][A-Z0-9_]{1,79}$' THEN error_message ELSE NULL END;
   IF safe_code IS NULL AND octet_length(error_message)<=8192 THEN
    BEGIN
     native_selection_diagnostic:=error_message::jsonb;
     safe_code:=coalesce(native_selection_diagnostic->>'code',native_selection_diagnostic->>'error_code');
     IF safe_code !~ '^[A-Z][A-Z0-9_]{1,79}$' THEN safe_code:=NULL;END IF;
    EXCEPTION WHEN invalid_text_representation THEN safe_code:=NULL;END;
   END IF;
   safe_code:=coalesce(safe_code,'SQLSTATE_'||error_state);
   SELECT coalesce(jsonb_agg(jsonb_build_object('function',parts[1],'line',parts[2]::integer)
      ORDER BY ordinal),'[]'::jsonb) INTO diagnostic_frames FROM
      (SELECT parts,ordinal FROM regexp_matches(diagnostic_context,
       'PL/pgSQL function ([A-Za-z_][A-Za-z0-9_.]*)\([^)]*\) line ([0-9]{1,6})','g')
       WITH ORDINALITY f(parts,ordinal) LIMIT 8) frames;
  END;
  IF safe_code IS NOT NULL THEN
   INSERT INTO mission_narrative_internal.dispatch_audit(receipt_id,event_code,details)
    VALUES(receipt.id,'staff_cached_publication_rejected',jsonb_build_object(
      'schema_version','mission-native-saved-publication-diagnostic/1','work_id',w.id,
      'master_session_id',p_session,'sqlstate',error_state,'error_code',safe_code,
      'frames',diagnostic_frames,'generation_http_calls',0));
   RETURN jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1',
     'status','failed','error_code',safe_code);
  END IF;
  INSERT INTO mission_narrative_internal.dispatch_audit(receipt_id,event_code,details)
   VALUES(receipt.id,'staff_cached_publication_completed',jsonb_build_object(
     'schema_version','mission-native-saved-publication/1','work_id',w.id,'master_session_id',p_session,
     'message_id',message_ref,'saved_result_sha256',w.result_sha256,'generation_http_calls',0));
  RETURN jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1',
    'status','published','message_id',message_ref,'replayed',false);
 END IF;

 -- A failed Combat Writer before any Count/Generation is immutable. Reissue its same sealed report in a distinct work.
 IF EXISTS(SELECT 1 FROM mission_generic_owner.work_items x WHERE x.id=p_work AND x.master_session_id=p_session AND x.kind='narration' AND x.payload->>'schema_version'='mission-generic-narration/3' AND x.result->>'schema_version'='mission-generic-pre-provider-failure/1' AND x.result->>'failure_code'='request_validation_failed') THEN
  recovery_combat:=mission_generic_owner.combat_narration_reissue_proof_v1(p_work,p_staff);
  IF recovery_combat IS NULL OR recovery_combat->>'owned_by_me' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'MCR_COMBAT_REISSUE_PROOF' USING ERRCODE='42501';END IF;
  PERFORM 1 FROM mission_generic_owner.role_window_cursors WHERE master_session_id=p_session FOR UPDATE;
  PERFORM public.master_v2_lock_scope(p_session);
  SELECT * INTO STRICT w FROM mission_generic_owner.work_items WHERE id=p_work AND master_session_id=p_session FOR UPDATE;
  SELECT * INTO STRICT b FROM mission_generic_owner.unified_batches WHERE id=w.authority_receipt_id AND master_session_id=p_session FOR UPDATE;
  PERFORM 1 FROM public.combat_v2_rounds WHERE id=b.source_round_id FOR UPDATE;
  PERFORM 1 FROM public.combat_v2_round_reports WHERE id=b.source_report_id FOR UPDATE;
  recovery_combat:=mission_generic_owner.combat_narration_reissue_proof_v1(p_work,p_staff);
  IF recovery_combat IS NULL OR recovery_combat->>'owned_by_me' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'MCR_COMBAT_REISSUE_CHANGED' USING ERRCODE='40001';END IF;
  IF recovery_combat->>'published'='true' THEN RETURN jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1','status','published','message_id',b.message_id,'replayed',true);END IF;
  IF recovery_combat->>'successor_work_id' IS NOT NULL THEN RETURN jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1','status','recovered','master_session_id',p_session,'work_id',(recovery_combat->>'successor_work_id')::uuid,'replayed',true);END IF;
  IF recovery_combat->>'can_reissue' IS DISTINCT FROM 'true' OR EXISTS(SELECT 1 FROM mission_generic_owner.work_items nw WHERE nw.master_session_id=p_session AND nw.state IN('ready','claimed','authorized','provider_started','uncertain')) THEN RAISE EXCEPTION 'MCR_COMBAT_REISSUE_PENDING' USING ERRCODE='40001';END IF;
  PERFORM mission_generic_owner.dispatch_user(p_session,p_staff);
  PERFORM mission_generic_owner.work_assert(w);
  successor_id:=mission_ai_service_owner.uuid5(w.id,'mission-combat-narration-reissue/1:work');
  successor_event:=mission_ai_service_owner.uuid5(w.id,'mission-combat-narration-reissue/1:event');
  successor_key:=mission_ai_service_owner.uuid5(w.id,'mission-combat-narration-reissue/1:request');
  INSERT INTO mission_generic_owner.work_items(id,master_session_id,event_id,request_key,dedupe_key,step_key,run_control_version,definition_sha256,encounter_id,authority_receipt_id,kind,revision,payload,payload_sha256)
   VALUES(successor_id,p_session,successor_event,successor_key,'combat-narration-reissue:'||w.id::text,w.step_key,w.run_control_version,w.definition_sha256,w.encounter_id,b.id,'narration',w.revision,w.payload,w.payload_sha256) RETURNING * INTO successor;
  UPDATE mission_generic_owner.unified_batches SET writer_work_id=successor.id WHERE id=b.id AND writer_work_id=w.id AND state='ready' AND message_id IS NULL AND retired_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'MCR_COMBAT_REISSUE_CAS' USING ERRCODE='40001';END IF;
  INSERT INTO mission_narrative_internal.dispatch_audit(receipt_id,event_code,details) VALUES(w.dispatch_receipt_id,'staff_combat_narration_preprovider_reissued',jsonb_build_object('schema_version','mission-combat-narration-reissue/1','master_session_id',p_session,'failed_work_id',w.id,'old_receipt_id',w.receipt_id,'old_result_sha256',w.result_sha256,'successor_work_id',successor.id,'successor_request_key',successor.request_key,'batch_id',b.id,'report_id',b.source_report_id,'report_sha256',recovery_combat->>'report_sha256','payload_sha256',w.payload_sha256,'actor_user_id',p_staff,'provider_calls',0,'old_failure_preserved',true));
  result_row:=mission_public_owner.work_contract_issue_v1(successor.id);
  IF (result_row->'features'?'combat_snapshot_origin_budget_v1') IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'MCR_COMBAT_REISSUE_CONTRACT' USING ERRCODE='40001';END IF;
  IF mission_generic_owner.combat_narration_reissue_proof_v1(w.id,p_staff) IS NULL THEN RAISE EXCEPTION 'MCR_COMBAT_REISSUE_ATTESTATION';END IF;
  RETURN jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1','status','recovered','master_session_id',p_session,'work_id',successor.id,'replayed',false);
 END IF;



 IF p_session='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid AND p_work='310493d3-92d2-4645-ba85-ab42f57dbf9d'::uuid THEN
  PERFORM mission_generic_owner.dispatch_user(p_session,p_staff);
  IF p_staff<>'b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b'::uuid OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_staff AND role IN('admin','master'))
   OR m.location_id<>'0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid OR m.owner_kind<>'ai_service' OR m.closed_at IS NOT NULL OR m.suspended_at IS NOT NULL
   OR mission_generic_owner.manual_staff_scope_v1(p_session) IS NULL THEN RAISE EXCEPTION 'FREE_RECOVERY_SCOPE' USING ERRCODE='42501';END IF;
  PERFORM 1 FROM mission_generic_owner.role_window_cursors WHERE master_session_id=p_session FOR UPDATE;
  PERFORM public.master_v2_lock_scope(p_session);
  successor_key:=mission_ai_service_owner.uuid5('310493d3-92d2-4645-ba85-ab42f57dbf9d'::uuid,'mission-staff-unpublished-reinterpretation/1:ac9aedbd59dcb835d717f4ddb6ce195e3c2a9d640df576667290fa38b7e6cbbb');
  SELECT * INTO recovery_progress FROM mission_generic_owner.progress_receipts WHERE request_key=successor_key;
  IF FOUND THEN
   IF recovery_progress.master_session_id<>p_session OR recovery_progress.actor_user_id<>p_staff OR recovery_progress.result_sha256<>public.combat_v2_sha256(recovery_progress.result)
    OR NOT mission_generic_owner.role_source_released_v4('433ace05-5265-4aad-96a3-5567b6e3480a'::uuid) THEN RAISE EXCEPTION 'FREE_RECOVERY_REPLAY_CONFLICT';END IF;
   SELECT * INTO STRICT successor FROM mission_generic_owner.work_items WHERE id=(recovery_progress.result#>>'{dispatch,event_id}')::uuid AND master_session_id=p_session;
   RETURN jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1','status','recovered','master_session_id',p_session,'work_id',successor.id,'replayed',true);
  END IF;
  SELECT * INTO STRICT w FROM mission_generic_owner.work_items WHERE id=p_work AND master_session_id=p_session FOR UPDATE;
  SELECT * INTO STRICT old_director FROM mission_generic_owner.work_items WHERE id='433ace05-5265-4aad-96a3-5567b6e3480a'::uuid AND master_session_id=p_session FOR UPDATE;
  SELECT * INTO STRICT b FROM mission_generic_owner.unified_batches WHERE id='0adc85b5-7a66-4d13-a919-4233b1d41857'::uuid AND writer_work_id=w.id AND decision_work_id=old_director.id AND source_window_id=old_director.id FOR UPDATE;
  SELECT * INTO STRICT source_row FROM mission_generic_owner.unified_source_windows WHERE id=old_director.id AND work_id=old_director.id AND master_session_id=p_session FOR UPDATE;
  SELECT canonical_preimage::jsonb INTO STRICT recovery_root FROM mission_factory_owner.editor_release_readiness WHERE singleton AND state='enabled' AND revision_sha256=observed_revision_sha256;
  IF recovery_root#>>'{config,c1266_free_narrative,enabled}' IS DISTINCT FROM 'true' OR recovery_root#>>'{config,c1266_free_narrative,master_session_id}' IS DISTINCT FROM p_session::text
    OR recovery_root#>>'{config,c1266_free_narrative,recovery_writer_id}' IS DISTINCT FROM w.id::text THEN RAISE EXCEPTION 'FREE_RECOVERY_RELEASE';END IF;
  IF w.kind<>'narration' OR w.state<>'failed' OR (w.result->'failure_codes' ? 'MISSION_SEGMENTED_SLOT_COVERAGE_INVALID') IS NOT TRUE
   OR w.result_sha256<>'3a86177027166f250966eeeceb844e1de5efe3efc6caaab42b6832f72428c275'
   OR public.combat_v2_sha256(w.result)<>'01866a3b46c797b430dd4a1d4430176899b0c37dc80e23515d621d2a59f38508'
   OR public.combat_v2_sha256(old_director.result)<>'e68c2eb57650d7a33fa1069565b686fe3db33e8b1309ffc98dfd60fa6fdcb766'
   OR w.payload_sha256<>'5fe7195653506a31f5d263d2a14af8793c1fdbcf5bf54a2d305d9724937d8523'
   OR old_director.kind<>'director' OR old_director.state<>'completed' OR old_director.result_sha256<>'b8f03c42eb2f531897b04e0b21905784843e20c039fd6a3a3627f3202cb08ace'
   OR old_director.payload_sha256<>'e1c8499e6907024d340cfadb28f880895061c5f5ffbca8f9372945f510c9ef4e'
   OR w.message_id IS NOT NULL OR old_director.message_id IS NOT NULL OR b.state<>'ready' OR b.message_id IS NOT NULL OR b.encounter_id IS NOT NULL OR b.next_round_id IS NOT NULL
   OR source_row.superseded_at IS NOT NULL OR source_row.consumed_message_id IS NOT NULL
   OR source_row.context->>'source_revision'<>'ac9aedbd59dcb835d717f4ddb6ce195e3c2a9d640df576667290fa38b7e6cbbb' OR mission_generic_owner.role_source_revision_v1(p_session)<>'ac9aedbd59dcb835d717f4ddb6ce195e3c2a9d640df576667290fa38b7e6cbbb'
   OR source_row.role_ids<>ARRAY['d59bf486-65b8-4a93-8b60-6cb516bb9481'::uuid,'73f030ea-4b37-423a-93bb-f991ded79e35'::uuid]
   OR EXISTS(SELECT 1 FROM unnest(source_row.role_ids) rid WHERE NOT EXISTS(SELECT 1 FROM mission_generic_owner.role_latest_v1(p_session) lr WHERE lr.message_id=rid AND lr.valid))
   OR EXISTS(SELECT 1 FROM public.combat_v2_sessions WHERE master_session_id=p_session AND closed_at IS NULL)
   OR EXISTS(SELECT 1 FROM mission_generic_owner.work_items nw WHERE nw.master_session_id=p_session AND nw.created_at>w.created_at)
   OR EXISTS(SELECT 1 FROM mission_generic_owner.unified_segment_publications_v4 WHERE work_id=w.id)
   OR EXISTS(SELECT 1 FROM mission_generic_owner.work_items x WHERE x.id IN(w.id,old_director.id) AND(x.finalized_at IS NULL OR x.payload_sha256<>public.combat_v2_sha256(x.payload)))
   OR (SELECT count(*) FROM mission_generic_owner.work_items x JOIN mission_narrative_internal.dispatch_receipts dr ON dr.id=x.dispatch_receipt_id AND dr.master_session_id=p_session AND dr.authority_receipt_id=x.id AND dr.request_key=x.request_key AND dr.dispatch_count=1 AND dr.finalized_at IS NOT NULL
      JOIN staff_ai_quota_private.calls q ON q.producer='mission_generic_ai' AND q.source_id=dr.id AND q.call_no=1 AND q.scope_id=p_session AND q.state='settled' AND q.charged_usd=dr.charged_cost_usd WHERE x.id IN(w.id,old_director.id))<>2
  THEN RAISE EXCEPTION 'FREE_RECOVERY_SOURCE_PROOF' USING ERRCODE='40001';END IF;
  UPDATE mission_generic_owner.unified_source_windows SET superseded_at=clock_timestamp(),superseded_reason='staff_unpublished_reinterpretation' WHERE id=source_row.id;
  INSERT INTO mission_narrative_internal.dispatch_audit(receipt_id,event_code,details)VALUES(old_director.dispatch_receipt_id,'staff_unpublished_reinterpretation',jsonb_build_object('schema_version','mission-unpublished-reinterpretation/1','master_session_id',p_session,'source_window_id',source_row.id,'source_revision','ac9aedbd59dcb835d717f4ddb6ce195e3c2a9d640df576667290fa38b7e6cbbb','director_result_sha256',old_director.result_sha256,'writer_result_sha256',w.result_sha256,'successor_progress_key',successor_key,'actor_user',p_staff,'old_work_preserved',true,'generation_http_calls',0));
  result_row:=mission_generic_owner.progress_step(p_session,p_staff,successor_key);
  INSERT INTO mission_generic_owner.progress_receipts(request_key,master_session_id,actor_user_id,result,result_sha256)VALUES(successor_key,p_session,p_staff,result_row,public.combat_v2_sha256(result_row));
  SELECT * INTO STRICT successor FROM mission_generic_owner.work_items WHERE id=(result_row#>>'{dispatch,event_id}')::uuid AND kind='director' AND state='ready' AND master_session_id=p_session;
  result_row:=mission_public_owner.work_contract_issue_v1(successor.id);
  IF (result_row->'features' ? 'provider_output_retention_v1') IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'FREE_RECOVERY_NEW_CONTRACT';END IF;
  RETURN jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1','status','recovered','master_session_id',p_session,'work_id',successor.id,'replayed',false);
 END IF;


 IF p_session='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid AND p_work='e76f31f2-eded-495e-9c5f-f03461c5cc3a'::uuid THEN
