 AND public.combat_v2_sha256(w.payload#>'{resolved_scenes,0}')='8ffc1e7abc84f8db7da30e3af234ab6e574106464cb760fa4204891291af3f53' AND public.combat_v2_sha256(w.payload#>'{resolved_scenes,1}')='37de1843c7c1967d25a564e2cd682bc2e4baae20d996aac647365529e0ae06bb' AND jsonb_array_length(w.payload->'resolved_scenes')=2 AND w.payload->'pending_offensives'='[]'::jsonb AND w.payload->'source_windows'='[]'::jsonb
 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(w.payload->'resolved_scenes') item
 WHERE NOT EXISTS(SELECT 1 FROM public.combat_v2_round_reports rp JOIN public.combat_v2_rounds cr ON cr.id=rp.round_id
 WHERE rp.id=CASE WHEN (item#>>'{scene_binding,report_sha256}')=(SELECT mechanics_sha256 FROM public.combat_v2_round_reports WHERE id=native_batch_check.source_report_id) THEN native_batch_check.source_report_id ELSE native_batch_check.secondary_report_id END
 AND item->>'schema_version'='mission-generic-narration/2' AND item->>'mode'='combat'
 AND item#>>'{scene_binding,session_id}'=native_batch_check.encounter_id::text AND item#>>'{scene_binding,control_version}'=native_batch_check.run_control_version::text
 AND item#>>'{scene_binding,round_id}'=cr.id::text AND item#>>'{scene_binding,report_sha256}'=rp.mechanics_sha256
 AND item#>>'{scene,snapshot_sha256}'=public.combat_v2_sha256(item#>'{scene,snapshot}')
 AND item#>>'{scene_binding,scene_sha256}'=item#>>'{scene,snapshot_sha256}'
 AND item->'barrier'=jsonb_build_object('closed',true,'required_receipt_ids',jsonb_build_array(rp.id),'receipt_ids',jsonb_build_array(rp.id))
 AND cr.session_id=native_batch_check.encounter_id AND cr.report_id=rp.id AND cr.state='risolto' AND cr.resolved_at IS NOT NULL
 AND rp.narration_state='attesa' AND rp.mechanics_sha256=public.combat_v2_sha256(rp.mechanics) AND rp.values_written IS FALSE))
 AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.unified_report_publications pub WHERE pub.report_id IN(native_batch_check.source_report_id,native_batch_check.secondary_report_id))
 AND public.combat_v2_values_written(native_batch_check.encounter_id) IS FALSE AND combat_panel_private.uses_simulated_pools(native_batch_check.encounter_id) IS TRUE
 AND EXISTS(SELECT 1 FROM public.mission_run_state r WHERE r.master_session_id=w.master_session_id AND r.run_phase='in_corso' AND r.current_step_key=native_batch_check.step_key AND r.control_version=native_batch_check.run_control_version)
 )
  OR NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts d JOIN mission_narrative_internal.dispatch_audit a ON a.receipt_id=d.id AND a.event_code='generic_count_overflow_terminal'
   WHERE d.id=w.dispatch_receipt_id AND d.status='failed' AND d.dispatch_count=0 AND d.charged_cost_usd=0 AND d.finalized_at IS NOT NULL
   AND a.details->>'work_id'=w.id::text AND a.details->>'receipt_id'=w.receipt_id::text AND a.details->>'result_sha256'=w.result_sha256 AND a.details->>'payload_sha256'=w.payload_sha256)
  THEN RAISE EXCEPTION 'C889_RECOVERY_BINDING' USING ERRCODE='40001';END IF;
  INSERT INTO mission_generic_owner.work_items(id,master_session_id,event_id,request_key,dedupe_key,step_key,run_control_version,definition_sha256,encounter_id,authority_receipt_id,kind,revision,payload,payload_sha256)
  VALUES(successor_id,p_session,successor_event,successor_key,'c889-count-reissue:'||w.id::text,w.step_key,w.run_control_version,w.definition_sha256,w.encounter_id,b.id,'narration',w.revision,w.payload,w.payload_sha256) RETURNING * INTO successor;
  UPDATE mission_generic_owner.unified_batches SET writer_work_id=successor_id WHERE id=b.id AND writer_work_id=w.id;
  IF NOT FOUND THEN RAISE EXCEPTION 'C889_WRITER_CAS' USING ERRCODE='40001';END IF;
  INSERT INTO mission_narrative_internal.dispatch_audit(receipt_id,event_code,details) VALUES(w.dispatch_receipt_id,'c889_count_narration_reissued',jsonb_build_object('schema_version','c889-native-report-reissue/1','old_work_id',w.id,'work_id',successor_id,'batch_id',b.id,'payload_sha256',w.payload_sha256,'generation_http_calls',0));
  RETURN jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1','status','recovered','master_session_id',p_session,'work_id',successor_id,'replayed',false);
 END IF;
  if p_session='ce7bc0e0-c8ed-48dd-a9ec-58c02022a7b9'::uuid
    and p_work='42341080-7f78-494e-9adf-85de7cfce038'::uuid and exists(
    select 1 from mission_generic_owner.work_items ow where ow.id=p_work and ow.master_session_id=p_session
      and ow.kind='narration' and ow.state='failed'
      and ow.result->>'schema_version'='mission-count-overflow-failure/1') then
    perform mission_generic_owner.dispatch_user(p_session,p_staff);
    if p_staff not in('f0856d53-83a6-4de0-bc0c-12c87916e665'::uuid,'b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b'::uuid)
    or m.location_id<>'0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid or m.owner_kind<>'ai_service'
    or m.closed_at is not null or m.suspended_at is not null
    or not exists(select 1 from public.profiles where id=p_staff and role in('admin','master'))
    or mission_generic_owner.c726_factory_staff_runtime_v1(p_session) is distinct from true
    or mission_staff_abort_private.quiescent_v1(p_session) is distinct from true
    or (mission_generic_owner.c7_run_budget_v1(p_session,true,null)->>'allowed') is distinct from 'true'
    then raise exception 'MCR_COUNT_SCOPE' using errcode='42501';end if;
    perform 1 from mission_generic_owner.role_window_cursors where master_session_id=p_session for update;
    if not found then raise exception 'MCR_CURSOR_MISSING' using errcode='55000';end if;
    perform 1 from public.master_v2_sessions where id=p_session for update;
    select * into strict w from mission_generic_owner.work_items where id=p_work and master_session_id=p_session for update;
    if w.payload_sha256<>public.combat_v2_sha256(w.payload) or w.result_sha256<>public.combat_v2_sha256(w.result)
    or w.authorization_id is not null or w.dispatch_id is not null or w.message_id is not null
    or w.finalized_at is null or w.receipt_id is null or w.result->>'provider_calls'<>'0'
    or w.result->>'outcome_uncertain'<>'false' or w.result->>'failure_code'<>'MISSION_INPUT_COUNT_OVERFLOW'
    or not exists(select 1 from mission_narrative_internal.dispatch_receipts d
       join mission_narrative_internal.dispatch_audit a on a.receipt_id=d.id and a.event_code='generic_count_overflow_terminal'
       where d.id=w.dispatch_receipt_id and d.authority_receipt_id=w.id and d.master_session_id=p_session
        and d.status='failed' and d.dispatch_count=0 and d.finalized_at is not null and d.charged_cost_usd=0
        and a.details->>'work_id'=w.id::text and a.details->>'receipt_id'=w.receipt_id::text
        and a.details->>'payload_sha256'=w.payload_sha256 and a.details->>'result_sha256'=w.result_sha256
        and a.details->>'generation_http_calls'='0')
    then raise exception 'MCR_COUNT_PROOF' using errcode='40001';end if;
    select * into strict b from mission_generic_owner.unified_batches where id=w.authority_receipt_id and master_session_id=p_session for update;
    select * into strict source_row from mission_generic_owner.unified_source_windows where id=b.source_window_id and master_session_id=p_session for update;
    select * into strict run_row from public.mission_run_state where master_session_id=p_session for update;
    successor_id:=md5('C1264:NARRATION:work:'||w.id::text)::uuid;
    successor_event:=md5('C1264:NARRATION:event:'||w.id::text)::uuid;
    successor_key:=md5('C1264:NARRATION:request:'||w.id::text)::uuid;
    if b.state<>'ready' or b.message_id is not null or source_row.superseded_at is not null or source_row.consumed_message_id is not null
    or b.payload is distinct from w.payload or b.payload_sha256<>w.payload_sha256
    or b.step_key<>w.step_key or b.run_control_version<>w.run_control_version
    or run_row.current_step_key<>w.step_key or run_row.control_version<>w.run_control_version or run_row.run_phase<>'in_corso'
    or w.payload->>'source_revision' is distinct from mission_generic_owner.role_source_revision_v1(p_session)
    or w.payload#>>'{publication_barrier,closed}' is distinct from 'true'
    or w.payload#>'{publication_barrier,required_receipt_ids}' is distinct from w.payload#>'{publication_barrier,receipt_ids}'
    or (w.payload#>'{publication_barrier,receipt_ids}' @> jsonb_build_array(b.id)) is distinct from true
    or exists(select 1 from mission_generic_owner.unified_segment_publications_v4 where work_id=w.id)
    or not exists(select 1 from mission_generic_owner.work_items dw where dw.id=b.decision_work_id and dw.kind='director'
      and dw.state='completed' and dw.result->>'ok'='true' and dw.result->'decision'=b.decision
      and b.decision_sha256=public.combat_v2_sha256(b.decision) and source_row.work_id=dw.id
      and source_row.source_sha256=dw.payload_sha256 and source_row.definition_sha256=w.definition_sha256)
    then raise exception 'MCR_COUNT_SOURCE_CHANGED' using errcode='40001';end if;
    if b.writer_work_id=successor_id then
      select * into strict successor from mission_generic_owner.work_items where id=successor_id;
      if successor.master_session_id<>p_session or successor.authority_receipt_id<>b.id or successor.kind<>'narration'
      or successor.event_id<>successor_event or successor.request_key<>successor_key
      or successor.payload is distinct from w.payload or successor.payload_sha256<>w.payload_sha256
      then raise exception 'MCR_COUNT_REPLAY_CHANGED' using errcode='40001';end if;
      return jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1','status','recovered','master_session_id',p_session,'work_id',successor.id,'replayed',true);
    end if;
    if b.writer_work_id<>w.id then raise exception 'MCR_COUNT_WRITER_CHANGED' using errcode='40001';end if;
    insert into mission_generic_owner.work_items(id,master_session_id,event_id,request_key,dedupe_key,step_key,run_control_version,definition_sha256,encounter_id,authority_receipt_id,kind,revision,payload,payload_sha256)
    values(successor_id,p_session,successor_event,successor_key,'count-narration-reissue:'||w.id::text,w.step_key,w.run_control_version,w.definition_sha256,w.encounter_id,b.id,'narration',w.revision,w.payload,w.payload_sha256) returning * into successor;
    update mission_generic_owner.unified_batches set writer_work_id=successor.id where id=b.id and writer_work_id=w.id;
    if not found then raise exception 'MCR_COUNT_WRITER_CAS' using errcode='40001';end if;
    insert into mission_narrative_internal.dispatch_audit(receipt_id,event_code,details) values(w.dispatch_receipt_id,'generic_count_narration_reissued',jsonb_build_object('schema_version','c1264-count-narration-reissue/1','old_work_id',w.id,'work_id',successor.id,'batch_id',b.id,'source_window_id',b.source_window_id,'payload_sha256',w.payload_sha256,'actor_user',p_staff,'generation_http_calls',0));
    return jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1','status','recovered','master_session_id',p_session,'work_id',successor.id,'replayed',false);
  end if;

  factory_cached:=p_session='ce7bc0e0-c8ed-48dd-a9ec-58c02022a7b9'::uuid
   and p_work='86e5b361-9d82-aee8-a840-b09a83126fc0'::uuid
   and p_staff in('f0856d53-83a6-4de0-bc0c-12c87916e665'::uuid,'b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b'::uuid)
   and mission_generic_owner.c726_factory_staff_runtime_v1(p_session) is true
   and (select count(*) from public.master_v2_participants where session_id=p_session and engagement_state='attivo' and left_at is null)=2
   and not exists(select 1 from public.master_v2_participants mp join public.characters ch on ch.id=mp.character_id
     where mp.session_id=p_session and mp.engagement_state='attivo' and mp.left_at is null
      and (ch.user_id is distinct from mp.user_id_snapshot or ch.user_id not in('f0856d53-83a6-4de0-bc0c-12c87916e665'::uuid,'b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b'::uuid)))
   and exists(select 1 from mission_generic_owner.run_bindings rb where rb.master_session_id=p_session
     and rb.snapshot_sha256='49817335c60ce9d4b47bc5d81c6950f622635c7fb232264ab54736349124f567'
     and rb.snapshot_sha256=mission_internal.fingerprint(rb.snapshot));
  if factory_cached then perform mission_generic_owner.dispatch_user(p_session,p_staff);end if;
  if m.location_id is distinct from '0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
    or m.owner_kind <> 'ai_service' or m.closed_at is not null
    or not (mission_academy_owner.staff_carrier_runtime(p_session) or factory_cached)
    or not mission_generic_owner.flow_scope_enabled(p_session)
    or not exists(select 1 from public.profiles where id=p_staff and role in ('admin','master'))
    or combat_consumer_private.staff_test_allowed(m.location_id,array[p_staff],false) is distinct from true
  then raise exception 'MCR_STAFF_SCOPE' using errcode='42501'; end if;

  perform 1 from mission_generic_owner.role_window_cursors
    where master_session_id=p_session for update;
  if not found then raise exception 'MCR_CURSOR_MISSING' using errcode='55000'; end if;
  perform 1 from public.master_v2_sessions where id=p_session for update;
  select * into strict w from mission_generic_owner.work_items
    where id=p_work and master_session_id=p_session for update;
  if w.state='completed' and w.message_id is not null and exists(
    select 1 from mission_generic_owner.unified_segment_publications_v4
    where work_id=w.id and message_id=w.message_id) then
    return jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1',
      'status','published','message_id',w.message_id,'replayed',true);
  end if;
  if w.kind<>'narration' or w.payload->>'schema_version'<>'mission-generic-narration/4'
    or w.state<>'failed' or w.result->>'ok'<>'true'
    or w.result->>'provider_calls'<>'1' or w.result->>'outcome_uncertain'<>'false'
    or w.result_sha256 !~ '^[0-9a-f]{64}$' or w.message_id is not null
  then return jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1',
    'status','not_applicable'); end if;
  select * into strict b from mission_generic_owner.unified_batches
    where id=w.authority_receipt_id and master_session_id=p_session and writer_work_id=w.id for update;
  select * into strict source_row from mission_generic_owner.unified_source_windows
    where id=b.source_window_id and master_session_id=p_session for update;
  select * into strict run_row from public.mission_run_state
    where master_session_id=p_session for update;
  select * into strict receipt from mission_narrative_internal.dispatch_receipts
    where id=w.dispatch_receipt_id for share;
  if b.state<>'ready' or b.message_id is not null
    or source_row.superseded_at is not null or source_row.consumed_message_id is not null
    or run_row.run_phase<>'in_corso' or run_row.current_step_key<>w.step_key
    or run_row.control_version<>w.run_control_version
    or w.payload->>'source_revision' is distinct from mission_generic_owner.role_source_revision_v1(p_session)
    or w.payload is distinct from b.payload or w.payload_sha256<>b.payload_sha256
    or w.result->>'work_id' is distinct from w.id::text
    or w.result->>'master_session_id' is distinct from p_session::text
    or w.result->>'request_key' is distinct from w.request_key::text
    or w.result->>'payload_sha256' is distinct from w.payload_sha256
    or receipt.status<>'success' or receipt.finalized_at is null
    or receipt.charged_cost_usd is null
    or exists(select 1 from mission_generic_owner.unified_segment_publications_v4
      where work_id=w.id)
  then raise exception 'MCR_SOURCE_CHANGED' using errcode='40001'; end if;

  if factory_cached and not exists(
   select 1 from mission_narrative_internal.dispatch_receipts nd
   join mission_narrative_internal.dispatch_audit ga on ga.receipt_id=nd.id and ga.event_code='generic_finalized'
   join mission_narrative_internal.dispatch_audit cp on cp.receipt_id=nd.id and cp.event_code='c8_count_success'
   join mission_narrative_internal.provider_authorizations pa on pa.id=w.authorization_id and pa.receipt_id=nd.id
   join mission_narrative_internal.dispatch_attempts na on na.receipt_id=nd.id and na.id=pa.attempt_id
   join staff_ai_quota_private.calls qc on qc.source_id=nd.id and qc.producer='mission_generic_ai' and qc.call_no=1
   where nd.id=w.dispatch_receipt_id and nd.authority_receipt_id=w.id and nd.master_session_id=p_session
    and nd.request_key=w.request_key and nd.status='success' and nd.dispatch_count=1 and nd.finalized_at is not null
    and nd.charged_cost_usd is not null and nd.lease_token_sha256 is null and nd.lease_expires_at is null
    and na.status='success' and na.finalized_at is not null and na.cost_basis='exact'
    and na.actual_cost_usd=nd.charged_cost_usd and qc.scope_id=p_session and qc.state='settled' and qc.charged_usd=nd.charged_cost_usd
    and ga.details->>'work_id'=w.id::text and ga.details->>'receipt_id'=w.receipt_id::text
    and ga.details->>'state'='failed' and ga.details->>'outcome_uncertain'='false'
    and ga.details->>'application_error_sqlstate'='42703'
    and ga.details->>'result_sha256'=w.result_sha256
    and ga.details->>'result_jsonb_sha256'=public.combat_v2_sha256(w.result)
    and cp.details->>'work_id'=w.id::text and cp.details->>'state'='success'
    and cp.details->>'generation_allowed'='true' and cp.details->>'input_tokens'='10066'
    and cp.details->>'max_input_tokens'='12000'
    and w.authority_receipt_id='08512119-3bfd-4df7-adbc-0686f5edf5b7'::uuid
    and w.definition_sha256='49817335c60ce9d4b47bc5d81c6950f622635c7fb232264ab54736349124f567'
    and w.result->>'schema_version'='mission-generic-result/2' and jsonb_typeof(w.result->'segments')='array'
    and w.result->'text'='null'::jsonb
    and not exists(select 1 from mission_generic_owner.work_items other where other.master_session_id=p_session and other.state in('claimed','authorized','provider_started','uncertain'))
    and not exists(select 1 from mission_narrative_internal.dispatch_attempts pending join mission_narrative_internal.dispatch_receipts pd on pd.id=pending.receipt_id where pd.master_session_id=p_session and pending.finalized_at is null)
  ) then raise exception 'MCR_FACTORY_CACHED_RECEIPT' using errcode='40001';end if;
  perform mission_generic_owner.work_assert(w);

  begin
    update mission_generic_owner.work_items set state='provider_started',finalized_at=null
      where id=w.id and state='failed';
    result_row:=mission_generic_owner.unified_publish_v4(
      w.id,w.result,w.request_key,w.result_sha256);
    message_ref:=(result_row->>'message_id')::uuid;
    if message_ref is null then raise exception 'MCR_PUBLICATION_MISSING'; end if;
    update mission_generic_owner.work_items
      set state='completed',finalized_at=clock_timestamp(),message_id=message_ref,
        result=result||jsonb_build_object('text',result_row->>'text','continuity',result_row->'continuity'),
        result_sha256=public.combat_v2_sha256(result||jsonb_build_object(
          'text',result_row->>'text','continuity',result_row->'continuity'))
      where id=w.id and state='provider_started';
    if not found then raise exception 'MCR_WORK_CAS'; end if;
  exception when others then
    get stacked diagnostics error_state=returned_sqlstate,error_message=message_text,
      error_constraint=constraint_name,error_table=table_name,error_schema=schema_name,
      diagnostic_column=column_name,diagnostic_context=pg_exception_context,native_selection_detail=pg_exception_detail;
    IF error_state='55000' AND error_message='MRS_V4_NO_LEGAL_NATIVE_ATTACK' AND octet_length(native_selection_detail)<=8192 THEN
      BEGIN
        native_selection_diagnostic:=native_selection_detail::jsonb;
        IF mission_factory_owner.keys_exact_v2(native_selection_diagnostic,ARRAY['schema_version','actor_key','round_phase','counts','producer_counts','producer_called']) IS DISTINCT FROM true
          OR native_selection_diagnostic->>'schema_version' IS DISTINCT FROM 'mission-native-attack-selection-diagnostic/2'
          OR coalesce(native_selection_diagnostic->>'actor_key','')!~'^[a-z][a-z0-9_]{0,63}$'
          OR coalesce(native_selection_diagnostic->>'round_phase','') NOT IN('raccolta_azioni','raccolta_difese','risoluzione','risolto','narrazione','narrato','other')
          OR mission_factory_owner.keys_exact_v2(native_selection_diagnostic->'counts',ARRAY['actor_offers','principal_match','offered','action','master_adapter','action_dispatch','attack','mano','in_projection','no_required_inputs','supported_groups','candidate_count','shape_rejected','pg_target_count','multiple_move_groups','move_shape_rejected','move_option_missing','extra_dependency_rejected']) IS DISTINCT FROM true
          OR jsonb_typeof(native_selection_diagnostic->'producer_called') IS DISTINCT FROM 'boolean'
          OR mission_factory_owner.keys_exact_v2(native_selection_diagnostic->'producer_counts',ARRAY['targets_total','targets_seen','mano_seen','geometry_stay','endpoint_count','pending_count','rejected_geometry','label_present','legal_total','action_entered']) IS DISTINCT FROM true
          OR EXISTS(SELECT 1 FROM jsonb_each(native_selection_diagnostic->'producer_counts') x WHERE jsonb_typeof(x.value) IS DISTINCT FROM 'number' OR (x.value#>>'{}')!~'^[0-9]{1,6}$')
          OR EXISTS(SELECT 1 FROM jsonb_each(native_selection_diagnostic->'counts') x WHERE jsonb_typeof(x.value) IS DISTINCT FROM 'number' OR (x.value#>>'{}')!~'^[0-9]{1,6}$')
        THEN native_selection_diagnostic:=NULL;END IF;
      EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value THEN native_selection_diagnostic:=NULL;END;
    END IF;
    if factory_cached then
      if diagnostic_column !~ '^[A-Za-z_][A-Za-z0-9_]{0,62}$' then diagnostic_column:=null;end if;
      if diagnostic_column is null and error_state='42703' then
        diagnostic_column:=coalesce(
          substring(error_message from '^column "([A-Za-z_][A-Za-z0-9_]{0,62})" does not exist$'),
          substring(error_message from '^record "[A-Za-z_][A-Za-z0-9_]{0,62}" has no field "([A-Za-z_][A-Za-z0-9_]{0,62})"$'),
          substring(error_message from '^column [A-Za-z_][A-Za-z0-9_]{0,62}\.([A-Za-z_][A-Za-z0-9_]{0,62}) does not exist$'));
      end if;
      if error_table !~ '^[A-Za-z_][A-Za-z0-9_]{0,62}$' then error_table:=null;end if;
      if error_schema !~ '^[A-Za-z_][A-Za-z0-9_]{0,62}$' then error_schema:=null;end if;
      select coalesce(jsonb_agg(jsonb_build_object('function',parts[1],'line',parts[2]::integer) order by ordinal),'[]'::jsonb) into diagnostic_frames
        from (select parts,ordinal from regexp_matches(diagnostic_context,'PL/pgSQL function ([A-Za-z_][A-Za-z0-9_.]*)\([^)]*\) line ([0-9]{1,6})','g') with ordinality f(parts,ordinal) limit 8) frames;
    end if;
    safe_code:=case when error_message ~ '^[A-Z][A-Z0-9_]{1,79}$'
      then error_message else 'SQLSTATE_'||error_state end;
  end;
  if safe_code is not null then
    insert into mission_narrative_internal.dispatch_audit(receipt_id,event_code,details)
      values(receipt.id,'staff_cached_publication_rejected',jsonb_build_object(
        'work_id',w.id,'master_session_id',p_session,
        'sqlstate',error_state,'error_code',safe_code,
        'constraint_name',nullif(error_constraint,''),
        'table_name',nullif(error_table,''),
        'schema_name',nullif(error_schema,'')) || CASE WHEN native_selection_diagnostic IS NOT NULL THEN jsonb_build_object('private_native_attack_selection',native_selection_diagnostic) ELSE '{}'::jsonb END || case when factory_cached then jsonb_build_object('private_diagnostics',jsonb_build_object('schema_version','c1264-cached-private-error/1','column',diagnostic_column,'table',error_table,'schema',error_schema,'frames',diagnostic_frames)) else '{}'::jsonb end);
    return jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1',
      'status','failed','error_code',safe_code);
  end if;
  insert into mission_narrative_internal.dispatch_audit(receipt_id,event_code,details)
    values(receipt.id,'staff_cached_publication_completed',jsonb_build_object(
      'work_id',w.id,'master_session_id',p_session,'message_id',message_ref));
  return jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1',
    'status','published','message_id',message_ref,'replayed',false);
end
$function$;


CREATE OR REPLACE FUNCTION public.regia_round_publication_state_v1(p_master_session uuid, p_actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m public.master_v2_sessions%ROWTYPE;
 s public.combat_v2_sessions%ROWTYPE;
 r public.combat_v2_rounds%ROWTYPE;
 w mission_generic_owner.unified_round_windows%ROWTYPE;
 pw mission_generic_owner.unified_round_windows%ROWTYPE;
 b mission_generic_owner.unified_batches%ROWTYPE;
 hw mission_generic_owner.regia_human_windows_v1%ROWTYPE;
 report public.combat_v2_round_reports%ROWTYPE;
 is_master boolean; can_main boolean:=false; can_defend boolean:=false;
 slots jsonb:='[]'::jsonb;
 private_hw boolean:=false;
 scene56_receipt jsonb;scene56_round public.combat_v2_rounds;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'REGIA_ACCESS_DENIED' USING ERRCODE='42501'; END IF;
 SELECT * INTO m FROM public.master_v2_sessions WHERE id=p_master_session;
 IF EXISTS(SELECT 1 FROM exam_human_private.requests e
   WHERE e.master_session_id=m.id AND e.state='combat')
 THEN RETURN exam_human_private.round_publication_state_v1(m.id,p_actor); END IF;
 IF m.id IS NULL OR NOT EXISTS(SELECT 1 FROM public.locations l
    WHERE l.id=m.location_id AND l.id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
      AND l.is_active AND l.is_test)
   AND NOT mission_public_owner.role_session_allowed_v1(m.id)
   AND NOT mission_public_owner.human_session_allowed_v1(m.id)
 THEN RETURN jsonb_build_object('schema_version','regia-round-publication-state/1',
    'status','unavailable','reason_code','not_opted_in','public',null,'master',null); END IF;
 is_master:=coalesce(m.master_user=auth.uid() AND public.master_v2_is_master(auth.uid()),false);
 IF NOT is_master
   AND mission_generic_owner.principal_in_session(m.id,auth.uid()) IS NOT TRUE
   AND NOT EXISTS(SELECT 1 FROM public.master_v2_participants p
      JOIN public.characters c ON c.id=p.character_id AND c.user_id=p.user_id_snapshot
      WHERE p.session_id=m.id AND p.user_id_snapshot=auth.uid()
        AND p.left_at IS NULL AND p.engagement_state='attivo')
 THEN RAISE EXCEPTION 'REGIA_ACCESS_DENIED' USING ERRCODE='42501'; END IF;
 IF p_actor IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.combat_v2_actors a
   JOIN public.combat_v2_sessions cs ON cs.id=a.session_id
   WHERE a.id=p_actor AND cs.master_session_id=m.id
     AND a.controller_user=auth.uid())
 THEN RAISE EXCEPTION 'REGIA_ACCESS_DENIED' USING ERRCODE='42501'; END IF;
 SELECT * INTO s FROM public.combat_v2_sessions
   WHERE master_session_id=m.id AND state NOT IN('chiuso','annullato')
   ORDER BY created_at DESC LIMIT 1;
 IF s.id IS NULL THEN RETURN jsonb_build_object('schema_version','regia-round-publication-state/1',
   'status',CASE WHEN is_master THEN 'ready' ELSE 'unavailable' END,
   'activity_id',m.id,'actor_id',p_actor,
   'reason_code','REGIA_ENTRY_STAGING_REQUIRED',
   'public',jsonb_build_object('schema_version','regia-round-public/1',
     'window_id',null,'public_round_id',null,'publication_id',null,
     'publication_revision',m.control_version,'context_version',m.control_version,
     'permissions',jsonb_build_object('main',false,'defense',false,'reaction',false),
     'reason_code','regia_fato_pending'),
   'master',CASE WHEN is_master THEN jsonb_build_object(
     'schema_version','regia-round-preparation/1','window_id',null,
     'source_round_id',null,'source_report_id',null,'source_report_sha256',null,
     'next_round_id',null,'preparation_revision',m.control_version,
     'control_version',m.control_version,'side',null,'legal_png_slots','[]'::jsonb,
     'state','entry_staging_required','can_prepare',false,'can_publish',false,
     'direction_context',mission_generic_owner.regia_human_direction_context_v1(m.id))
     ELSE NULL END); END IF;
 IF NOT (SELECT l.is_test FROM public.locations l WHERE l.id=m.location_id)
  AND NOT ((m.owner_kind='ai_service' AND mission_public_owner.ai_resource_scope_v1(m.id,s.id))
    OR (m.owner_kind='human' AND mission_public_owner.human_resource_scope_v1(m.id,s.id,false)))
 THEN RAISE EXCEPTION 'REGIA_RESOURCE_POLICY_DRIFT' USING ERRCODE='42501'; END IF;
 IF m.owner_kind='ai_service' AND EXISTS(SELECT 1 FROM mission_narrative_internal.scene_runtime_v1 cache WHERE cache.master_session_id=m.id AND cache.is_active)
  AND EXISTS(SELECT 1 FROM mission_narrative_internal.scene_runtime_v1 cache WHERE cache.master_session_id=m.id AND cache.is_active AND cache.mode='combat')
  AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.unified_round_windows uw JOIN public.combat_v2_rounds rr ON rr.id=uw.round_id WHERE rr.session_id=s.id) THEN
  SELECT * INTO scene56_round FROM public.combat_v2_rounds rr WHERE rr.session_id=s.id ORDER BY rr.round_no DESC LIMIT 1;
  IF scene56_round.round_no=1 THEN
   scene56_receipt:=mission_narrative_internal.scene_opening_receipt_v1(scene56_round.id);
  ELSIF mission_narrative_internal.scene_native_round_bound_v1(m.id,scene56_round.id) THEN
   SELECT jsonb_build_object('publication_id',cache.last_publication_id,'state_version_after',cache.state_version) INTO scene56_receipt
   FROM mission_narrative_internal.scene_runtime_v1 cache
   JOIN public.combat_v2_rounds previous ON previous.session_id=s.id AND previous.round_no=scene56_round.round_no-1
   JOIN public.combat_v2_round_reports previous_report ON previous_report.id=previous.report_id AND previous_report.round_id=previous.id
    AND previous_report.message_id=cache.last_publication_id AND previous_report.narration_state='pubblicata'
   JOIN public.messages published ON published.id=cache.last_publication_id AND published.location_id=m.location_id
   WHERE cache.master_session_id=m.id AND cache.is_active AND cache.mode='combat'
    AND encode(extensions.digest(convert_to(published.body,'UTF8'),'sha256'),'hex')=cache.last_publication_sha256;
  END IF;
  SELECT coalesce((SELECT jsonb_build_object('publication_id',ss.published_message_id,'state_version_after',cache.state_version)
   FROM mission_narrative_internal.scene_sources_v1 ss
   JOIN mission_narrative_internal.scene_runtime_v1 cache ON cache.id=ss.scene_id AND cache.last_publication_id=ss.published_message_id
   JOIN public.messages msg ON msg.id=ss.published_message_id AND msg.location_id=m.location_id AND msg.kind='fato' AND msg.recipient_user IS NULL
   WHERE cache.master_session_id=m.id AND cache.is_active AND ss.request_kind='combat_intent' AND ss.retired_at IS NULL
    AND ss.technical_request->>'round_id'=scene56_round.id::text
    AND encode(extensions.digest(convert_to(msg.body,'UTF8'),'sha256'),'hex')=cache.last_publication_sha256),scene56_receipt) INTO scene56_receipt;
  IF scene56_receipt IS NOT NULL THEN
   can_main:=p_actor IS NOT NULL AND scene56_round.phase='raccolta_azioni' AND EXISTS(SELECT 1 FROM public.combat_v2_actors a
    WHERE a.id=p_actor AND a.session_id=s.id AND a.actor_kind='pg' AND a.state='attivo' AND a.controller_user=auth.uid()
    AND NOT EXISTS(SELECT 1 FROM public.combat_v2_declarations d WHERE d.round_id=scene56_round.id AND d.actor_id=a.id AND d.kind IN('attacco','movimento','utilita','passa')));
   can_defend:=p_actor IS NOT NULL AND scene56_round.phase='raccolta_difese' AND EXISTS(SELECT 1 FROM public.combat_v2_attack_targets t WHERE t.round_id=scene56_round.id AND t.target_actor_id=p_actor AND t.state='attesa_difesa') AND NOT EXISTS(SELECT 1 FROM public.combat_v2_declarations d WHERE d.round_id=scene56_round.id AND d.actor_id=p_actor AND d.kind IN('difesa','nessuna'));
   IF NOT EXISTS(SELECT 1 FROM mission_narrative_internal.scene_runtime_v1 cache WHERE cache.master_session_id=m.id AND cache.turn_owner='combat') THEN can_main:=false;can_defend:=false;END IF;
   -- Match the public pending frame before queue preparation as well as during
   -- the Writer lease: a direct native panel RPC cannot bypass this barrier.
   IF EXISTS(SELECT 1 FROM public.combat_v2_declarations pending
     JOIN public.combat_v2_actors png ON png.id=pending.actor_id AND png.actor_kind='png'
     WHERE pending.round_id=scene56_round.id
      AND NOT(pending.kind='nessuna' AND coalesce(pending.declaration_text,'')='')
      AND NOT mission_narrative_internal.scene_native_declaration_public_v1(pending.id))
   THEN can_main:=false;can_defend:=false;END IF;
   IF can_defend AND EXISTS(SELECT 1 FROM public.combat_v2_declarations attack
    JOIN public.combat_v2_actors attacker ON attacker.id=attack.actor_id AND attacker.actor_kind='png'
    JOIN public.combat_v2_attack_targets target ON target.attack_declaration_id=attack.id AND target.target_actor_id=p_actor
    WHERE attack.round_id=scene56_round.id AND attack.kind='attacco'
     AND NOT EXISTS(SELECT 1 FROM combat_consumer_private.declaration_messages dm WHERE dm.declaration_id=attack.id)
     AND NOT EXISTS(SELECT 1 FROM mission_narrative_internal.scene_sources_v1 announced
       JOIN mission_narrative_internal.scene_runtime_v1 cache ON cache.id=announced.scene_id AND cache.master_session_id=m.id
       JOIN public.messages msg ON msg.id=announced.published_message_id AND msg.location_id=m.location_id AND msg.kind='fato'
       WHERE announced.request_kind='combat_intent' AND announced.retired_at IS NULL AND announced.published_message_id IS NOT NULL
        AND announced.technical_request->>'round_id'=scene56_round.id::text
        AND EXISTS(SELECT 1 FROM jsonb_array_elements(announced.technical_request->'intents') i WHERE i->>'declaration_id'=attack.id::text)))
   THEN can_defend:=false;END IF;
   RETURN jsonb_build_object('schema_version','regia-round-publication-state/1','status','ready','activity_id',m.id,'actor_id',p_actor,
    'public',jsonb_build_object('schema_version','regia-round-public/1','window_id',scene56_round.id,'public_round_id',scene56_round.id,
    'publication_id',scene56_receipt->'publication_id','publication_revision',(scene56_receipt->>'state_version_after')::bigint,
    'context_version',m.control_version,'permissions',jsonb_build_object('main',can_main,'defense',can_defend,'reaction',can_defend),
    'reason_code',null),'master',null);
  END IF;
 END IF;
 SELECT * INTO hw FROM mission_generic_owner.regia_human_windows_v1 h
  WHERE h.encounter_id=s.id AND h.side='terminal' AND h.state='private'
  ORDER BY h.created_at DESC LIMIT 1;
 IF hw.id IS NOT NULL THEN
  SELECT * INTO report FROM public.combat_v2_round_reports WHERE id=hw.source_report_id;
  RETURN jsonb_build_object('schema_version','regia-round-publication-state/1',
    'status','ready','activity_id',m.id,'actor_id',p_actor,
    'public',jsonb_build_object('schema_version','regia-round-public/1',
      'window_id',null,'public_round_id',null,'publication_id',null,
      'publication_revision',m.control_version,'context_version',m.control_version,
      'permissions',jsonb_build_object('main',false,'defense',false,'reaction',false),
      'reason_code','regia_fato_pending'),
    'master',CASE WHEN NOT is_master THEN NULL ELSE jsonb_build_object(
      'schema_version','regia-round-preparation/1',
      'window_id',hw.id,'source_round_id',hw.source_round_id,
      'source_report_id',hw.source_report_id,
      'source_report_sha256',hw.source_report_sha256,'next_round_id',null,
      'preparation_revision',hw.preparation_revision,
      'control_version',m.control_version,'side','terminal',
      'legal_png_slots','[]'::jsonb,'state','terminal',
      'can_prepare',false,'can_publish',true,
      'direction_context',mission_generic_owner.regia_human_direction_context_v1(m.id)) END);
 END IF;
 -- C1244 AGG5: prima apertura Native privata attestata anche ai PG.
 -- Nessuna proiezione Master viene consegnata; il ramo Master admitted resta invariato.
 IF m.owner_kind='human' AND m.closed_at IS NULL
   AND m.stato IN ('in_corso','sospesa')
   AND m.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
   AND EXISTS(SELECT 1 FROM public.locations loc
     WHERE loc.id=m.location_id AND loc.is_active AND loc.is_test)
   AND (NOT is_master OR NOT EXISTS(
     SELECT 1 FROM mission_generic_owner.regia_human_admissions_v1 adm
      WHERE adm.master_session_id=m.id AND adm.encounter_id=s.id))
   AND (EXISTS(SELECT 1 FROM mission_generic_owner.regia_human_session_optins_v1 opt
      WHERE opt.master_session_id=m.id AND opt.actor_user=m.master_user)
     OR EXISTS(SELECT 1 FROM mission_generic_owner.regia_human_admissions_v1 adm
      WHERE adm.master_session_id=m.id AND adm.encounter_id=s.id))
   AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.unified_round_windows uw
     JOIN public.combat_v2_rounds ur ON ur.id=uw.round_id
     WHERE uw.master_session_id=m.id AND ur.session_id=s.id)
 THEN RETURN jsonb_build_object('schema_version','regia-round-publication-state/1',
   'status','ready','activity_id',m.id,'actor_id',p_actor,
   'reason_code','REGIA_OPENING_STAGED',
   'public',jsonb_build_object('schema_version','regia-round-public/1',
     'window_id',null,'public_round_id',null,'publication_id',null,
     'publication_revision',m.control_version,'context_version',m.control_version,
     'permissions',jsonb_build_object('main',false,'defense',false,'reaction',false),
     'reason_code','regia_fato_pending'),
   'master',null); END IF;
 IF is_master AND EXISTS(SELECT 1 FROM mission_generic_owner.regia_human_admissions_v1 h
      WHERE h.encounter_id=s.id AND h.master_session_id=m.id)
   AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.unified_round_windows uw
      WHERE uw.master_session_id=m.id AND uw.round_id IN
       (SELECT id FROM public.combat_v2_rounds WHERE session_id=s.id))
 THEN
  SELECT * INTO r FROM public.combat_v2_rounds WHERE session_id=s.id
    ORDER BY round_no DESC LIMIT 1;
  IF r.state<>'risolto' THEN
   RETURN jsonb_build_object('schema_version','regia-round-publication-state/1',
     'status','ready','activity_id',m.id,'actor_id',p_actor,
     'reason_code','REGIA_OPENING_STAGED',
     'public',jsonb_build_object('schema_version','regia-round-public/1',
       'window_id',null,'public_round_id',null,'publication_id',null,
       'publication_revision',m.control_version,'context_version',m.control_version,
       'permissions',jsonb_build_object('main',false,'defense',false,'reaction',false),
       'reason_code','regia_fato_pending'),
     'master',jsonb_build_object(
       'schema_version','regia-round-preparation/1','window_id',null,
       'source_round_id',null,'source_report_id',null,'source_report_sha256',null,
       'next_round_id',r.id,'preparation_revision',m.control_version,
       'control_version',m.control_version,'side',null,'legal_png_slots','[]'::jsonb,
       'state','entry_staged',
       'can_prepare',coalesce((mission_generic_owner.regia_human_direction_context_v1(m.id)->>'can_direct')::boolean,false),
       'can_publish',false,
       'direction_context',mission_generic_owner.regia_human_direction_context_v1(m.id)));
  END IF;
  SELECT * INTO report FROM public.combat_v2_round_reports WHERE round_id=r.id;
  RETURN jsonb_build_object('schema_version','regia-round-publication-state/1',
   'status','ready','activity_id',m.id,'actor_id',p_actor,
   'public',jsonb_build_object('schema_version','regia-round-public/1',
     'window_id',r.id,'public_round_id',r.id,'publication_id',report.message_id,
     'publication_revision',m.control_version,'context_version',m.control_version,
     'permissions',jsonb_build_object('main',false,'defense',false,'reaction',false),
     'reason_code',null),
   'master',jsonb_build_object('schema_version','regia-round-preparation/1',
     'window_id',null,'source_round_id',r.id,'source_report_id',report.id,
     'source_report_sha256',report.mechanics_sha256,'next_round_id',null,
     'preparation_revision',m.control_version,'control_version',m.control_version,
     'side',null,'legal_png_slots','[]'::jsonb,'state','resolved',
     'can_prepare',r.state='risolto' AND report.narration_state='attesa',
     'can_publish',false,
     'direction_context',mission_generic_owner.regia_human_direction_context_v1(m.id)));
 END IF;
 SELECT x.* INTO r FROM public.combat_v2_rounds x
   JOIN mission_generic_owner.unified_round_windows uw ON uw.round_id=x.id
   WHERE x.session_id=s.id AND uw.master_session_id=m.id
   ORDER BY x.round_no DESC LIMIT 1;
 IF r.id IS NULL THEN RETURN jsonb_build_object('schema_version','regia-round-publication-state/1',
   'status','unavailable','reason_code','not_opted_in','public',null,'master',null); END IF;
 SELECT * INTO STRICT w FROM mission_generic_owner.unified_round_windows WHERE round_id=r.id;
 SELECT * INTO b FROM mission_generic_owner.unified_batches WHERE id=w.batch_id;
 SELECT * INTO hw FROM mission_generic_owner.regia_human_windows_v1
   WHERE next_round_id=w.round_id AND batch_id=b.id;
 -- C1244 AGG6: la finestra privata conserva il referto precedente e la propria revisione.
 private_hw:=hw.id IS NOT NULL AND hw.state='private'
   AND m.owner_kind='human'
   AND m.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
   AND w.publication_id IS NULL;
 SELECT q.* INTO report FROM public.combat_v2_round_reports q
  WHERE (private_hw AND q.id=hw.source_report_id)
     OR (NOT private_hw AND ((r.state='risolto' AND q.round_id=r.id)
       OR (r.state<>'risolto' AND q.id=b.source_report_id)))
  ORDER BY CASE WHEN q.round_id=r.id THEN 0 ELSE 1 END LIMIT 1;
 SELECT uw.* INTO pw FROM mission_generic_owner.unified_round_windows uw
   JOIN public.combat_v2_rounds rr ON rr.id=uw.round_id
   WHERE rr.session_id=s.id AND uw.publication_id IS NOT NULL
   ORDER BY rr.round_no DESC LIMIT 1;
 IF p_actor IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.combat_v2_actors a
   WHERE a.id=p_actor AND a.session_id=s.id AND a.controller_user=auth.uid())
 THEN RAISE EXCEPTION 'REGIA_ACCESS_DENIED' USING ERRCODE='42501'; END IF;
 IF w.publication_id IS NOT NULL AND p_actor IS NOT NULL THEN
   can_main:=r.phase='raccolta_azioni' AND p_actor=ANY(w.expected_actor_ids)
     AND NOT EXISTS(SELECT 1 FROM public.combat_v2_declarations d
       WHERE d.round_id=r.id AND d.actor_id=p_actor AND d.kind IN('attacco','movimento','utilita','passa'));
   can_defend:=r.phase='raccolta_difese' AND EXISTS(SELECT 1 FROM public.combat_v2_attack_targets t
       WHERE t.round_id=r.id AND t.target_actor_id=p_actor AND t.state='attesa_difesa')
     AND NOT EXISTS(SELECT 1 FROM public.combat_v2_declarations d
       WHERE d.round_id=r.id AND d.actor_id=p_actor AND d.kind IN('difesa','nessuna'));
 END IF;
 IF is_master THEN
   SELECT coalesce(jsonb_agg(jsonb_build_object('actor_id',a.id,
      'action_due',NOT EXISTS(SELECT 1 FROM public.combat_v2_declarations d
         WHERE d.round_id=r.id AND d.actor_id=a.id AND d.kind IN('attacco','movimento','utilita','passa')))
      ORDER BY a.initiative_snapshot DESC,a.id),'[]'::jsonb) INTO slots
   FROM public.combat_v2_actors a
   WHERE a.id=ANY(w.expected_actor_ids) AND a.session_id=s.id
     AND a.actor_kind='png' AND a.state='attivo';
 END IF;
 RETURN jsonb_build_object('schema_version','regia-round-publication-state/1',
   'status','ready','activity_id',m.id,'actor_id',p_actor,
   'public',jsonb_build_object('schema_version','regia-round-public/1',
      'window_id',pw.round_id,'public_round_id',pw.round_id,
      'publication_id',pw.publication_id,
      'publication_revision',coalesce(b.run_control_version,m.control_version),
      'context_version',m.control_version,
      'permissions',jsonb_build_object('main',can_main,'defense',can_defend,'reaction',can_defend),
      'reason_code',CASE WHEN w.publication_id IS NULL THEN 'regia_fato_pending' ELSE NULL END),
   'master',CASE WHEN NOT is_master THEN NULL ELSE jsonb_build_object(
      'schema_version','regia-round-preparation/1',
      'window_id',coalesce(hw.id,w.round_id),
      'source_round_id',CASE WHEN private_hw THEN hw.source_round_id
         WHEN r.state='risolto' THEN r.id ELSE b.source_round_id END,
      'source_report_id',CASE WHEN private_hw THEN hw.source_report_id
         WHEN r.state='risolto' THEN
         (SELECT id FROM public.combat_v2_round_reports WHERE round_id=r.id)
         ELSE b.source_report_id END,
      'source_report_sha256',CASE WHEN private_hw THEN hw.source_report_sha256
         ELSE report.mechanics_sha256 END,'next_round_id',w.round_id,
      'preparation_revision',CASE WHEN private_hw THEN hw.preparation_revision
         WHEN r.state='risolto'
         THEN m.control_version ELSE coalesce(hw.preparation_revision,m.control_version) END,
      'control_version',m.control_version,
      'side',w.side,'legal_png_slots',slots,
      'state',CASE WHEN w.publication_id IS NOT NULL THEN 'published' ELSE 'private' END,
      'can_prepare',hw.id IS NOT NULL AND w.publication_id IS NOT NULL
        AND r.state='risolto' AND EXISTS(SELECT 1 FROM public.combat_v2_round_reports qr
          WHERE qr.round_id=r.id AND qr.narration_state='attesa'),
      'direction_context',mission_generic_owner.regia_human_direction_context_v1(m.id),
      'can_publish',hw.id IS NOT NULL AND hw.state='private'
       AND (hw.side='pg' OR NOT EXISTS(SELECT 1 FROM unnest(w.expected_actor_ids) actor(id)
         WHERE NOT EXISTS(SELECT 1 FROM combat_panel_private.actor_turns turn_row
          WHERE turn_row.round_id=r.id AND turn_row.actor_id=actor.id
            AND turn_row.main_declaration_id IS NOT NULL)))) END);
END $function$;


CREATE OR REPLACE FUNCTION combat_panel_private.commit_master_actor(p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p jsonb; uid uuid:=exam_regia_private.current_principal(); key uuid; fp text; receipt_id uuid:=gen_random_uuid();
 prior combat_panel_private.request_receipts%ROWTYPE; o combat_panel_private.offers%ROWTYPE;
 c combat_panel_private.contexts%ROWTYPE; a public.combat_v2_actors%ROWTYPE;
 env jsonb; resolved jsonb; selected uuid[]; payload jsonb; intent jsonb; result jsonb; receipt jsonb;
 targets uuid[]:='{}'; coverages uuid[]:='{}'; primary_attack uuid; movement uuid; substitution uuid;
  rotation_radius integer; fireball_selection jsonb; declaration uuid; label text; target_label text; event jsonb; dispatch text; flow_allocations jsonb:='[]';
  human_stage boolean:=false;intent_stage boolean:=false; ack_context_version bigint;
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'panel_authentication_required' USING ERRCODE='28000'; END IF;
 p:=combat_panel_private.validate_command(p_command); key:=(p->>'request_key')::uuid; fp:=public.combat_v2_sha256(p);
 PERFORM pg_advisory_xact_lock(hashtextextended('panel-request:'||uid::text||':'||key::text,731));
 SELECT * INTO prior FROM combat_panel_private.request_receipts WHERE principal_user=uid AND request_key=key;
 IF prior.request_key IS NOT NULL THEN
   IF prior.command_fingerprint<>fp THEN RAISE EXCEPTION 'panel_request_key_conflict' USING ERRCODE='22023'; END IF;
   RETURN jsonb_set(prior.viewer_envelope,'{receipt,replayed}','true',false);
 END IF;
 SELECT * INTO o FROM combat_panel_private.offers WHERE id=(p->>'offer_id')::uuid AND principal_user=uid;
 IF o.id IS NULL OR o.source_payload->>'adapter' IS DISTINCT FROM 'master_v2'
   OR o.kind NOT IN ('action','defense') THEN RAISE EXCEPTION 'panel_offer_not_available' USING ERRCODE='42501'; END IF;
 -- Preserve historical idempotent receipts; reject only new commits of stale passive attacks.
 IF o.source_payload->>'dispatch'='action' AND o.source_payload->>'kind'='attacco'
   AND o.source_payload->>'ability_source'='clan'
   AND o.source_payload->>'ability_id'='4056f62d-77f3-47f9-8ecb-9a7799682a9d' THEN
   RAISE EXCEPTION 'panel_passive_ability_not_attack' USING ERRCODE='22023'; END IF;
 SELECT * INTO STRICT c FROM combat_panel_private.contexts WHERE id=o.context_id AND principal_user=uid;
 IF c.activity_kind<>'master_v2' OR c.round_id IS NULL
   OR c.location_id IS DISTINCT FROM (p->>'location_id')::uuid OR c.activity_id IS DISTINCT FROM (p->>'activity_id')::uuid THEN
   RAISE EXCEPTION 'panel_activity_scope_invalid' USING ERRCODE='22023'; END IF;
 PERFORM public.combat_v2_lock_round(c.round_id);
 env:=combat_panel_private.master_projection(c.location_id,c.command_actor_id);
 PERFORM 1 FROM combat_panel_private.contexts WHERE id=c.id FOR UPDATE;
 c:=combat_panel_private.owned_context(c.id,(p->>'context_version')::bigint);
 SELECT * INTO STRICT o FROM combat_panel_private.offers WHERE id=o.id FOR UPDATE;
 IF o.state<>'offered' OR o.context_version<>c.context_version OR o.source_fingerprint IS DISTINCT FROM c.source_fingerprint
   OR o.scene_version IS DISTINCT FROM c.scene_version OR o.actor_id IS DISTINCT FROM c.command_actor_id THEN
   RAISE EXCEPTION 'panel_offer_not_available' USING ERRCODE='40001'; END IF;
 IF o.requires_role AND length(btrim(p->>'narrative_text'))=0 THEN RAISE EXCEPTION 'panel_role_required' USING ERRCODE='22023'; END IF;
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=o.actor_id AND session_id=c.activity_id
   AND exam_regia_private.actor_principal(id,controller_user)=uid AND companion_id IS NULL AND state='attivo' FOR UPDATE;
 SELECT coalesce(array_agg(value::uuid),'{}') INTO selected FROM jsonb_array_elements_text(p->'selected_option_ids');
 resolved:=combat_panel_private.resolve_selections(o.id,selected,p->'inputs');
 FOR payload IN SELECT choice->'payload' FROM jsonb_array_elements(resolved->'groups') AS groups(g)
   CROSS JOIN LATERAL jsonb_array_elements(g->'options') AS choices(choice) LOOP
   IF payload ? 'rotation_radius_m' THEN
     IF rotation_radius IS NOT NULL THEN RAISE EXCEPTION 'rotation_selection_duplicate';END IF;
     rotation_radius:=(payload->>'rotation_radius_m')::integer;
   END IF;
   IF payload ? 'fireball_selection' THEN
     IF fireball_selection IS NOT NULL THEN RAISE EXCEPTION 'fireball_selection_conflict';END IF;
     fireball_selection:=payload->'fireball_selection';
   END IF;
   IF payload ? 'attack_target_id' THEN
     coverages:=array_append(coverages,(payload->>'attack_target_id')::uuid);
     primary_attack:=coalesce(primary_attack,(payload->>'attack_declaration_id')::uuid);
   ELSIF payload ? 'target_actor_id' THEN targets:=array_append(targets,(payload->>'target_actor_id')::uuid);
   END IF;
   IF o.source_payload#>>'{sabaku_flow,version}'='sabaku-flow/2' AND payload ? 'target_actor_id' THEN
     IF NOT payload ? 'flow_count' THEN RAISE EXCEPTION 'sabaku_flow_quantity_required' USING ERRCODE='22023'; END IF;
     flow_allocations:=flow_allocations||jsonb_build_array(jsonb_build_object(
       'target_actor_id',payload->'target_actor_id','flows',payload->'flow_count'));
   END IF;
   IF payload ? 'movement_capability_id' THEN
     IF movement IS NOT NULL THEN RAISE EXCEPTION 'panel_movement_selection_conflict' USING ERRCODE='22023'; END IF;
     movement:=(payload->>'movement_capability_id')::uuid;
   END IF;
   IF payload ? 'substitution_option_id' THEN
     IF substitution IS NOT NULL THEN RAISE EXCEPTION 'panel_substitution_selection_conflict' USING ERRCODE='22023'; END IF;
     substitution:=(payload->>'substitution_option_id')::uuid;
   END IF;
  END LOOP;
  -- Only the Master-controlled PNG may stage privately. PG declarations and
  -- defenses continue through the published window and native controller checks.
  IF a.actor_kind='png' THEN
   PERFORM mission_generic_owner.regia_human_stage_permit_v1(c.round_id,a.id,key);
  END IF;
  -- The human permit is bound to this offer, actor and request in the same TX.
  -- Native context/offer and controller versions were checked above under lock.
  SELECT EXISTS(SELECT 1
    FROM mission_generic_owner.regia_human_stage_permits_v1 hp
    JOIN mission_generic_owner.regia_human_windows_v1 hw
      ON hw.next_round_id=hp.round_id AND hw.master_session_id=hp.master_session_id
    JOIN mission_generic_owner.unified_round_windows uw
      ON uw.round_id=hp.round_id AND uw.batch_id=hw.batch_id
       AND uw.master_session_id=hw.master_session_id
    JOIN public.combat_v2_sessions cs ON cs.id=c.activity_id
       AND cs.master_session_id=hw.master_session_id
    JOIN public.master_v2_sessions ms ON ms.id=hw.master_session_id
    WHERE hp.round_id=c.round_id AND hp.actor_id=a.id AND hp.request_key=key
      AND hp.principal_id=uid AND hp.transaction_id=txid_current()
      AND hp.backend_pid=pg_backend_pid()
      AND hw.encounter_id=cs.id AND a.session_id=cs.id AND a.actor_kind='png'
      AND ms.owner_kind='human' AND ms.closed_at IS NULL
      AND ms.master_user=uid
      AND ms.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
      AND ((hw.state='private' AND hw.side='png' AND uw.side='png'
            AND uw.publication_id IS NULL AND o.operation='declare'
            AND a.id=ANY(uw.expected_actor_ids))
        OR (hw.state='published' AND hw.side='pg' AND uw.side='pg'
            AND uw.publication_id IS NOT NULL AND o.operation='defend'
            AND o.kind='defense')))
    INTO human_stage;
  intent_stage:=auth.uid() IS NULL AND public.combat_v2_is_service() AND a.actor_kind='png'
   AND o.kind='action' AND o.operation='declare' AND o.source_payload->>'dispatch'='action' AND o.source_payload->>'kind'='passa'
   AND mission_generic_owner.unified_service_staging(c.round_id) AND EXISTS(SELECT 1 FROM mission_generic_owner.unified_round_windows uw
     JOIN mission_generic_owner.unified_batches b ON b.id=uw.batch_id JOIN mission_generic_owner.unified_publication_permits pp ON pp.batch_id=b.id AND pp.work_id=b.writer_work_id
     WHERE uw.round_id=c.round_id AND uw.publication_id IS NULL AND a.id=ANY(uw.expected_actor_ids) AND b.retired_at IS NULL
       AND pp.transaction_id=txid_current() AND pp.backend_pid=pg_backend_pid() AND mission_generic_owner.native_intent_work_v1(b.writer_work_id));
  PERFORM mission_generic_owner.unified_assert_command(c.round_id,CASE WHEN o.kind='defense' THEN 'defend' ELSE 'declare' END);
 dispatch:=o.source_payload->>'dispatch';
 IF dispatch IN ('action','movement') THEN
   IF o.source_payload->>'fireball'='true' THEN
     IF fireball_selection IS NULL THEN RAISE EXCEPTION 'fireball_selection_required';END IF;
     intent:=clan_uchiha_private.fireball_prepare(c.round_id,a.id,key,fireball_selection);
     SELECT coalesce(array_agg(value::uuid),'{}') INTO targets FROM jsonb_array_elements_text(coalesce(intent->'target_actor_ids','[]'));
   ELSE
   intent:=jsonb_build_object('kind',o.source_payload->'kind');
   IF intent->>'kind'='attacco' THEN
     IF cardinality(targets)=0 THEN RAISE EXCEPTION 'panel_target_required' USING ERRCODE='22023'; END IF;
     intent:=intent||jsonb_build_object('target_actor',targets[1],'target_actor_ids',targets,
       'ability_source',o.source_payload->'ability_source');
     IF o.source_payload ? 'ability_id' THEN intent:=intent||jsonb_build_object('ability_id',o.source_payload->'ability_id'); END IF;
   ELSIF intent->>'kind'='utilita' AND o.source_payload->>'aburame_escape'='true' THEN
     intent:=intent||jsonb_build_object('ability_source','clan','ability_id','f5e9af24-70f1-49f6-a7ca-74f59256336e');
   ELSIF dispatch='movement' THEN
     IF movement IS NULL THEN RAISE EXCEPTION 'panel_movement_required' USING ERRCODE='22023'; END IF;
   END IF;
   IF movement IS NOT NULL THEN
     IF dispatch='movement' THEN
       PERFORM combat_panel_private.prepare_master_movement(c.round_id,a.id,movement,key);
     ELSIF dispatch='action' AND intent->>'kind'='attacco' AND cardinality(targets)=1
       AND (coalesce(intent->>'ability_source','mano')='mano' OR (intent->>'ability_source'='clan' AND intent->>'ability_id' IN ('9ac77d79-9894-5388-9753-70538ac5eaa3','b076a976-c75b-4b5a-8813-b0e8e2c3af03')))
       AND combat_panel_private.movement_attack_target_valid(a.id,targets[1],movement,CASE WHEN intent->>'ability_source'='clan' THEN 2 ELSE combat_panel_private.manual_contact_center_range(a.id,targets[1]) END)
       AND (intent->>'ability_source'<>'clan' OR intent->>'ability_id'='b076a976-c75b-4b5a-8813-b0e8e2c3af03' OR (SELECT combat_spatial.distance_m(start_x_m,start_y_m,end_x_m,end_y_m)>=5 FROM combat_spatial.movement_capabilities WHERE capability_id=movement)) THEN
       PERFORM combat_panel_private.prepare_master_movement(c.round_id,a.id,movement,key);
     ELSE
       RAISE EXCEPTION 'panel_movement_attack_selection_invalid' USING ERRCODE='22023';
     END IF;
   END IF;
   END IF;
   IF intent->>'kind'='attacco' AND fireball_selection IS NULL THEN
     PERFORM combat_panel_private.multiplication_prepare_selected_aims(c.round_id,a.id,key,targets,resolved);
   END IF;
   IF o.source_payload#>>'{sabaku_flow,version}'='sabaku-flow/2' THEN
     IF movement IS NOT NULL OR dispatch<>'action' OR intent->>'kind'<>'attacco' THEN
       RAISE EXCEPTION 'sabaku_flow_offer_invalid' USING ERRCODE='22023'; END IF;
     -- Il totale e' congelato nell'offerta nativa, mai ricevuto come valore libero dal client.
     IF jsonb_typeof(o.source_payload#>'{sabaku_flow,quantity}') IS DISTINCT FROM 'number'
       OR (o.source_payload#>>'{sabaku_flow,quantity}') !~ '^[1-3]$' THEN
       RAISE EXCEPTION 'sabaku_flow_total_required' USING ERRCODE='22023'; END IF;
     IF (clan_sabaku_private.flow_costs(1,flow_allocations)->>'flows')::integer
       IS DISTINCT FROM (o.source_payload#>>'{sabaku_flow,quantity}')::integer THEN
       RAISE EXCEPTION 'sabaku_flow_total_allocation_mismatch' USING ERRCODE='22023'; END IF;
     PERFORM clan_sabaku_private.flow_prepare(c.round_id,a.id,key,o.id,'panel',flow_allocations);
   END IF;
   IF intent->>'ability_source'='clan' AND combat_v2_elemental_internal.suiton_profile(a.id,(intent->>'ability_id')::uuid) IS NOT NULL THEN
     PERFORM combat_v2_elemental_internal.suiton_prepare_callback('master_v2',o.id,a.id,key,
       ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(p->'selected_option_ids')),p->'inputs',intent);
   END IF;
   IF intent->>'ability_source'='clan' AND combat_v2_elemental_internal.other_profile(a.id,(intent->>'ability_id')::uuid) IS NOT NULL THEN
     PERFORM combat_v2_elemental_internal.other_prepare_callback('master_v2',o.id,a.id,key,ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(p->'selected_option_ids')),p->'inputs',intent);
   END IF;
   result:=public.combat_v2_action_declare(c.round_id,a.id,intent,p->>'narrative_text',key);
   declaration:=(result#>>'{data,declaration_id}')::uuid;
 ELSIF dispatch='defense' THEN
   IF cardinality(coverages)=0 OR primary_attack IS NULL THEN RAISE EXCEPTION 'panel_coverage_required' USING ERRCODE='22023'; END IF;
   intent:=jsonb_build_object('reaction',o.source_payload->'reaction','attack_target_ids',coverages);
   IF o.source_payload ? 'ability_id' THEN intent:=intent||jsonb_build_object(
     'ability_source',o.source_payload->'ability_source','ability_id',o.source_payload->'ability_id'); END IF;
   IF o.source_payload->>'rotation_version'='hyuga-rotation/1' THEN
     PERFORM clan_hyuga_private.rotation_prepare(c.round_id,a.id,primary_attack,key,rotation_radius);
   END IF;
   IF o.source_payload->>'aburame_clone'='aburame-clone/1' THEN
     IF primary_attack IS DISTINCT FROM (o.source_payload->>'attack_id')::uuid THEN RAISE EXCEPTION 'aburame_clone_attack_drift';END IF;
     PERFORM clan_aburame_private.clone_prepare(c.round_id,a.id,primary_attack,key,(o.source_payload->>'movement_capability')::uuid);
   END IF;
   result:=public.combat_v2_defense_declare(c.round_id,primary_attack,a.id,intent,p->>'narrative_text',key);
   declaration:=(result#>>'{data,defense_id}')::uuid;
 ELSIF dispatch='substitution' THEN
   IF substitution IS NULL THEN RAISE EXCEPTION 'panel_substitution_required' USING ERRCODE='22023'; END IF;
   PERFORM clan_marionettisti_private.assert_jutsu_source(a.id,'jutsu','31b15861-fb78-4f8a-ac1c-ebf2d957c32e');
   IF EXISTS(SELECT 1 FROM combat_spatial.request_receipts WHERE request_key=key) THEN
     RAISE EXCEPTION 'panel_request_key_conflict' USING ERRCODE='22023'; END IF;
   result:=public.combat_v2_substitution_select_v1(substitution,key);
   declaration:=(result->>'defense_declaration_id')::uuid;
   -- Il selector vivo crea il testo vuoto. Completa solo la dichiarazione
   -- appena creata, ancora inviata e controllata, nella stessa transazione.
   UPDATE public.combat_v2_declarations SET declaration_text=p->>'narrative_text'
     WHERE id=declaration AND round_id=c.round_id AND actor_id=a.id AND request_key=key
       AND controller_user_snapshot=uid AND state='inviata' AND declaration_text='';
   IF NOT FOUND THEN RAISE EXCEPTION 'panel_substitution_declaration_invalid' USING ERRCODE='22023'; END IF;
 ELSE RAISE EXCEPTION 'panel_dispatch_not_available' USING ERRCODE='22023'; END IF;
 IF declaration IS NULL THEN RAISE EXCEPTION 'panel_source_receipt_invalid' USING ERRCODE='22023'; END IF;
  IF o.operation='defend' THEN
    PERFORM combat_panel_private.multiplication_register_defense_selections(c.round_id,a.id,key,resolved,declaration); END IF;
  IF a.actor_kind='png' AND EXISTS(SELECT 1 FROM mission_generic_owner.unified_round_windows uw WHERE uw.round_id=c.round_id) THEN
     IF NOT (mission_generic_owner.unified_service_staging(c.round_id) OR human_stage)
     THEN RAISE EXCEPTION 'MUF_STAGING_AUTHORITY_REQUIRED' USING ERRCODE='42501'; END IF;
    UPDATE public.combat_v2_declarations d SET controller_user_snapshot=uid
    FROM public.combat_v2_provider_instances_v1 pi
    WHERE d.id=declaration AND d.round_id=c.round_id AND d.actor_id=a.id AND d.request_key=key
       AND (d.state='inviata' OR ((human_stage OR(intent_stage AND d.kind='passa' AND result#>>'{data,declaration_id}'=d.id::text AND result#>>'{data,phase}'='risolto' AND result#>'{data,auto_resolution}' IS NOT NULL AND result#>'{data,auto_resolution}'<>'null'::jsonb)) AND d.state='risolta'
         AND d.kind IN('utilita','movimento','passa','difesa','nessuna')))
       AND d.declaration_text=coalesce(p->>'narrative_text','')
      AND d.controller_version_snapshot=a.controller_version
      AND pi.id=a.provider_instance_v1_id AND pi.session_id=a.session_id
      AND d.controller_user_snapshot=pi.narrative_version_ref;
    IF NOT FOUND AND NOT EXISTS(SELECT 1 FROM public.combat_v2_declarations d
      WHERE d.id=declaration AND d.round_id=c.round_id AND d.actor_id=a.id AND d.request_key=key
        AND d.state IN ('inviata','risolta') AND d.declaration_text=coalesce(p->>'narrative_text','')
        AND d.controller_version_snapshot=a.controller_version AND d.controller_user_snapshot=uid)
    THEN RAISE EXCEPTION 'MG_DECLARATION_AUTHORITY_INVALID' USING ERRCODE='42501'; END IF;
  END IF;
  -- Solo Passa nativo senza role: l'offerta effettiva è attestata prima del publisher
 -- nella stessa TX. La receipt finale segue normalmente; ogni errore annulla tutto.
 IF a.actor_kind='png' AND NOT o.requires_role AND o.kind='action' AND o.operation='declare'
   AND o.source_payload->>'kind'='passa' AND intent->>'kind'='passa'
    AND nullif(btrim(p->>'narrative_text'),'') IS NULL
    AND EXISTS(SELECT 1 FROM mission_generic_owner.unified_round_windows uw WHERE uw.round_id=c.round_id) THEN
    IF NOT (mission_generic_owner.unified_service_staging(c.round_id) OR human_stage) OR NOT EXISTS(
     SELECT 1 FROM public.combat_v2_declarations pd WHERE pd.id=declaration AND pd.round_id=c.round_id
       AND pd.actor_id=a.id AND pd.request_key=key AND pd.kind='passa'
       AND (pd.state='inviata' OR (pd.state='risolta' AND human_stage
          AND result#>>'{data,declaration_id}'=pd.id::text
          AND result#>>'{data,phase}'='risolto'
          AND result#>'{data,auto_resolution}' IS NOT NULL
          AND result#>'{data,auto_resolution}'<>'null'::jsonb))
       AND pd.controller_user_snapshot=uid AND pd.controller_version_snapshot=a.controller_version
       AND pd.declaration_text=coalesce(p->>'narrative_text','')) THEN
     RAISE EXCEPTION 'MUF_ROLELESS_PASS_SCOPE' USING ERRCODE='42501'; END IF;
   UPDATE combat_panel_private.offers SET state='consumed',consumed_request_key=key
     WHERE id=o.id AND principal_user=uid AND context_id=c.id AND actor_id=a.id AND state='offered';
   IF NOT FOUND THEN RAISE EXCEPTION 'MUF_ROLELESS_PASS_OFFER' USING ERRCODE='40001'; END IF;
 END IF;
 PERFORM combat_panel_private.publish_master_declaration(declaration,p->>'narrative_text');
 SELECT value->>'display_name' INTO label FROM jsonb_array_elements(env->'actors') WHERE value->>'actor_id'=a.id::text;
 IF cardinality(targets)>0 THEN
   SELECT value->>'display_name' INTO target_label FROM jsonb_array_elements(env->'actors') WHERE value->>'actor_id'=targets[1]::text;
 END IF;
 event:=jsonb_build_object('event_id',receipt_id,'event_kind','action_declared','actor_id',a.id,'display_name',label,
   'label_version',c.context_version,'target_actor_id',CASE WHEN target_label IS NOT NULL THEN targets[1] END,
   'target_display_name',target_label,'target_label_version',CASE WHEN target_label IS NOT NULL THEN c.context_version END,
   'summary',CASE WHEN o.operation='defend' THEN 'Difesa registrata' ELSE 'Azione registrata' END);
 env:=combat_panel_private.master_projection(c.location_id,a.id);
 IF env->>'status'='blocked' AND env->>'reason_code'='REGIA_FATO_PENDING' THEN
  IF a.actor_kind<>'pg' OR o.kind<>'action' OR o.operation<>'declare'
   OR NOT mission_narrative_internal.scene_native_round_bound_v1(
      (SELECT master_session_id FROM public.combat_v2_sessions WHERE id=c.activity_id),c.round_id)
   OR NOT EXISTS(SELECT 1 FROM public.combat_v2_declarations accepted
     JOIN public.combat_v2_rounds rr ON rr.id=accepted.round_id AND rr.session_id=c.activity_id
     JOIN public.combat_v2_round_reports report ON report.id=rr.report_id AND report.round_id=rr.id
     JOIN public.combat_v2_events action_event ON action_event.scope_id=rr.id
      AND action_event.request_key=accepted.request_key AND action_event.operation_kind='combat_v2_action_declare'
     WHERE accepted.id=declaration AND accepted.round_id=c.round_id AND accepted.actor_id=a.id
      AND accepted.kind IN('attacco','utilita','movimento','passa') AND accepted.state='risolta'
      AND accepted.request_key=key AND accepted.controller_user_snapshot=uid
      AND accepted.controller_version_snapshot=a.controller_version
      AND accepted.declaration_text=coalesce(p->>'narrative_text','')
      AND action_event.status='completata' AND action_event.caller=uid
      AND action_event.result=result AND result#>>'{data,declaration_id}'=accepted.id::text
      AND result#>>'{data,phase}'='risolto'
      AND result#>>'{data,auto_resolution,data,report_id}'=report.id::text
      AND rr.state='risolto' AND report.narration_state='attesa' AND NOT report.values_written
      AND report.mechanics_sha256=public.combat_v2_sha256(report.mechanics))
  THEN RAISE EXCEPTION 'NATIVE_PENDING_ACK_SCOPE' USING ERRCODE='42501';END IF;
  -- A public frame has not been projected. Report the real retained panel
  -- context version, not a synthetic increment or a version from private data.
  SELECT context_version INTO STRICT ack_context_version FROM combat_panel_private.contexts
   WHERE id=c.id AND principal_user=uid AND command_actor_id=a.id
    AND activity_id=c.activity_id AND round_id=c.round_id AND location_id=c.location_id;
  IF ack_context_version<o.context_version THEN RAISE EXCEPTION 'NATIVE_PENDING_ACK_VERSION' USING ERRCODE='40001';END IF;
 ELSE
  ack_context_version:=(env#>>'{context,version}')::bigint;
 END IF;
 receipt:=jsonb_build_object('receipt_id',receipt_id,'request_key',key,'operation',o.operation,'replayed',false,
   'activity_id',c.activity_id,'round_id',c.round_id,'context_version_before',o.context_version,
   'context_version_after',ack_context_version,'declaration_id',declaration,'report_id',NULL,
   'values_written',false,'display_events',jsonb_build_array(event));
 env:=jsonb_set(env,'{receipt}',receipt);
 UPDATE combat_panel_private.offers SET state='consumed',consumed_request_key=key WHERE id=o.id;
 INSERT INTO combat_panel_private.request_receipts(principal_user,request_key,command_fingerprint,offer_id,event_id,viewer_envelope)
   VALUES(uid,key,fp,o.id,receipt_id,env);
 RETURN env;
END $function$;

