 'acl',p.proacl::text,'config',to_jsonb(p.proconfig),'secdef',p.prosecdef,'language',l.lanname,
 'volatility',p.provolatile::text,'source_md5',pg_catalog.md5(p.prosrc),'ddl_md5',pg_catalog.md5(pg_catalog.pg_get_functiondef(p.oid)))
 INTO actual FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_language l ON l.oid=p.prolang WHERE p.oid=pg_catalog.to_regprocedure(sig);
 IF actual IS DISTINCT FROM h THEN RAISE EXCEPTION 'C64_FINAL_HEADER_DRIFT %',sig;END IF;END LOOP;
 IF octet_length(candidate)>262144 OR strpos(candidate,'__C64_')>0 THEN RAISE EXCEPTION 'C64_ROOT_UNMATERIALIZED';END IF;
 WITH scopes AS (SELECT unnest(ARRAY['1fb789a2-0319-435f-9f6d-dd517cac7cd3','4c7b05e0-b5b7-4586-9aa9-2a77ae03deb4','7c301c10-5a0e-42d8-92b3-cee6fc4171e6','93053f1e-7a4e-4ed9-b73c-df8bae2c361e','8281f278-c198-424f-a2b2-63b76812c1f3','c2faf883-5264-44e3-b1a2-bd9a39876942']::uuid[]) AS id), msgids AS(SELECT DISTINCT message_id FROM mission_generic_owner.work_items WHERE master_session_id IN(SELECT id FROM scopes) AND message_id IS NOT NULL)
SELECT jsonb_build_object('fati_count',(SELECT count(*) FROM public.messages WHERE id IN(SELECT message_id FROM msgids)),
 'fati_sha',(SELECT public.combat_v2_sha256(jsonb_agg(jsonb_build_object('id',id,'body',body) ORDER BY id)) FROM public.messages WHERE id IN(SELECT message_id FROM msgids)),
 'roles_sha',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(t) ORDER BY master_session_id,submission_order)) FROM mission_generic_owner.role_submissions t WHERE master_session_id IN(SELECT id FROM scopes)),
 'sessions_sha',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(t) ORDER BY id)) FROM public.master_v2_sessions t WHERE id IN(SELECT id FROM scopes)),
 'bindings_sha',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(t) ORDER BY master_session_id)) FROM mission_generic_owner.run_bindings t WHERE master_session_id IN(SELECT id FROM scopes)),
 'work_sha',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(t) ORDER BY id)) FROM mission_generic_owner.work_items t WHERE master_session_id IN(SELECT id FROM scopes)),
 'quota_sha',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(t) ORDER BY id)) FROM staff_ai_quota_private.calls t WHERE scope_id IN(SELECT id FROM scopes)),
 'scenes_sha',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(t) ORDER BY id)) FROM mission_narrative_internal.scene_runtime_v1 t WHERE master_session_id IN(SELECT id FROM scopes)),
 'gameplay_sha',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(t)-ARRAY['updated_at','last_regen_at','avatar_url','banner_url','music_url','off_notes'] ORDER BY id)) FROM public.characters t WHERE id IN('6bceee99-974f-426b-8d92-38b43b4a4267','f335b077-34a1-41c3-94aa-58ec674b649b'))) INTO after_data;

SELECT jsonb_build_object('failed_writers',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(fw) ORDER BY id)) FROM mission_generic_owner.work_items fw WHERE fw.id IN('3cecb7a6-2331-45e8-bf1a-b53feb1b351a','203b64e2-e0f3-d871-317c-0ebf87d4a697')),'reports',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(rp) ORDER BY id)) FROM public.combat_v2_round_reports rp WHERE rp.round_id IN(SELECT id FROM public.combat_v2_rounds WHERE session_id='b3135a23-78c5-4c45-a730-b1de8257367b')),'defense_publication',(SELECT public.combat_v2_sha256(to_jsonb(dm)) FROM public.messages dm WHERE dm.id='a74fdfe9-4974-44c6-b066-cdd7fe04feaa'),'rounds',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(x) ORDER BY id)) FROM public.combat_v2_rounds x WHERE session_id='b3135a23-78c5-4c45-a730-b1de8257367b'),'actors',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(x) ORDER BY id)) FROM public.combat_v2_actors x WHERE session_id='b3135a23-78c5-4c45-a730-b1de8257367b'),'declarations',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(x) ORDER BY id)) FROM public.combat_v2_declarations x WHERE round_id IN(SELECT id FROM public.combat_v2_rounds WHERE session_id='b3135a23-78c5-4c45-a730-b1de8257367b')),'events',(SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(x) ORDER BY event_version,event_key)) FROM mission_generic_owner.event_outbox_v1 x WHERE master_session_id='c2faf883-5264-44e3-b1a2-bd9a39876942')) INTO after_data_combat;
 IF (SELECT count(*) FROM pg_constraint WHERE conrelid='mission_narrative_internal.scene_sources_v1'::regclass AND conname IN('scene_sources_v1_request_kind_check','scene_sources_v1_check') AND contype='c' AND convalidated AND pg_get_constraintdef(oid) LIKE '%combat_intent%')<>2 THEN RAISE EXCEPTION 'C64_CONSTRAINT_POST_DRIFT';END IF;
 SELECT * INTO STRICT prior FROM c64_preservation;
 IF after_data IS DISTINCT FROM prior.before_data OR after_data_combat IS DISTINCT FROM prior.before_combat THEN RAISE EXCEPTION 'C64_HISTORY_OR_GAMEPLAY_MUTATED';END IF;
 new_sha:=encode(extensions.digest(convert_to(candidate,'UTF8'),'sha256'),'hex');
 UPDATE mission_factory_owner.editor_release_readiness SET canonical_preimage=candidate,revision_sha256=new_sha,observed_revision_sha256=new_sha,client_build='mission-factory-admin/2:'||new_sha,independent_review_ref='C1266_COMBAT64_REVIEW.json',updated_at=clock_timestamp() WHERE singleton AND revision_sha256='71bb950bc0b876d560271c96003c7be8a38f1d8f207326447026355ef1eb1132';
 IF NOT FOUND THEN RAISE EXCEPTION 'C64_ROOT_CAS_LOST';END IF;
END $c64post$;
COMMIT;
